// Inventory
// Stock Receipt — a master/detail resource (StockReceipt has many
// StockReceiptItem rows), same bespoke-route pattern as /sales/delivery-challans
// above. Items carry a batch no. and expiry date but no tax or discount —
// this is an internal stock movement document, not a tax invoice — so the
// total is simply the sum of item amounts (qty * rate).
const stockReceiptInclude = {
  items: {
    orderBy: { id: 'asc' },
    include: {
      batches: { orderBy: { id: 'asc' } },
      serials: { orderBy: { id: 'asc' } },
    },
  },
};

// `header` carries the receipt's warehouse — stamped onto every batch/serial
// row this line creates via buildBatchSerialCreates, same as the GRN side
// (see toGrnItemData above; buildBatchSerialCreates/toBatchCreateData/
// toSerialCreateData are shared between both document types).
function toStockReceiptItemData(item, header) {
  const quantity = Number(item.quantity) || 0;
  const unitPrice = Number(item.unitPrice) || 0;
  return {
    productCode: item.productCode || null,
    productName: item.productName || null,
    hsnCode: item.hsnCode || null,
    batchNo: item.batchNo || null,
    expiryDate: item.expiryDate || null,
    // Per-line Warehouse — line-first, falling back to the document's header
    // Warehouse only when a line leaves it blank (legacy rows saved before
    // this column existed). Same convention as toGrnItemData's warehouse.
    warehouse: item.warehouse || header.warehouse || null,
    uom: item.uom || null,
    quantity,
    unitPrice,
    amount: round2(quantity * unitPrice),
    ...buildBatchSerialCreates(item, header),
  };
}

function computeStockReceiptTotals(items) {
  // Rounded to paise: the raw float sum is what made stock valuation
  // reports disagree with the documents they are built from.
  return { amount: round2(items.reduce((sum, i) => sum + round2(i.amount), 0)) };
}

router.get('/inventory/stock-receipts', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { receiptNo: { contains: q } },
        { referenceNo: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.stockReceipt.findMany({ where: withBranchScope(where, req), include: stockReceiptInclude, orderBy: { id: 'desc' } });
  await attachJournalEntryRefs(rows, JOURNAL_SOURCE_TYPES.STOCK_RETURN, 'receiptNo');
  res.json({ success: true, data: rows });
}));

router.get('/inventory/stock-receipts/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.stockReceipt.findUnique({ where: { id: Number(req.params.id) }, include: stockReceiptInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  await attachJournalEntryRefs(row, JOURNAL_SOURCE_TYPES.STOCK_RETURN, 'receiptNo');
  res.json({ success: true, data: row });
}));

router.post('/inventory/stock-receipts', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue receiptNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { items = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  // Same Batch/Serial rules as Purchase GRN — see assertBatchSerialAllocation
  // in utils/businessRules.js. Batch uniqueness is scoped to the Stock
  // Receipt document itself (batchScope: 'stockReceipt'), same concept as
  // Purchase GRN's own 'grn' scope — see assertUniqueBatchesAndSerials's
  // doc comment.
  await assertBatchSerialAllocation(prisma, items, { quantityField: 'quantity' });
  await assertUniqueBatchesAndSerials(prisma, items, { defaultWarehouse: header.warehouse, batchScope: 'stockReceipt' });
  const itemData = items.map((item) => toStockReceiptItemData(item, header));
  const totals = computeStockReceiptTotals(itemData);
  const row = await prisma.$transaction(async (tx) => {
    // receiptNo now comes from the configured SRC numbering series rather
    // than free text — see resolveDocumentNumber above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('SRC', header.receiptNo, tx, seriesId || null);
    const created = await tx.stockReceipt.create({
      data: { ...header, receiptNo: documentNumber, ...totals, items: { create: itemData } },
      include: stockReceiptInclude,
    });
    if (syncManual) await syncManual();
    // Journal the movement into [dbo].[Stock] — inward, and only once the
    // receipt is Posted. See utils/stockTable.js.
    await postStockEntries(tx, {
      transType: TRANS_TYPES.STOCK_RECEIPT,
      transNum: created.id,
      documentNumber: created.receiptNo,
      status: created.status,
      warehouse: created.warehouse,
      branch: created.branch,
      lines: receiptLines(itemData),
      userId: req.user?.id,
    });
    // Dr Inventory / Cr Inventory Offset - Increase. Filed under the
    // 'Stock Return' transaction type: stock arriving with no purchase
    // behind it.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.STOCK_RETURN,
      sourceDocNo: created.receiptNo,
      status: created.status,
      doc: { ...created, items: itemData },
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/inventory/stock-receipts/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { items = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  // Same Batch/Serial rules as Purchase GRN — see assertBatchSerialAllocation
  // in utils/businessRules.js. Batch uniqueness is scoped to the Stock
  // Receipt document itself (batchScope: 'stockReceipt') — excludeStockReceiptId
  // means re-saving this receipt with its own previously-saved batch numbers
  // unchanged isn't flagged as colliding with itself.
  await assertBatchSerialAllocation(prisma, items, { quantityField: 'quantity' });
  await assertUniqueBatchesAndSerials(prisma, items, { excludeStockReceiptId: id, defaultWarehouse: header.warehouse, batchScope: 'stockReceipt' });
  const itemData = items.map((item) => toStockReceiptItemData(item, header));
  const totals = computeStockReceiptTotals(itemData);
  // Replace the item set wholesale on every save — simpler and safer than
  // diffing which rows were added/removed/reordered client-side.
  const row = await prisma.$transaction(async (tx) => {
    await tx.stockReceiptItem.deleteMany({ where: { receiptId: id } });
    const updated = await tx.stockReceipt.update({
      where: { id },
      data: { ...header, ...totals, items: { create: itemData } },
      include: stockReceiptInclude,
    });
    // A receipt saved as Draft and later Posted journals on that later save;
    // one already journalled is left alone (postStockEntries is insert-only
    // and posts a given document exactly once). See utils/stockTable.js.
    await postStockEntries(tx, {
      transType: TRANS_TYPES.STOCK_RECEIPT,
      transNum: updated.id,
      documentNumber: updated.receiptNo,
      status: updated.status,
      warehouse: updated.warehouse,
      branch: updated.branch,
      lines: receiptLines(itemData),
      userId: req.user?.id,
    });
    // Rebuild the accounting document from what this receipt now says.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.STOCK_RETURN,
      sourceDocNo: updated.receiptNo,
      status: updated.status,
      doc: { ...updated, items: itemData },
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/inventory/stock-receipts/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // Deleting the document deletes its accounting document too -- a
  // ledger entry for a document that no longer exists is worse than no
  // entry at all. See reverseJournalEntry in utils/glPosting.js.
  await removeJournalEntryForDocument(
    prisma, JOURNAL_SOURCE_TYPES.STOCK_RETURN, 'stockReceipt', 'receiptNo', Number(req.params.id)
  );
  // StockReceiptItem.receipt has onDelete: Cascade, so items go with it.
  const receiptId = Number(req.params.id);
  await prisma.$transaction(async (tx) => {
    // Reverse whatever this receipt posted to [dbo].[Stock] before it's
    // gone — deleting bypasses the cancel step that would otherwise have
    // done this. No-op if it never posted.
    await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_RECEIPT, transNum: receiptId, userId: req.user?.id });
    await tx.stockReceipt.delete({ where: { id: receiptId } });
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));
// Stock Issue — a master/detail resource (StockIssue has many
// StockIssueItem rows), same bespoke-route pattern as /inventory/stock-receipts
// above. Items carry a batch no. and expiry date; the unit rate isn't shown
// as an editable column in the mockup (it's valued at the product's cost
// price automatically), but is still stored per item so the total can be
// computed and the issue can be costed later.
const stockIssueInclude = { items: { orderBy: { id: 'asc' } } };

function toStockIssueItemData(item, header) {
  const quantity = Number(item.quantity) || 0;
  const unitPrice = Number(item.unitPrice) || 0;
  return {
    productCode: item.productCode || null,
    productName: item.productName || null,
    hsnCode: item.hsnCode || null,
    batchNo: item.batchNo || null,
    expiryDate: item.expiryDate || null,
    // Per-line Warehouse — line-first, falling back to the document's header
    // `toWarehouse` only when a line leaves it blank (legacy rows saved
    // before this column existed). Same convention as toGrnItemData's
    // warehouse. Used both for stock posting (see issueLines in
    // utils/stockTable.js) and for assertNoNegativeWarehouseStockFor below.
    warehouse: item.warehouse || header?.toWarehouse || null,
    uom: item.uom || null,
    quantity,
    unitPrice,
    amount: round2(quantity * unitPrice),
  };
}

function computeStockIssueTotals(items) {
  // Rounded to paise: the raw float sum is what made stock valuation
  // reports disagree with the documents they are built from.
  return { amount: round2(items.reduce((sum, i) => sum + round2(i.amount), 0)) };
}

