router.post('/inventory/stock-issues', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue issueNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { items = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const itemData = items.map((item) => toStockIssueItemData(item, header));
  const totals = computeStockIssueTotals(itemData);
  // A Batch/Serial-tracked line must SELECT existing batches/serials to
  // cover its quantity — the "Batches Number - Selection" / "Serial Numbers
  // - Selection" dialog. See assertBatchSerialIssueAllocation /
  // assertBatchSerialAvailability in utils/businessRules.js.
  await assertBatchSerialIssueAllocation(prisma, items, { quantityField: 'quantity' });
  await assertBatchSerialAvailability(prisma, items);
  const row = await prisma.$transaction(async (tx) => {
    // Non-inventory lines must not post to the stock ledger, nor be sized
    // against on-hand quantity below — see attachInventoryItemFlag.
    await attachInventoryItemFlag(tx, itemData);
    // issueNo now comes from the configured SIG numbering series rather
    // than free text — see resolveDocumentNumber above.
    // A despatch cannot take stock below zero — see assertNoNegativeStock.
    await assertNoNegativeStock(tx, itemData);
    // Every line's own selected Warehouse must have enough on hand too —
    // the company-wide check above can pass while one specific warehouse
    // still goes negative. See assertNoNegativeWarehouseStockFor.
    await assertNoNegativeWarehouseStockFor(tx, itemData, { label: 'the selected Warehouse' });
    const { documentNumber, syncManual } = await resolveDocumentNumber('SIG', header.issueNo, tx, seriesId || null);
    const created = await tx.stockIssue.create({
      data: { ...header, issueNo: documentNumber, ...totals, items: { create: stripInventoryFlag(itemData) } },
      include: stockIssueInclude,
    });
    if (syncManual) await syncManual();
    // Decrement the selected batches/serials and record the allocation —
    // see applyBatchSerialIssueEffects. Zipped against `items` (the raw
    // request lines) by position; created.items is ordered by id ascending,
    // the same order the lines were created in.
    await applyBatchSerialIssueEffects(tx, items, created.items, { linkField: 'stockIssueItemId' });
    // Journal the movement into [dbo].[Stock] — outward, and only once the
    // issue is Posted. See utils/stockTable.js.
    await postStockEntries(tx, {
      transType: TRANS_TYPES.STOCK_ISSUE,
      transNum: created.id,
      documentNumber: created.issueNo,
      status: created.status,
      warehouse: created.toWarehouse,
      branch: created.branch,
      lines: issueLines(itemData),
      userId: req.user?.id,
    });
    // Dr Inventory Offset - Decrease / Cr Inventory. Deliberately NOT COGS:
    // consumption that earned no revenue would distort gross margin.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.STOCK_ISSUE,
      sourceDocNo: created.issueNo,
      status: created.status,
      doc: { ...created, items: itemData },
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/inventory/stock-issues/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { items = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const itemData = items.map((item) => toStockIssueItemData(item, header));
  const totals = computeStockIssueTotals(itemData);
  // Same Batch/Serial "Selection" rules as create — excludeStockIssueId adds
  // this document's own existing selections back to the available pool
  // before comparing (see assertBatchSerialAvailability's own comment).
  await assertBatchSerialIssueAllocation(prisma, items, { quantityField: 'quantity' });
  await assertBatchSerialAvailability(prisma, items, { excludeStockIssueId: id });
  // Replace the item set wholesale on every save — simpler and safer than
  // diffing which rows were added/removed/reordered client-side.
  const row = await prisma.$transaction(async (tx) => {
    // Undo the stock effect of this document's CURRENT batch/serial
    // selections before its items (and their allocation rows) are replaced
    // — must run before the deleteMany below, since the allocation rows
    // cascade away with their item. See restoreBatchSerialIssueEffects.
    await restoreBatchSerialIssueEffects(tx, { stockIssueId: id });
    await tx.stockIssueItem.deleteMany({ where: { issueId: id } });
    // Non-inventory lines must not post to the stock ledger, nor be sized
    // against on-hand quantity below — see attachInventoryItemFlag.
    await attachInventoryItemFlag(tx, itemData);
    // A despatch cannot take stock below zero — see assertNoNegativeStock.
    await assertNoNegativeStock(tx, itemData);
    // Every line's own selected Warehouse must have enough on hand too —
    // see assertNoNegativeWarehouseStockFor.
    await assertNoNegativeWarehouseStockFor(tx, itemData, { label: 'the selected Warehouse' });
    const updated = await tx.stockIssue.update({
      where: { id },
      data: { ...header, ...totals, items: { create: stripInventoryFlag(itemData) } },
      include: stockIssueInclude,
    });
    // Apply the new selection's stock effect — see
    // applyBatchSerialIssueEffects.
    await applyBatchSerialIssueEffects(tx, items, updated.items, { linkField: 'stockIssueItemId' });
    // Journals on the save that first makes this Posted; already-journalled
    // issues are untouched. See utils/stockTable.js.
    await postStockEntries(tx, {
      transType: TRANS_TYPES.STOCK_ISSUE,
      transNum: updated.id,
      documentNumber: updated.issueNo,
      status: updated.status,
      warehouse: updated.toWarehouse,
      branch: updated.branch,
      lines: issueLines(itemData),
      userId: req.user?.id,
    });
    // Rebuild the accounting document from what this issue now says.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.STOCK_ISSUE,
      sourceDocNo: updated.issueNo,
      status: updated.status,
      doc: { ...updated, items: itemData },
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/inventory/stock-issues/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // Deleting the document deletes its accounting document too -- a
  // ledger entry for a document that no longer exists is worse than no
  // entry at all. See reverseJournalEntry in utils/glPosting.js.
  await removeJournalEntryForDocument(
    prisma, JOURNAL_SOURCE_TYPES.STOCK_ISSUE, 'stockIssue', 'issueNo', Number(req.params.id)
  );
  const id = Number(req.params.id);
  await prisma.$transaction(async (tx) => {
    // Give back whatever batch quantity/serial status this issue's
    // selections had taken, before the items (and their allocation rows)
    // cascade away with the document.
    await restoreBatchSerialIssueEffects(tx, { stockIssueId: id });
    // Reverse whatever this issue posted to [dbo].[Stock] before it's gone
    // — deleting bypasses the cancel step that would otherwise have done
    // this.
    await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_ISSUE, transNum: id, userId: req.user?.id });
    await tx.stockIssue.delete({ where: { id } });
  });
  // StockIssueItem.issue has onDelete: Cascade, so items go with it.
  res.json({ success: true, message: 'Deleted successfully' });
}));
// Stock Adjustment — a master/detail resource (StockAdjustment has many
// StockAdjustmentItem rows), same bespoke-route pattern as /inventory/stock-issues
// above. Each line captures the product's Current Stock, an Increase/Decrease
// type, a Quantity and a Reason. The physical count and the signed difference
// (physical - system) are still derived and stored exactly as before
// (physical = current stock +/- quantity) so every existing stock
// valuation/report query built on differenceQuantity keeps working unchanged.
// The adjustment value is that signed difference costed at the product's
// unit price (a shortfall reduces value, a surplus increases it).
const stockAdjustmentInclude = { items: { orderBy: { id: 'asc' } } };

/**
 * @param {object} item     the raw request line
 * @param {Map}    onHand   server-computed stock by product code
 *
 * The system quantity is read from the ledger, not from `item.currentStock`
 * as the client sent it. An adjustment exists to reconcile a physical count
 * against *the system's* view; taking the system side from the same request
 * that carries the physical count meant the recorded difference was whatever
 * the client said it was. A stale form — or a forged request — wrote a
 * difference that moved stock by the wrong amount, and because the adjustment
 * is itself a stock movement, the error compounded on the next count.
 */
function toStockAdjustmentItemData(item, onHand = null, header = null) {
  const currentStock = onHand && onHand.has(item.productCode)
    ? Number(onHand.get(item.productCode)) || 0
    : Number(item.currentStock) || 0;
  const quantity = Number(item.quantity) || 0;
  const itemAdjustmentType = item.itemAdjustmentType === 'Decrease' ? 'Decrease' : 'Increase';
  const signedQuantity = itemAdjustmentType === 'Decrease' ? -quantity : quantity;
  const physicalQuantity = currentStock + signedQuantity;
  const unitPrice = Number(item.unitPrice) || 0;
  const differenceQuantity = physicalQuantity - currentStock;
  return {
    productCode: item.productCode || null,
    productName: item.productName || null,
    hsnCode: item.hsnCode || null,
    batchNo: item.batchNo || null,
    expiryDate: item.expiryDate || null,
    // Per-line Warehouse — line-first, falling back to the document's header
    // Warehouse only when a line leaves it blank (legacy rows saved before
    // this column existed). Same convention as toGrnItemData's warehouse.
    // Used both for stock posting (see adjustmentLines in utils/stockTable.js)
    // and, for Decrease lines only, by assertNoNegativeWarehouseStockFor below.
    warehouse: item.warehouse || header?.warehouse || null,
    uom: item.uom || null,
    systemQuantity: currentStock,
    physicalQuantity,
    differenceQuantity,
    itemAdjustmentType,
    quantity,
    reason: item.reason || null,
    unitPrice,
    amount: round2(differenceQuantity * unitPrice),
  };
}

function computeStockAdjustmentTotals(items) {
  // Rounded to paise: the raw float sum is what made stock valuation
  // reports disagree with the documents they are built from.
  return { amount: round2(items.reduce((sum, i) => sum + round2(i.amount), 0)) };
}

router.get('/inventory/stock-adjustments', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { adjustmentNo: { contains: q } },
        { referenceNo: { contains: q } },
        { reason: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.stockAdjustment.findMany({ where: withBranchScope(where, req), include: stockAdjustmentInclude, orderBy: { id: 'desc' } });
  res.json({ success: true, data: rows });
}));

router.get('/inventory/stock-adjustments/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.stockAdjustment.findUnique({ where: { id: Number(req.params.id) }, include: stockAdjustmentInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  res.json({ success: true, data: row });
}));

router.post('/inventory/stock-adjustments', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue adjustmentNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { items = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const row = await prisma.$transaction(async (tx) => {
    // System quantity comes from the ledger, never from the request — see
    // toStockAdjustmentItemData.
    const onHand = await getCurrentStockForMany(items.map((i) => i.productCode), { client: tx });
    const itemData = items.map((i) => toStockAdjustmentItemData(i, onHand, header));
    // Non-inventory lines must not post to the stock ledger, nor be sized
    // against on-hand quantity below — see attachInventoryItemFlag.
    await attachInventoryItemFlag(tx, itemData);
    const totals = computeStockAdjustmentTotals(itemData);
    // A Decrease line's own selected Warehouse must have enough on hand —
    // Increase lines add stock and are never checked. See
    // assertNoNegativeWarehouseStockFor.
    await assertNoNegativeWarehouseStockFor(tx, itemData, {
      label: 'the selected Warehouse',
      filter: (i) => i.itemAdjustmentType === 'Decrease',
    });
    // adjustmentNo now comes from the configured ADJ numbering series
    // rather than free text — see resolveDocumentNumber above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('ADJ', header.adjustmentNo, tx, seriesId || null);
    const created = await tx.stockAdjustment.create({
      data: { ...header, adjustmentNo: documentNumber, ...totals, items: { create: stripInventoryFlag(itemData) } },
      include: stockAdjustmentInclude,
    });
    if (syncManual) await syncManual();
    // Journal the movement into [dbo].[Stock] — per line, an Increase posts
    // inward and a Decrease outward, only once Posted. See utils/stockTable.js.
    await postStockEntries(tx, {
      transType: TRANS_TYPES.STOCK_ADJUSTMENT,
      transNum: created.id,
      documentNumber: created.adjustmentNo,
      status: created.status,
      warehouse: created.warehouse,
      branch: created.branch,
      lines: adjustmentLines(itemData),
      userId: req.user?.id,
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/inventory/stock-adjustments/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { items = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  // Replace the item set wholesale on every save — simpler and safer than
  // diffing which rows were added/removed/reordered client-side.
  const row = await prisma.$transaction(async (tx) => {
    await tx.stockAdjustmentItem.deleteMany({ where: { adjustmentId: id } });
    // System quantity comes from the ledger, never from the request — and is
    // read after this document's own previous lines are cleared, so an edit
    // measures against stock excluding its own prior effect.
    const onHand = await getCurrentStockForMany(items.map((i) => i.productCode), { client: tx });
    const itemData = items.map((i) => toStockAdjustmentItemData(i, onHand, header));
    // Non-inventory lines must not post to the stock ledger, nor be sized
    // against on-hand quantity below — see attachInventoryItemFlag.
    await attachInventoryItemFlag(tx, itemData);
    const totals = computeStockAdjustmentTotals(itemData);
    // A Decrease line's own selected Warehouse must have enough on hand —
    // Increase lines add stock and are never checked. Checked after this
    // document's own previous lines are cleared (deleteMany above), same as
    // the company-wide onHand lookup. See assertNoNegativeWarehouseStockFor.
    await assertNoNegativeWarehouseStockFor(tx, itemData, {
      label: 'the selected Warehouse',
      filter: (i) => i.itemAdjustmentType === 'Decrease',
    });
    const updated = await tx.stockAdjustment.update({
      where: { id },
      data: { ...header, ...totals, items: { create: stripInventoryFlag(itemData) } },
      include: stockAdjustmentInclude,
    });
    // Journals on the save that first makes this Posted; already-journalled
    // adjustments are untouched. See utils/stockTable.js.
    await postStockEntries(tx, {
      transType: TRANS_TYPES.STOCK_ADJUSTMENT,
      transNum: updated.id,
      documentNumber: updated.adjustmentNo,
      status: updated.status,
      warehouse: updated.warehouse,
      branch: updated.branch,
      lines: adjustmentLines(itemData),
      userId: req.user?.id,
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/inventory/stock-adjustments/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // StockAdjustmentItem.adjustment has onDelete: Cascade, so items go with it.
  const id = Number(req.params.id);
  await prisma.$transaction(async (tx) => {
    // Reverse whatever this adjustment posted to [dbo].[Stock] before it's
    // gone — deleting bypasses the cancel step that would otherwise have
    // done this. No-op if it never posted.
    await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_ADJUSTMENT, transNum: id, userId: req.user?.id });
    await tx.stockAdjustment.delete({ where: { id } });
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Stock Transfer ("Material Transfer") — a master/detail resource
// (StockTransfer has many StockTransferItem rows), same bespoke-route
// pattern as /inventory/stock-issues above. Unlike Stock Receipt/Issue/
// Adjustment (each touches exactly one warehouse), a transfer moves stock
// between two — there is no header-level From/To Warehouse; each line names
// its own fromWarehouse/toWarehouse (see the StockTransfer model comment in
// schema.prisma), and different lines on the same document can move stock
// between different warehouse pairs.
const stockTransferInclude = { items: { orderBy: { id: 'asc' }, include: { batchAllocations: { orderBy: { id: 'asc' } }, serialAllocations: { orderBy: { id: 'asc' } } } } };

/**
 * @param {object} item    the raw request line
 * @param {object} header  the sanitized document header (no longer carries
 *                         fromWarehouse/toWarehouse — every line must name
 *                         its own, enforced by assertStockTransferItemsHaveWarehouses)
 * @param {Map}    onHand  server-computed company-wide stock by product code
 *
 * totalStock is a read-only reference snapshot (same "never trust the
 * client's figure" rule as StockAdjustmentItem.systemQuantity) — it plays no
 * part in the transfer's own movement math, which is exactly `quantity` on
 * both legs.
 */
function toStockTransferItemData(item, header, onHand = null) {
  const totalStock = onHand && onHand.has(item.productCode)
    ? Number(onHand.get(item.productCode)) || 0
    : Number(item.totalStock) || 0;
  const quantity = Number(item.quantity) || 0;
  const unitPrice = Number(item.unitPrice) || 0;
  const itemCost = item.itemCost != null ? Number(item.itemCost) : unitPrice;
  return {
    productCode: item.productCode || null,
    productName: item.productName || null,
    fromWarehouse: item.fromWarehouse || null,
    toWarehouse: item.toWarehouse || null,
    totalStock,
    uom: item.uom || null,
    quantity,
    unitPrice,
    itemCost,
    accountCode: item.accountCode || null,
    project: item.project || null,
    remarks: item.remarks || null,
    amount: round2(quantity * unitPrice),
  };
}

function computeStockTransferTotals(items) {
  // Rounded to paise: the raw float sum is what made stock valuation
  // reports disagree with the documents they are built from.
  return { amount: round2(items.reduce((sum, i) => sum + round2(i.amount), 0)) };
}

/**
 * Every line must name both legs of its own movement — without this, a line
 * that reached here with a blank fromWarehouse/toWarehouse (the frontend
 * requires both, but the API is the actual boundary) would post to the
 * journal with warehouse NULL, a movement nothing can be filtered or
 * reconciled against.
 *
 * For a Branch Transfer, `toWarehouse` isn't a manual per-row choice — it's
 * auto-filled from the destination branch's own Transit Warehouse
 * (WarehouseMaster.isTransit; see transitWarehouseCode/TransitWarehouseCell
 * in StockTransfer.jsx), and comes back blank whenever that branch has none
 * flagged yet. There is no field on this document for the user to fix that
 * from, so requiring it here — same as the frontend used to — blocked
 * saving a perfectly valid Open transfer purely because Warehouse Master
 * hasn't been set up yet. It's still required for a plain Stock Transfer,
 * where the user genuinely does pick it. The gap is closed instead at the
 * point it actually matters — closure/posting — by
 * assertStockTransferItemsReadyToClose below, called from
 * syncStockTransferClosure right before the ledger entries are written.
 */
function assertStockTransferItemsHaveWarehouses(itemData, { transferType } = {}) {
  const requireToWarehouse = transferType !== 'Branch Transfer';
  const offending = itemData
    .map((i, idx) => ({ idx, i }))
    .filter(({ i }) => !i.fromWarehouse || (requireToWarehouse && !i.toWarehouse));
  if (offending.length) {
    const err = new Error(
      requireToWarehouse
        ? `Every item needs a From Warehouse and To Warehouse — row ${offending[0].idx + 1} is missing one.`
        : `Every item needs a From Warehouse — row ${offending[0].idx + 1} is missing one.`
    );
    err.status = 400;
    throw err;
  }
}

/**
 * Closure-time counterpart to the relaxed check above: by the time a
 * transfer is actually being received (syncStockTransferClosure, which is
 * what runs postStockEntries and moves real stock), every line's
 * toWarehouse — including a Branch Transfer's auto-filled Transit
 * Warehouse — must be resolved, or the inbound leg would post with
 * warehouse NULL. Failing here (rather than silently posting a null
 * warehouse) rolls back the whole receipt save that triggered closure.
 */
function assertStockTransferItemsReadyToClose(items, transferNo) {
  const offending = (items || []).filter((i) => !i.fromWarehouse || !i.toWarehouse);
  if (offending.length) {
    const err = new Error(
      `Stock Transfer ${transferNo} can't be received yet — it has a line with no Transit Warehouse. `
      + 'Set a Transit Warehouse for the destination branch in Company Setup > Warehouse Master, then re-save the transfer.'
    );
    err.status = 409;
    throw err;
  }
}

/**
 * A document's outbound leg can't take its own From Warehouse's stock below
 * zero — checked per (product, From Warehouse), not company-wide.
 *
 * assertNoNegativeStock (used elsewhere) only ever had a company-wide figure
 * to check against, which is why the comment on Stock Transfer's POST route
 * used to call this a known gap: a product sitting entirely in Warehouse A
 * could be "transferred" out of Warehouse B, which holds none of it, and the
 * company-wide total would still look fine while Warehouse B's own position
 * went negative. getCurrentStockByWarehouseForMany (utils/stockLedger.js)
 * exists precisely so this can be checked against the FROM warehouse's own
 * on-hand figure instead. The same gap applies to any other document with a
 * single From/despatching warehouse — Delivery Challan included, which is
 * why this isn't named specifically after Stock Transfer any more.
 *
 * `warehouseField` defaults to 'fromWarehouse' (the per-line field Stock
 * Transfer's own items carry); pass a mapped item list (each line stamped
 * with the header's single warehouse) for a document like Delivery Challan
 * whose From Warehouse lives on the header, not per line.
 */
async function assertNoNegativeWarehouseStock(tx, itemData, { warehouseField = 'fromWarehouse', quantityField = 'quantity', verb = 'transferring' } = {}) {
  // See assertNoNegativeStock's identical guard just above.
  if (!(await isInventoryModuleEnabled(tx))) return;

  const required = new Map(); // "productCode::warehouse" -> quantity
  for (const item of itemData) {
    // A non-inventory line (per-product inventoryItem=false, or the whole
    // document is a Claims/Services Delivery Challan — see
    // applyNonStockSalesCategory) never moves stock, so it is never sized
    // against on-hand quantity either — see attachInventoryItemFlag's doc
    // comment. Stock Transfer's own items never carry this flag at all, so
    // isInventoryLine defaults them to true and this is a no-op there.
    if (!isInventoryLine(item)) continue;
    const code = item.productCode;
    const warehouse = item[warehouseField];
    const qty = Number(item[quantityField]) || 0;
    if (!code || !warehouse || qty <= 0) continue;
    const key = `${code}::${warehouse}`;
    required.set(key, round2((required.get(key) || 0) + qty));
  }
  if (!required.size) return;

  const pairs = [...required.keys()].map((key) => {
    const sep = key.lastIndexOf('::');
    return { productCode: key.slice(0, sep), warehouse: key.slice(sep + 2) };
  });
  const onHand = await getCurrentStockByWarehouseForMany(pairs, { client: tx });

  const shortfalls = [];
  for (const [key, needed] of required) {
    const available = onHand.get(key) ?? 0;
    if (needed > available + 0.005) {
      const sep = key.lastIndexOf('::');
      shortfalls.push(
        `${key.slice(0, sep)} at ${key.slice(sep + 2)}: ${verb} ${needed} but only ${available} on hand in that warehouse`
      );
    }
  }
  if (shortfalls.length) {
    const err = new Error(`Insufficient stock in the From Warehouse — ${shortfalls.join('; ')}`);
    err.status = 409;
    throw err;
  }
}

/**
 * General-purpose version of assertNoNegativeWarehouseStock above, for every
 * OTHER stock-reducing document that carries a single per-line `warehouse`
 * field (rather than Stock Transfer's fromWarehouse/toWarehouse pair):
 * Delivery Challan, direct Sales Invoice, Sales Order (quantity check only —
 * it does not itself post stock), Stock Issue, and a Decrease Stock
 * Adjustment line. `warehouseField` names the property on each itemData
 * entry to read the warehouse from (defaults to 'warehouse'); pass a
 * `filter` to only check a subset of lines (e.g. Stock Adjustment's Decrease
 * lines only — Increase lines add stock and are never checked).
 */
async function assertNoNegativeWarehouseStockFor(tx, itemData, { warehouseField = 'warehouse', label = 'the selected warehouse', filter } = {}) {
  // See assertNoNegativeStock's identical guard above.
  if (!(await isInventoryModuleEnabled(tx))) return;

  const required = new Map(); // "productCode::warehouse" -> quantity
  for (const item of itemData) {
    // A non-inventory line never moves stock, so it is never sized against
    // on-hand quantity either — see attachInventoryItemFlag's doc comment.
    if (!isInventoryLine(item)) continue;
    if (filter && !filter(item)) continue;
    const code = item.productCode;
    const warehouse = item[warehouseField];
    const qty = Number(item.quantity) || 0;
    if (!code || !warehouse || qty <= 0) continue;
    const key = `${code}::${warehouse}`;
    required.set(key, round2((required.get(key) || 0) + qty));
  }
  if (!required.size) return;

  const pairs = [...required.keys()].map((key) => {
    const sep = key.lastIndexOf('::');
    return { productCode: key.slice(0, sep), warehouse: key.slice(sep + 2) };
  });
  const onHand = await getCurrentStockByWarehouseForMany(pairs, { client: tx });

  const shortfalls = [];
  for (const [key, needed] of required) {
    const available = onHand.get(key) ?? 0;
    if (needed > available + 0.005) {
      const sep = key.lastIndexOf('::');
      shortfalls.push(
        `${key.slice(0, sep)} at ${key.slice(sep + 2)}: requesting ${needed} but only ${available} on hand in that warehouse`
      );
    }
  }
  if (shortfalls.length) {
    const err = new Error(`Insufficient stock in ${label} — ${shortfalls.join('; ')}`);
    err.status = 409;
    throw err;
  }
}

/**
 * Is a Stock Transfer, as it stands right now, actually allowed to post
 * stock/G/L? Stock Transfer's own `status` column only ever holds
 * 'Open'/'Closed' (see the model comment in schema.prisma) — unlike every
 * other stock-posting document, it has no 'Draft'/'Cancelled'/'Pending' of
 * its own, so movesStock(status, transType) alone (now that 'Open' is no
 * longer excluded — see stockTable.js) is not enough to decide "should this
 * post RIGHT NOW". Two more things gate it, both already enforced
 * elsewhere in this app before this change, just at the wrong moment
 * (Closure, instead of here):
 *
 *  1. Approval. A transfer raised against a Stock Transfer Request copies
 *     that request's approvalStatus at creation time (see the POST route
 *     below) and must not move stock until it reads 'Approved' — see
 *     syncStockTransferApprovalOnRequestApproved, called from the
 *     Notification-bell approve endpoint (routes/notifications.js) the
 *     moment that happens. A transfer with no requestNo keeps the schema
 *     default of 'Approved' and clears this immediately.
 *  2. Warehouse readiness. A Branch Transfer's toWarehouse is auto-filled
 *     from the destination branch's own Transit Warehouse and can be blank
 *     at save time (assertStockTransferItemsHaveWarehouses deliberately
 *     allows this, so saving is never blocked just because Warehouse Master
 *     hasn't been set up yet) — posting an inbound leg with warehouse NULL
 *     is not acceptable, so this simply does not post until every line
 *     resolves, same all-or-nothing-per-document shape
 *     assertStockTransferItemsReadyToClose used to enforce only at Closure.
 *
 * utils/stockLedger.js's stockTransferReadyFilter tests the EXACT same two
 * conditions, so the derived ledger and the written journal never disagree
 * about whether a given transfer's legs have moved.
 */
function stockTransferPostable(transfer, items) {
  if (transfer.approvalStatus !== 'Approved') return false;
  return (items || []).length > 0 && (items || []).every((i) => i.fromWarehouse && i.toWarehouse);
}

/**
 * Stock Transfer's own reverse-then-repost cycle — the Stock-Transfer-
 * specific counterpart to syncStockPosting (see its doc comment near the top
 * of this file), adapted for the two ways a Stock Transfer differs from
 * every other document syncStockPosting already handles:
 *
 *  1. Whether THIS save should post is stockTransferPostable above, not a
 *     plain movesStock(status, transType) call — see its own doc comment.
 *  2. There is no `stockPostingGeneration` column on StockTransfer to hand
 *     syncStockPosting (adding one is a schema migration, out of scope for a
 *     stock-timing fix), so the current generation is read back from the
 *     journal itself instead — see highestPostedGeneration in
 *     utils/stockTable.js. That function is safe to call even against a
 *     generation that was already reversed (reverseStockEntries against an
 *     already-reversed generation is itself a no-op — see its own doc
 *     comment), so reversing whatever this returns and posting one
 *     generation higher never double-reverses or double-posts.
 *
 * Called from Stock Transfer's own POST/PUT routes (the ordinary case: an
 * unlinked, or already-approved, transfer with resolvable warehouses posts
 * immediately), from syncStockTransferApprovalOnRequestApproved (the moment
 * a Request-linked transfer becomes postable), and from
 * syncStockTransferClosure as a safety-net fallback for the rare transfer
 * that is STILL not postable by the time its Receipt arrives (see that
 * function's own comment).
 *
 * Does NOT run the negative-stock guard itself — see each call site's own
 * comment for why (in short: by the time this runs, the transfer's own items
 * already exist and, once postable, already count as moved in
 * utils/stockLedger.js's on-hand figure, so checking against that figure
 * from inside here would measure this transfer's own effect against itself).
 */
async function syncStockTransferMovement(tx, { transfer, items, userId = null } = {}) {
  const ready = stockTransferPostable(transfer, items);
  const outGen = await highestPostedGeneration(tx, TRANS_TYPES.STOCK_TRANSFER_OUT, transfer.id);
  const inGen = await highestPostedGeneration(tx, TRANS_TYPES.STOCK_TRANSFER_IN, transfer.id);

  if (!ready) {
    // Not (or no longer) postable — reverse whatever an earlier, postable
    // save already posted, same as syncStockPosting does for any other
    // non-moving status. The ordinary case (never postable in the first
    // place) finds nothing to reverse and is a no-op.
    if (outGen > 0) await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_TRANSFER_OUT, transNum: transfer.id, userId, generation: outGen });
    if (inGen > 0) await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_TRANSFER_IN, transNum: transfer.id, userId, generation: inGen });
    await reverseJournalEntry(tx, JOURNAL_SOURCE_TYPES.STOCK_TRANSFER, transfer.transferNo);
    return { posted: false, reason: transfer.approvalStatus !== 'Approved' ? 'pending-approval' : 'warehouse-not-ready' };
  }

  if (outGen > 0) await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_TRANSFER_OUT, transNum: transfer.id, userId, generation: outGen });
  if (inGen > 0) await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_TRANSFER_IN, transNum: transfer.id, userId, generation: inGen });
  // Journal the movement into [dbo].[Stock] TWICE per line — an outbound leg
  // at that line's own fromWarehouse and an inbound leg at its own
  // toWarehouse, all keyed off this same document id but under distinct
  // TransType values. transferOutLines/transferInLines stamp each line's own
  // warehouse onto it, which postStockEntries' own per-line `warehouse`
  // override reads. See utils/stockTable.js's TRANS_TYPES.STOCK_TRANSFER_OUT/IN.
  await postStockEntries(tx, {
    transType: TRANS_TYPES.STOCK_TRANSFER_OUT,
    transNum: transfer.id,
    documentNumber: transfer.transferNo,
    status: transfer.status,
    branch: transfer.branch,
    lines: transferOutLines(items),
    userId,
    generation: outGen + 1,
  });
  await postStockEntries(tx, {
    transType: TRANS_TYPES.STOCK_TRANSFER_IN,
    transNum: transfer.id,
    documentNumber: transfer.transferNo,
    status: transfer.status,
    branch: transfer.branch,
    lines: transferInLines(items),
    userId,
    generation: inGen + 1,
  });
  // Dr Inventory (destination) / Cr Inventory (source), in the same lockstep
  // moment as the stock legs above — see glPosting.js's updated
  // GL_NON_MOVING_STATUSES_BY_SOURCE_TYPE comment. Posts only when the two
  // warehouses determine to different inventory accounts -- within one
  // account it nets to nothing and is skipped.
  await syncJournalEntry(tx, {
    sourceType: JOURNAL_SOURCE_TYPES.STOCK_TRANSFER,
    sourceDocNo: transfer.transferNo,
    status: transfer.status,
    doc: { ...transfer, items },
  });
  return { posted: true };
}

// Keeps a Stock Transfer Request's status in step with whichever Stock
// Transfer(s) reference it via requestNo (string-match, same convention as
// GoodsReceivedNote.poNo -> PurchaseOrder.poNo — no FK). Saving a transfer
// against a still-Open request closes it; changing a transfer off a request
// (or deleting the transfer entirely) reopens it. Only ever flips a request
// between its own Open/Closed values, so a request some other flow already
// moved on from is left alone.
async function syncStockTransferRequestStatus(tx, { previousRequestNo = null, requestNo = null } = {}) {
  if (previousRequestNo && previousRequestNo !== requestNo) {
    await tx.stockTransferRequest.updateMany({
      where: { requestNo: previousRequestNo, status: 'Closed' },
      data: { status: 'Open' },
    });
  }
  if (requestNo && requestNo !== previousRequestNo) {
    await tx.stockTransferRequest.updateMany({
      where: { requestNo, status: 'Open' },
      data: { status: 'Closed' },
    });
  }
}

/**
 * Called from the Notification-bell approve endpoint (POST
 * /api/notifications/:id/approve in routes/notifications.js) the moment a
 * Stock Transfer Request's own approvalStatus flips to 'Approved' — see
 * resolveApproval there. Exported at the bottom of this file for that route
 * to call, the same way buildAvailableBalanceReportData already is for
 * routes/dashboard.js.
 *
 * A Stock Transfer raised against a still-Pending Request copies that
 * Pending value onto its OWN approvalStatus column at creation time (see the
 * POST /inventory/stock-transfers route below) and, before this function
 * existed, was never revisited again — nothing else in this codebase ever
 * wrote to a StockTransfer's approvalStatus column after create, so an
 * approved Request's linked transfer would have sat forever reading
 * 'Pending' and never posted. This is that missing sync: find every Stock
 * Transfer still Open against this Request, flip its own approvalStatus to
 * match, and post its stock/G/L for the first time if it is otherwise ready
 * (stockTransferPostable) — the moment stock now actually moves for a
 * Request-linked transfer, instead of waiting for a Receipt to close it.
 *
 * Must run inside the SAME transaction as the Request's own approvalStatus
 * update (the caller passes its own `tx`), so an approval and the stock it
 * releases either both happen or neither does.
 */
async function syncStockTransferApprovalOnRequestApproved(tx, { requestNo, userId = null } = {}) {
  if (!requestNo) return;
  const transfers = await tx.stockTransfer.findMany({
    where: { requestNo, status: 'Open', approvalStatus: 'Pending' },
    include: stockTransferInclude,
  });
  for (const transfer of transfers) {
    // Read on-hand and check it BEFORE flipping this transfer's own
    // approvalStatus. Once that column reads 'Approved', utils/
    // stockLedger.js's stockTransferReadyFilter starts counting this
    // transfer's own outbound/inbound legs as live movement — checking
    // AFTER the flip would measure it against an on-hand figure that
    // already includes its own not-yet-posted effect on itself.
    // eslint-disable-next-line no-await-in-loop
    await assertNoNegativeStock(tx, transfer.items);
    // eslint-disable-next-line no-await-in-loop
    await assertNoNegativeWarehouseStock(tx, transfer.items);
    // eslint-disable-next-line no-await-in-loop
    const approved = await tx.stockTransfer.update({
      where: { id: transfer.id },
      data: { approvalStatus: 'Approved' },
      include: stockTransferInclude,
    });
    // eslint-disable-next-line no-await-in-loop
    await syncStockTransferMovement(tx, { transfer: approved, items: approved.items, userId });
  }
}

// Keeps a Stock Transfer's own `status` (Open/Closed) in step with whichever
// Stock Transfer Receipt references it via transferNo (string-match, same
// no-FK convention as syncStockTransferRequestStatus just above).
//
// STOCK/G/L NO LONGER MOVE HERE. They used to: a Stock Transfer was raised
// Open and moved nothing until a Receipt confirmed the goods arrived and
// flipped it to 'Closed', which is what triggered postStockEntries/
// syncJournalEntry for the first time. That timing moved upstream — a
// transfer now posts as soon as it is raised (or, for a Request-linked one,
// as soon as that request is approved — see stockTransferPostable/
// syncStockTransferMovement and syncStockTransferApprovalOnRequestApproved
// above) — because physically the goods are dispatched (and, per the
// business decision behind this change, treated as received) the moment the
// transfer itself is issued, not whenever someone later gets around to
// confirming a receipt against it.
//
// What Closure is left responsible for:
//
//  1. The status flip itself. 'Closed' is a distinct, human-driven signal —
//     "someone at the destination confirmed this arrived" — separate from
//     whether stock has moved, and callers elsewhere in the app (reports,
//     the Stock Transfer list UI) still read this column for that purpose.
//  2. The approval/readiness gates below, kept here as a genuine guard on
//     the 'Closed' status itself: it would be wrong to let a transfer be
//     marked "confirmed received" if it was never approved (or Rejected —
//     the goods presumably never left) or if its warehouse is still
//     unresolved, regardless of what already happened to its stock.
//  3. A safety-net, idempotent fallback call to syncStockTransferMovement.
//     Approval and warehouse-readiness are both meant to already be true by
//     the time a transfer is closed (its own Issue/approval path should have
//     posted it already), so in the ordinary case this call finds nothing
//     left to do (highestPostedGeneration is already > 0, ready is already
//     true) and is a pure no-op. It only does real work for the one
//     remaining edge case — a Branch Transfer whose destination Transit
//     Warehouse only gets configured, and the transfer only gets re-saved to
//     pick it up, sometime between raising it and closing it — so that
//     edge case still eventually posts instead of the movement silently
//     never happening.
//
// Deleting (or re-pointing) the confirming receipt now ONLY reopens the
// transfer (flips 'Closed' back to 'Open') — it no longer reverses stock/GL,
// because Closure no longer owns what posted them. Reversing a transfer's
// stock/G/L is now exclusively the Stock Transfer (Issue) DELETE route's job
// (see the reversal there, which — since posting can now have happened at
// create, at edit, or at the later approval moment — reverses whatever
// generation is CURRENTLY posted rather than a hardcoded one).
async function syncStockTransferClosure(tx, { previousTransferNo = null, transferNo = null, userId = null, receiptItems = [] } = {}) {
  if (previousTransferNo && previousTransferNo !== transferNo) {
    // No `include: { items: true }` needed any more — this branch no longer
    // touches stock/G/L (see this function's own doc comment), just the
    // status column.
    const prev = await tx.stockTransfer.findFirst({
      where: { transferNo: previousTransferNo, status: 'Closed' },
      select: { id: true },
    });
    if (prev) {
      await tx.stockTransfer.update({ where: { id: prev.id }, data: { status: 'Open' } });
    }
  }
  if (transferNo && transferNo !== previousTransferNo) {
    const found = await tx.stockTransfer.findFirst({
      where: { transferNo, status: 'Open' },
      include: { items: true },
    });
    if (found) {
      // Approval gate: refuse to mark this "confirmed received" if it was
      // never approved (or was rejected) — see stockTransferPostable's own
      // doc comment for the same test applied at posting time. Throwing here
      // rolls back the whole $transaction this runs inside (the receipt save
      // that triggered it included).
      if (found.approvalStatus !== 'Approved') {
        const err = new Error(
          found.approvalStatus === 'Rejected'
            ? `Stock Transfer ${found.transferNo} was rejected and cannot be received.`
            : `Stock Transfer ${found.transferNo} is awaiting approval and cannot be received yet.`
        );
        err.status = 409;
        throw err;
      }
      // A Branch Transfer line whose destination (Transit) Warehouse was
      // still blank when the transfer was raised takes the Receive Warehouse
      // chosen on the confirming receipt for the same item — the receipt is
      // where the destination actually states where the goods arrived, so
      // the transfer is no longer stuck until Warehouse Master is set up and
      // the transfer re-saved. Lines that already have a toWarehouse are
      // never touched.
      const receiveWarehouseByProduct = new Map();
      (receiptItems || []).forEach((r) => {
        if (r.productCode && r.toWarehouse && !receiveWarehouseByProduct.has(r.productCode)) {
          receiveWarehouseByProduct.set(r.productCode, r.toWarehouse);
        }
      });
      for (const line of found.items) {
        if (line.toWarehouse) continue;
        const receiveWarehouse = receiveWarehouseByProduct.get(line.productCode);
        if (!receiveWarehouse) continue;
        await tx.stockTransferItem.update({ where: { id: line.id }, data: { toWarehouse: receiveWarehouse } });
        line.toWarehouse = receiveWarehouse;
      }
      // Only enforced here, not at save time — see the comment on
      // assertStockTransferItemsHaveWarehouses. A Branch Transfer can be
      // saved (and re-saved) with its Transit Warehouse still blank; it
      // just can't be received/closed until Warehouse Master has one set
      // for the destination branch.
      assertStockTransferItemsReadyToClose(found.items, found.transferNo);
      const closed = await tx.stockTransfer.update({ where: { id: found.id }, data: { status: 'Closed' } });
      // Safety-net fallback — see this function's own doc comment, point 3.
      // Idempotent: the ordinary transfer already posted at Issue/approval
      // time and this simply finds nothing left to reverse or post.
      await syncStockTransferMovement(tx, { transfer: closed, items: found.items, userId });
    }
  }
}

router.get('/inventory/stock-transfers', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { transferNo: { contains: q } },
        { partyName: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.stockTransfer.findMany({ where: withBranchScope(where, req), include: stockTransferInclude, orderBy: { id: 'desc' } });
  await attachJournalEntryRefs(rows, JOURNAL_SOURCE_TYPES.STOCK_TRANSFER, 'transferNo');
  res.json({ success: true, data: rows });
}));

router.get('/inventory/stock-transfers/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.stockTransfer.findUnique({ where: { id: Number(req.params.id) }, include: stockTransferInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  await attachJournalEntryRefs(row, JOURNAL_SOURCE_TYPES.STOCK_TRANSFER, 'transferNo');
  res.json({ success: true, data: row });
}));

router.post('/inventory/stock-transfers', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue transferNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { items = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  // "Relocate" — a Batch/Serial-tracked line must select the existing
  // batch/serial being moved, and enough of it must currently sit in the
  // line's own From Warehouse (a batch can now be split across warehouses
  // — see assertBatchRelocationAvailable). See the *Relocate* functions in
  // utils/businessRules.js.
  await assertBatchSerialRelocateAllocation(prisma, items, { quantityField: 'quantity' });
  await assertBatchRelocationAvailable(prisma, items);
  await assertRelocateWarehouseMatches(prisma, items);
  const row = await prisma.$transaction(async (tx) => {
    // System stock comes from the ledger, never from the request — see
    // toStockTransferItemData.
    const onHand = await getCurrentStockForMany(items.map((i) => i.productCode), { client: tx });
    const itemData = items.map((i) => toStockTransferItemData(i, header, onHand));
    assertStockTransferItemsHaveWarehouses(itemData, { transferType: header.transferType });
    // Company-wide guard (catches a product the company doesn't hold enough
    // of at all) plus the warehouse-scoped one (catches a From Warehouse that
    // doesn't hold enough of it even though another warehouse does) — see
    // assertNoNegativeWarehouseStock's own doc comment.
    await assertNoNegativeStock(tx, itemData);
    await assertNoNegativeWarehouseStock(tx, itemData);
    const totals = computeStockTransferTotals(itemData);
    // transferNo now comes from the configured MT numbering series rather
    // than free text — see resolveDocumentNumber above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('MT', header.transferNo, tx, seriesId || null);
    // Notification bell feature: a transfer raised against a Stock Transfer
    // Request inherits that request's approvalStatus (Pending until acted
    // on) — syncStockTransferClosure refuses to post stock/GL for it until
    // that flips to 'Approved'. A transfer with no requestNo (the pre-
    // existing ad-hoc flow) keeps the schema default of 'Approved', since
    // the approval trigger point is explicitly scoped to StockTransferRequest
    // creation, not to every Stock Transfer.
    let approvalStatus;
    if (header.requestNo) {
      const linkedRequest = await tx.stockTransferRequest.findFirst({
        where: { requestNo: header.requestNo },
        select: { approvalStatus: true },
      });
      approvalStatus = linkedRequest?.approvalStatus || 'Pending';
    }
    const created = await tx.stockTransfer.create({
      data: {
        ...header,
        transferNo: documentNumber,
        ...totals,
        ...(approvalStatus ? { approvalStatus } : {}),
        items: { create: itemData },
      },
      include: stockTransferInclude,
    });
    if (syncManual) await syncManual();
    // Raising this transfer against a Stock Transfer Request closes that
    // request out — it's been acted on.
    await syncStockTransferRequestStatus(tx, { requestNo: created.requestNo || null });
    // Move the selected batch/serial's own `warehouse` column to the line's
    // toWarehouse and record the allocation — see applyBatchSerialRelocateEffects.
    await applyBatchSerialRelocateEffects(tx, items, created.items, { linkField: 'stockTransferItemId' });
    // Post stock (both legs) and the matching G/L entry, right now, if this
    // transfer is not linked to a Stock Transfer Request awaiting approval
    // and every line's From/To Warehouse is resolved — see
    // stockTransferPostable's own doc comment. A transfer that is not yet
    // postable (Pending approval, or an unresolved Branch Transfer) simply
    // does not post here; syncStockTransferApprovalOnRequestApproved posts it
    // the moment it is approved, and re-saving it (PUT) once its warehouse
    // resolves picks up the other case. The negative-stock guard above
    // already ran BEFORE this document (and its items) existed, which is the
    // correct moment for it — see syncStockTransferMovement's own doc
    // comment for why it does not repeat that check itself.
    await syncStockTransferMovement(tx, { transfer: created, items: itemData, userId: req.user?.id });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/inventory/stock-transfers/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { items = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  await assertBatchSerialRelocateAllocation(prisma, items, { quantityField: 'quantity' });
  // The batch availability check moved inside the transaction below, run
  // right after restoreBatchSerialRelocateEffects — unlike the old whole-
  // batch-only model, this one actually compares against each batch's
  // per-warehouse quantity, and that quantity now changes on a relocate
  // (see applyBatchSerialRelocateEffects), so it has to see the state
  // AFTER this document's own current effect is undone, or it would see
  // less available than is really free.
  // Replace the item set wholesale on every save — simpler and safer than
  // diffing which rows were added/removed/reordered client-side.
  const row = await prisma.$transaction(async (tx) => {
    // Read before update — needed to detect a requestNo change so the old
    // request can be reopened (see syncStockTransferRequestStatus below).
    const existing = await tx.stockTransfer.findUnique({ where: { id }, select: { requestNo: true } });
    // Undo this document's CURRENT relocate effect (puts each moved batch/
    // serial's warehouse back to its OWN fromWarehouse) before its items
    // (and their allocation rows) are replaced — see
    // restoreBatchSerialRelocateEffects. Must run before the deleteMany
    // below and before the warehouse-match/availability checks, since
    // re-saving this transfer's own unchanged lines should not be flagged
    // as "not at the From Warehouse" (or "not enough available") against a
    // warehouse THIS document itself just moved stock into.
    await restoreBatchSerialRelocateEffects(tx, { transferId: id });
    await assertBatchRelocationAvailable(tx, items);
    await assertRelocateWarehouseMatches(tx, items);
    await tx.stockTransferItem.deleteMany({ where: { transferId: id } });
    // System stock comes from the ledger, never from the request — and is
    // read after this document's own previous lines are cleared, so an edit
    // measures against stock excluding its own prior effect.
    const onHand = await getCurrentStockForMany(items.map((i) => i.productCode), { client: tx });
    const itemData = items.map((i) => toStockTransferItemData(i, header, onHand));
    assertStockTransferItemsHaveWarehouses(itemData, { transferType: header.transferType });
    await assertNoNegativeStock(tx, itemData);
    await assertNoNegativeWarehouseStock(tx, itemData);
    const totals = computeStockTransferTotals(itemData);
    const updated = await tx.stockTransfer.update({
      where: { id },
      data: { ...header, ...totals, items: { create: itemData } },
      include: stockTransferInclude,
    });
    await applyBatchSerialRelocateEffects(tx, items, updated.items, { linkField: 'stockTransferItemId' });
    // Reflect any change in which request this transfer is raised against —
    // reopens the old one (if any) and closes the new one (if any).
    await syncStockTransferRequestStatus(tx, {
      previousRequestNo: existing?.requestNo || null,
      requestNo: updated.requestNo || null,
    });
    // Reverse whatever this transfer's PREVIOUS lines posted and post the
    // EDITED ones in their place (e.g. qty 10 -> 15 nets to a fresh OUT@15/
    // IN@15 pair, never a stale 10 plus a new 15) — see
    // syncStockTransferMovement's own doc comment. A transfer not yet postable
    // (still Pending approval, or an unresolved Branch Transfer) stays
    // unposted, same as at create; one that has just BECOME postable on this
    // very save (e.g. a Branch Transfer whose Transit Warehouse was just set
    // up) posts here for the first time. The negative-stock guard above
    // already ran against on-hand with this document's own prior effect
    // excluded (its old items were deleted before onHand was read), which is
    // the correct moment for it.
    await syncStockTransferMovement(tx, { transfer: updated, items: itemData, userId: req.user?.id });
    return updated;
  });
  res.json({ success: true, data: row });
}));

// E-Way Bill for a Branch Transfer (TaxPro GSP) -- mirrors the Sales Invoice
// e-way routes above; see taxproGsp.service.js generateStockTransferEWayBill().
router.post('/inventory/stock-transfers/:id/eway-bill/generate', auth(), asyncHandler(async (req, res) => {
  const { transporterName, transporterGstin, vehicleNo, transportMode, distanceKm } = req.body || {};
  const row = await taxproGsp.generateStockTransferEWayBill(req.params.id, { transporterName, transporterGstin, vehicleNo, transportMode, distanceKm });
  res.json({ success: true, data: row });
}));
router.post('/inventory/stock-transfers/:id/eway-bill/cancel', auth(), asyncHandler(async (req, res) => {
  const row = await taxproGsp.cancelStockTransferEWayBill(req.params.id, req.body?.cancelReason);
  res.json({ success: true, data: row });
}));

router.delete('/inventory/stock-transfers/:id', auth(['admin']), asyncHandler(async (req, res) => {
  {
    const existingEWay = await prisma.stockTransfer.findUnique({ where: { id: Number(req.params.id) }, select: { ewayBillStatus: true } });
    if (existingEWay?.ewayBillStatus === 'Generated') {
      return res.status(409).json({ success: false, message: 'An e-way bill is active for this transfer. Cancel the e-way bill before deleting the transfer.' });
    }
  }
  // Deleting the document deletes its accounting document too -- a
  // ledger entry for a document that no longer exists is worse than no
  // entry at all. See reverseJournalEntry in utils/glPosting.js.
  await removeJournalEntryForDocument(
    prisma, JOURNAL_SOURCE_TYPES.STOCK_TRANSFER, 'stockTransfer', 'transferNo', Number(req.params.id)
  );
  const id = Number(req.params.id);
  await prisma.$transaction(async (tx) => {
    // Put every relocated batch/serial's warehouse back before the items —
    // and their allocation rows — cascade away with the document.
    // StockTransferItem.transfer has onDelete: Cascade, so items go with it.
    await restoreBatchSerialRelocateEffects(tx, { transferId: id });
    // Reverse both legs this transfer posted to [dbo].[Stock] before it's
    // gone — deleting bypasses the cancel step that would otherwise have
    // done this. Posting can now have happened at create, at a later edit, or
    // at the moment a linked Stock Transfer Request got approved (see
    // syncStockTransferMovement's reverse-then-repost cycle), so the CURRENT
    // generation is read back from the journal itself (highestPostedGeneration
    // — there is no stockPostingGeneration column on this model) rather than
    // assuming generation 1; a transfer that never posted at all (never
    // approved, or a still-unresolved Branch Transfer) finds generation 0 on
    // both legs and this is a no-op, same as before.
    const outGen = await highestPostedGeneration(tx, TRANS_TYPES.STOCK_TRANSFER_OUT, id);
    const inGen = await highestPostedGeneration(tx, TRANS_TYPES.STOCK_TRANSFER_IN, id);
    if (outGen > 0) await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_TRANSFER_OUT, transNum: id, userId: req.user?.id, generation: outGen });
    if (inGen > 0) await reverseStockEntries(tx, { transType: TRANS_TYPES.STOCK_TRANSFER_IN, transNum: id, userId: req.user?.id, generation: inGen });
    const deleted = await tx.stockTransfer.delete({ where: { id } });
    // The transfer that closed this request is gone — reopen it.
    await syncStockTransferRequestStatus(tx, { previousRequestNo: deleted.requestNo || null, requestNo: null });
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Stock Transfer Request — a request to move stock, raised BEFORE an actual
// Stock Transfer is created. Deliberately simple (v1 scope), same bespoke-
// route pattern as Stock Transfer above, but with NONE of its stock-ledger,
// GL-posting or batch/serial-allocation machinery: this is pure paperwork,
// referenced by Stock Transfer via requestNo (string-match, same convention
// as GoodsReceivedNote.poNo -> PurchaseOrder.poNo). Not wired into
// documentFlow.js yet — that is a later step.
const stockTransferRequestInclude = { items: { orderBy: { id: 'asc' } } };

function toStockTransferRequestItemData(item) {
  const quantity = Number(item.quantity) || 0;
  const unitPrice = Number(item.unitPrice) || 0;
  const itemCost = item.itemCost != null ? Number(item.itemCost) : unitPrice;
  return {
    productCode: item.productCode || null,
    productName: item.productName || null,
    fromWarehouse: item.fromWarehouse || null,
    toWarehouse: item.toWarehouse || null,
    uom: item.uom || null,
    quantity,
    transferredQuantity: Number(item.transferredQuantity) || 0,
    unitPrice,
    itemCost,
    accountCode: item.accountCode || null,
    project: item.project || null,
    remarks: item.remarks || null,
    amount: round2(quantity * unitPrice),
  };
}

function computeStockTransferRequestTotals(items) {
  return { amount: round2(items.reduce((sum, i) => sum + round2(i.amount), 0)) };
}

router.get('/inventory/stock-transfer-requests', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { requestNo: { contains: q } },
        { partyName: { contains: q } },
      ],
    }
    : undefined;
  // OR across branch + toBranch (not the plain withBranchScope default of
  // `branch` alone): a user notified as the destination-branch side of a
  // transfer (see approverResolution.js) needs to be able to find/open it
  // here too, or clicking through from their notification 404s.
  const rows = await prisma.stockTransferRequest.findMany({ where: withBranchScopeAny(where, req, ['branch', 'toBranch']), include: stockTransferRequestInclude, orderBy: { id: 'desc' } });
  res.json({ success: true, data: rows });
}));

router.get('/inventory/stock-transfer-requests/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.stockTransferRequest.findUnique({ where: { id: Number(req.params.id) }, include: stockTransferRequestInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  res.json({ success: true, data: row });
}));

router.post('/inventory/stock-transfer-requests', auth(), asyncHandler(async (req, res) => {
  const { items = [], seriesId, ...rawHeader } = req.body;
  // createdById is server-owned (the sender identity notifications depend on).
  const header = sanitizeHeader(rawHeader, { alsoBlock: ['createdById'] });
  const { row, recipients, notifications } = await prisma.$transaction(async (tx) => {
    const itemData = items.map((i) => toStockTransferRequestItemData(i));
    const totals = computeStockTransferRequestTotals(itemData);
    const { documentNumber, syncManual } = await resolveDocumentNumber('MR', header.requestNo, tx, seriesId || null);
    // approvalStatus defaults to 'Pending' (see schema.prisma) — every new
    // request starts out needing sign-off. The approval gate and its
    // notification trigger on THIS creation step (not on the Stock Transfer
    // raised from it later) — see utils/approverResolution.js for how the
    // recipients below are chosen.
    const created = await tx.stockTransferRequest.create({
      data: { ...header, requestNo: documentNumber, ...totals, createdById: req.user.id, items: { create: itemData } },
      include: stockTransferRequestInclude,
    });
    if (syncManual) await syncManual();
    const resolved = await resolveStockTransferRequestApprovers({
      amount: created.amount,
      branch: created.branch,
      toBranch: created.toBranch,
      senderId: req.user.id,
    });
    // Rows are collected (not createMany) so the ids can be pushed below.
    const rows = await createApprovalRequestNotifications(tx, {
      referenceType: 'StockTransferRequest',
      request: created,
      recipients: resolved,
    });
    return { row: created, recipients: resolved, notifications: rows };
  });
  // Real-time push only AFTER the transaction commits — emitting inside an
  // open transaction could notify someone about a row that later rolls back.
  await emitNotifications(notifications.map((notification) => ({ kind: 'new', notification })));
  res.status(201).json({
    success: true,
    data: row,
    // Not an error: the request is saved, but nobody will be asked to approve
    // it until an admin exists or a user is granted Notification + branch access.
    ...(recipients.length ? {} : { warning: 'No eligible approver was found for this request' }),
  });
}));

router.put('/inventory/stock-transfer-requests/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  const { items = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader, { alsoBlock: ['createdById'] });
  const { row, events } = await prisma.$transaction(async (tx) => {
    const before = await tx.stockTransferRequest.findUnique({
      where: { id },
      select: { amount: true, branch: true, toBranch: true, approvalStatus: true, createdById: true },
    });
    await tx.stockTransferRequestItem.deleteMany({ where: { requestId: id } });
    const itemData = items.map((i) => toStockTransferRequestItemData(i));
    const totals = computeStockTransferRequestTotals(itemData);
    const updated = await tx.stockTransferRequest.update({
      where: { id },
      data: { ...header, ...totals, items: { create: itemData } },
      include: stockTransferRequestInclude,
    });

    // Re-route notifications only when something that decides WHO approves
    // changed (amount / source / destination) and the request is still
    // waiting. Anyone who already has a row is never notified twice.
    const pendingEvents = [];
    const routingChanged = before && before.approvalStatus === 'Pending'
      && (Number(before.amount) !== Number(updated.amount) || before.branch !== updated.branch || before.toBranch !== updated.toBranch);
    if (routingChanged) {
      // The ORIGINAL sender stays excluded (not the editor); legacy rows with
      // no createdById simply exclude nobody.
      const recipients = await resolveStockTransferRequestApprovers({
        amount: updated.amount,
        branch: updated.branch,
        toBranch: updated.toBranch,
        senderId: before.createdById,
      });
      const eligibleIds = new Set(recipients.map((r) => r.id));
      const existing = await tx.notification.findMany({
        where: { referenceType: 'StockTransferRequest', referenceId: id, type: 'ApprovalRequest' },
      });
      const existingByUser = new Map(existing.map((n) => [n.userId, n]));

      // No longer eligible and still open -> Cancelled.
      const dropped = existing.filter((n) => !n.actionStatus && !eligibleIds.has(n.userId)).map((n) => n.userId);
      if (dropped.length) {
        pendingEvents.push(...await closeOpenRequestNotifications(tx, {
          referenceType: 'StockTransferRequest', referenceId: id, actionStatus: 'Cancelled', userIds: dropped,
        }));
      }
      // Newly eligible -> new row; a user whose earlier row was Cancelled and
      // who is eligible again gets THAT row re-opened (never a second row).
      const fresh = [];
      for (const user of recipients) {
        const had = existingByUser.get(user.id);
        if (!had) {
          fresh.push(user);
        } else if (had.actionStatus === 'Cancelled') {
          const reopened = await tx.notification.update({ where: { id: had.id }, data: { status: 'Unread', actionStatus: null } });
          pendingEvents.push({ kind: 'new', notification: reopened });
        }
      }
      const created = await createApprovalRequestNotifications(tx, { referenceType: 'StockTransferRequest', request: updated, recipients: fresh });
      pendingEvents.push(...created.map((notification) => ({ kind: 'new', notification })));
    }
    return { row: updated, events: pendingEvents };
  });
  await emitNotifications(events);
  res.json({ success: true, data: row });
}));

router.delete('/inventory/stock-transfer-requests/:id', auth(['admin']), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // StockTransferRequestItem.request has onDelete: Cascade, so items go with it.
  // Notification.referenceId is a loose reference (no FK), so it does NOT
  // cascade: without this step every approver's row would be stuck "Pending"
  // with live Approve/Reject buttons that error on click. Only open
  // ApprovalRequest rows are cancelled; ApprovalResult rows are left alone.
  const events = await prisma.$transaction(async (tx) => {
    const cancelled = await closeOpenRequestNotifications(tx, {
      referenceType: 'StockTransferRequest', referenceId: id, actionStatus: 'Cancelled',
    });
    await tx.stockTransferRequest.delete({ where: { id } });
    return cancelled;
  });
  await emitNotifications(events);
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Stock Transfer Receipt — confirms goods arrived at the destination
// warehouse, raised AFTER a Stock Transfer. Deliberately simple (v1 scope):
// no batch/serial allocation of its own. Referenced to Stock Transfer via
// transferNo (string-match, same convention as GoodsReceivedNote.poNo ->
// PurchaseOrder.poNo). Not wired into documentFlow.js yet.
//
// This document itself still has NO stock-ledger effect and NO G/L posting —
// that used to also describe the Stock Transfer it confirms, but no longer
// does: a Stock Transfer now posts stock/G/L as soon as it is raised (or
// approved), so by the time a Receipt exists against it, the movement it is
// "confirming" has normally already happened. Saving/deleting a Receipt below
// only flips the Stock Transfer's own status between 'Open' and 'Closed' —
// see syncStockTransferClosure's own doc comment for exactly what that still
// means and the narrow safety-net case where it can still trigger a first
// posting.
const stockTransferReceiptInclude = { items: { orderBy: { id: 'asc' } } };

function toStockTransferReceiptItemData(item) {
  const quantity = Number(item.quantity) || 0;
  const unitPrice = Number(item.unitPrice) || 0;
  const itemCost = item.itemCost != null ? Number(item.itemCost) : unitPrice;
  return {
    baseType: item.baseType || null,
    baseEntry: item.baseEntry != null ? Number(item.baseEntry) : null,
    baseNo: item.baseNo || null,
    baseLine: item.baseLine != null ? Number(item.baseLine) : null,
    productCode: item.productCode || null,
    productName: item.productName || null,
    fromWarehouse: item.fromWarehouse || null,
    toWarehouse: item.toWarehouse || null,
    uom: item.uom || null,
    transferQuantity: Number(item.transferQuantity) || 0,
    quantity,
    unitPrice,
    itemCost,
    accountCode: item.accountCode || null,
    project: item.project || null,
    remarks: item.remarks || null,
    amount: round2(quantity * unitPrice),
  };
}

function computeStockTransferReceiptTotals(items) {
  return { amount: round2(items.reduce((sum, i) => sum + round2(i.amount), 0)) };
}

router.get('/inventory/stock-transfer-receipts', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { receiptNo: { contains: q } },
        { transferNo: { contains: q } },
        { partyName: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.stockTransferReceipt.findMany({ where: withBranchScope(where, req), include: stockTransferReceiptInclude, orderBy: { id: 'desc' } });
  res.json({ success: true, data: rows });
}));

router.get('/inventory/stock-transfer-receipts/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.stockTransferReceipt.findUnique({ where: { id: Number(req.params.id) }, include: stockTransferReceiptInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  res.json({ success: true, data: row });
}));

router.post('/inventory/stock-transfer-receipts', auth(), asyncHandler(async (req, res) => {
  const { items = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const row = await prisma.$transaction(async (tx) => {
    const itemData = items.map((i) => toStockTransferReceiptItemData(i));
    const totals = computeStockTransferReceiptTotals(itemData);
    const { documentNumber, syncManual } = await resolveDocumentNumber('MC', header.receiptNo, tx, seriesId || null);
    const created = await tx.stockTransferReceipt.create({
      data: { ...header, receiptNo: documentNumber, ...totals, items: { create: itemData } },
      include: stockTransferReceiptInclude,
    });
    if (syncManual) await syncManual();
    // Confirming a receipt against a Stock Transfer closes it (flips
    // 'Open' -> 'Closed') — see syncStockTransferClosure's own doc comment
    // for why that no longer also means "this is when stock/G/L post".
    await syncStockTransferClosure(tx, { transferNo: created.transferNo || null, userId: req.user?.id, receiptItems: created.items });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/inventory/stock-transfer-receipts/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  const { items = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const row = await prisma.$transaction(async (tx) => {
    // Read before update — needed to detect a transferNo change so the old
    // transfer can be reopened (see syncStockTransferClosure below).
    const existing = await tx.stockTransferReceipt.findUnique({ where: { id }, select: { transferNo: true } });
    await tx.stockTransferReceiptItem.deleteMany({ where: { receiptId: id } });
    const itemData = items.map((i) => toStockTransferReceiptItemData(i));
    const totals = computeStockTransferReceiptTotals(itemData);
    const updated = await tx.stockTransferReceipt.update({
      where: { id },
      data: { ...header, ...totals, items: { create: itemData } },
      include: stockTransferReceiptInclude,
    });
    // Reflect any change in which transfer this receipt confirms — reopens
    // the old one (if any) and closes the new one (if any).
    await syncStockTransferClosure(tx, {
      previousTransferNo: existing?.transferNo || null,
      transferNo: updated.transferNo || null,
      userId: req.user?.id,
      receiptItems: updated.items,
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/inventory/stock-transfer-receipts/:id', auth(['admin']), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  await prisma.$transaction(async (tx) => {
    // StockTransferReceiptItem.receipt has onDelete: Cascade, so items go with it.
    const deleted = await tx.stockTransferReceipt.delete({ where: { id } });
    // The receipt that closed this transfer is gone — reopen it (flip back
    // to 'Open'). Does NOT reverse the transfer's stock/G/L: those were
    // posted at Issue/approval time, not by this Receipt, so deleting a mere
    // confirmation does not undo a movement that already physically
    // happened — see syncStockTransferClosure's own doc comment.
    await syncStockTransferClosure(tx, { previousTransferNo: deleted.transferNo || null, transferNo: null, userId: req.user?.id });
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));


// Receivables
// Bespoke aging-report endpoint for the Customer Outstanding page — mounted
// BEFORE the crudRouter below so `/report` doesn't get swallowed by that
// router's `/:id` route. Follows the dashboard.js style (auth + asyncHandler,
// prisma query + JS reshaping, single JSON response) rather than crudRouter,
// since this is a computed aggregate, not a CRUD resource.
// customerGroup filters against Customer.customerType (there's no separate
// "customer group" table/column — customerType is the only classification
// field on Customer, and its sample values, Manufacturing/Trading/
// Construction/Retail, match the report design's "Customer Group" exactly).
// "outstandingType" (All / Invoices + Debit Notes) and "currency" are
// no-ops — there's no DebitNote model in this schema (CustomerOutstanding
// rows are always sales-invoice-derived), and neither CustomerOutstanding
// nor Customer stores a currency column, so every row is implicitly the
// company's base currency. "Branch" DOES filter for real — BusinessPartner
// has its own branch column, applied against customerWhere below.
router.get('/receivables/outstanding/report', auth(), asyncHandler(async (req, res) => {
  const {
    branch, customerGroup, salesPerson, customerName, outstandingType, include,
    showInactiveCustomers, currency, asOnDate, agingBasedOn,
  } = req.query;
  const basisField = agingBasedOn === 'Invoice Date' ? 'invoiceDate' : 'dueDate';
  const asOn = asOnDate ? new Date(asOnDate) : new Date();
  asOn.setHours(0, 0, 0, 0);

  const customerWhere = { partnerType: 'Customer' };
  // customerGroup ("Customer Group") is a no-op — that classification lived
  // on the retired Customer Master's customerType field, which Business
  // Partner has no equivalent of.
  if (salesPerson) customerWhere.salesPerson = salesPerson;
  if (customerName) customerWhere.partnerName = customerName;
  if (branch) customerWhere.branch = branch;
  // Default is to hide inactive customers, same "Show Inactive Customers"
  // convention used on list pages elsewhere in the app.
  if (showInactiveCustomers !== 'Yes') customerWhere.status = 'Active';

  const customers = await prisma.businessPartner.findMany({ where: customerWhere });
  const names = customers.map((c) => c.partnerName);

  const outstandingRows = names.length
    ? await prisma.customerOutstanding.findMany({ where: { customerName: { in: names } } })
    : [];

  const rowsByName = {};
  outstandingRows.forEach((row) => {
    const name = row.customerName || 'Unknown';
    (rowsByName[name] = rowsByName[name] || []).push(row);
  });

  // Base iteration is over the filtered Customer list (not just customers
  // who happen to have an outstanding row), so "Include: All Customers"
  // can surface zero-balance customers too.
  const allRows = customers.map((cust) => {
    const custRows = rowsByName[cust.partnerName] || [];
    // Five underlying buckets — notDue (not yet due) and d1to30 (1-30 days
    // overdue) are tracked separately so the Receivables > Customer
    // Outstanding page (which shows them as distinct "Current" / "1 - 30
    // Days" columns) can use them. `current` is kept as notDue + d1to30
    // combined, exactly as before, so the Reports > Customer Outstanding
    // page's existing "0 - 30 Days" column/chart is unaffected.
    const bucket = { notDue: 0, d1to30: 0, d31to60: 0, d61to90: 0, above90: 0 };
    let overdueDays = 0;
    let lastInvoiceDate = null;
    // Sum of every invoice raised for this customer (Paid included), as
    // opposed to totalOutstanding below which only counts the unpaid
    // remainder. This is what a collection against the customer must NOT
    // move — it's a running record of everything ever invoiced, so the
    // aging buckets/Total Outstanding can shrink as payments come in
    // without this figure moving with them.
    let totalInvoiceAmount = 0;

    custRows.forEach((row) => {
      if (row.invoiceDate && (!lastInvoiceDate || new Date(row.invoiceDate) > new Date(lastInvoiceDate))) {
        lastInvoiceDate = row.invoiceDate;
      }
      totalInvoiceAmount += Number(row.invoiceAmount || 0);

      const balance = row.balanceAmount != null
        ? Number(row.balanceAmount)
        : Number(row.invoiceAmount || 0) - Number(row.paidAmount || 0);
      if (row.status === 'Paid' || balance <= 0) return;

      const basisDate = row[basisField];
      let daysOverdue = 0;
      if (basisDate) {
        const d = new Date(basisDate);
        d.setHours(0, 0, 0, 0);
        daysOverdue = Math.round((asOn - d) / (1000 * 60 * 60 * 24));
      }
      if (daysOverdue > overdueDays) overdueDays = daysOverdue;

      if (daysOverdue <= 0) bucket.notDue += balance;
      else if (daysOverdue <= 30) bucket.d1to30 += balance;
      else if (daysOverdue <= 60) bucket.d31to60 += balance;
      else if (daysOverdue <= 90) bucket.d61to90 += balance;
      else bucket.above90 += balance;
    });

    // Total Outstanding is the money actually still owed — the sum of the
    // unpaid buckets — NOT the sum of every invoice ever raised for this
    // customer. Summing raw invoiceAmount regardless of paid status (the
    // previous behavior) meant a customer with one Paid and one Unpaid
    // invoice showed a Total Outstanding bigger than what any of the aging
    // columns added up to, and a customer whose invoices were all fully
    // paid still showed a nonzero Total Outstanding.
    const totalOutstanding = bucket.notDue + bucket.d1to30 + bucket.d31to60 + bucket.d61to90 + bucket.above90;
    const status = totalOutstanding <= 0 ? 'No Outstanding' : (overdueDays > 0 ? 'Overdue' : 'Current');
    // Row-level overdue total — everything past due, i.e. every bucket
    // except notDue.
    const overdueAmount = bucket.d1to30 + bucket.d31to60 + bucket.d61to90 + bucket.above90;

    return {
      customerCode: cust.partnerCode,
      customerName: cust.partnerName,
      // Business Partner has no equivalent of the retired Customer Master's
      // customerType ("Customer Group") — always 'Uncategorized' now.
      customerGroup: 'Uncategorized',
      salesPerson: cust.salesPerson || '—',
      creditLimit: Number(cust.creditLimit || 0),
      totalInvoiceAmount,
      totalOutstanding,
      current: bucket.notDue + bucket.d1to30,
      ...bucket,
      overdueAmount,
      overdueDays,
      lastInvoiceDate,
      status,
    };
  }).sort((a, b) => a.customerCode.localeCompare(b.customerCode));

  // "Include" narrows to customers who actually carry a balance — the
  // default working set for this report — same "default narrows, All
  // widens" pattern used on the inventory reports above.
  const rows = include === 'All Customers' ? allRows : allRows.filter((r) => r.totalOutstanding > 0);

  const totals = rows.reduce((acc, r) => {
    acc.notDue += r.notDue;
    acc.d1to30 += r.d1to30;
    acc.current += r.current;
    acc.d31to60 += r.d31to60;
    acc.d61to90 += r.d61to90;
    acc.above90 += r.above90;
    acc.totalOutstanding += r.totalOutstanding;
    acc.totalInvoiceAmount += r.totalInvoiceAmount;
    acc.creditLimit += r.creditLimit;
    return acc;
  }, {
    notDue: 0, d1to30: 0, current: 0, d31to60: 0, d61to90: 0, above90: 0, totalOutstanding: 0, totalInvoiceAmount: 0, creditLimit: 0,
  });
  // Everything past due — every bucket except notDue. (Previously omitted
  // d1to30, which under-counted "overdue"; nothing downstream depended on
  // that number, since this field wasn't surfaced on any page until now.)
  totals.overdue = totals.d1to30 + totals.d31to60 + totals.d61to90 + totals.above90;

  // "Due Today" stat always uses dueDate specifically (regardless of the
  // Aging Based On filter), matching the design's literal "Due Today" label.
  let dueToday = 0;
  outstandingRows.forEach((row) => {
    const balance = row.balanceAmount != null
      ? Number(row.balanceAmount)
      : Number(row.invoiceAmount || 0) - Number(row.paidAmount || 0);
    if (row.status === 'Paid' || balance <= 0 || !row.dueDate) return;
    const d = new Date(row.dueDate);
    d.setHours(0, 0, 0, 0);
    if (d.getTime() === asOn.getTime()) dueToday += balance;
  });

  // Outstanding by Ageing — donut over the four buckets, across the full
  // filtered/included set.
  const ageingTotal = totals.totalOutstanding || 1;
  const outstandingByAgeing = [
    { name: '0 - 30 Days', value: Math.round(totals.current), percent: Math.round((totals.current / ageingTotal) * 1000) / 10 },
    { name: '31 - 60 Days', value: Math.round(totals.d31to60), percent: Math.round((totals.d31to60 / ageingTotal) * 1000) / 10 },
    { name: '61 - 90 Days', value: Math.round(totals.d61to90), percent: Math.round((totals.d61to90 / ageingTotal) * 1000) / 10 },
    { name: 'Above 90 Days', value: Math.round(totals.above90), percent: Math.round((totals.above90 / ageingTotal) * 1000) / 10 },
  ];

  // Top 10 Customers by Outstanding Amount.
  const topCustomersByOutstanding = [...rows].sort((a, b) => b.totalOutstanding - a.totalOutstanding).slice(0, 10)
    .map((r) => ({ name: r.customerName, value: Math.round(r.totalOutstanding) }));

  // Outstanding by Customer Group (Top 5 + Others).
  const byGroupValue = {};
  rows.forEach((r) => { byGroupValue[r.customerGroup] = (byGroupValue[r.customerGroup] || 0) + r.totalOutstanding; });
  const groupEntries = Object.entries(byGroupValue).sort((a, b) => b[1] - a[1]);
  const groupGrandTotal = totals.totalOutstanding || 1;
  const top5Groups = groupEntries.slice(0, 5);
  const othersGroupValue = groupEntries.slice(5).reduce((sum, [, v]) => sum + v, 0);
  const outstandingByCustomerGroup = [
    ...top5Groups.map(([name, value]) => ({ name, value: Math.round(value), percent: Math.round((value / groupGrandTotal) * 1000) / 10 })),
    ...(othersGroupValue > 0 ? [{ name: 'Others', value: Math.round(othersGroupValue), percent: Math.round((othersGroupValue / groupGrandTotal) * 1000) / 10 }] : []),
  ];

  res.json({
    success: true,
    data: {
      asOnDate: asOn,
      agingBasedOn: agingBasedOn || 'Due Date',
      stats: {
        totalCustomers: rows.length,
        totalOutstandingAmount: totals.totalOutstanding,
        current: totals.current,
        d31to60: totals.d31to60,
        d61to90: totals.d61to90,
        above90: totals.above90,
        overdueAmount: totals.overdue,
        dueToday,
      },
      rows,
      totals,
      outstandingByAgeing,
      topCustomersByOutstanding,
      outstandingByCustomerGroup,
    },
  });
}));

router.use('/receivables/outstanding', crudRouter(prisma.customerOutstanding, { searchFields: ['customerName', 'invoiceNo'] }));

// Collection Entry -- a master/detail resource (Collection has many
// CollectionInvoiceApplication rows), same bespoke-route pattern as
// PurchaseInvoice/ApprovalFlow (mirrors crudRouter's URL/method/response
// shape so the frontend keeps using the generic collectionApi from
// createCrudApi). Replaces the old flat crudRouter(prisma.collection, ...)
// mount now that the model has a nested line-items collection.
// Customer receipts and supplier payments settle open items through the same
// ledger (utils/openItemLedger.js). It replaced two hand-rolled copies whose
// apply and reverse steps clamped differently — apply floored the balance at
// zero, reverse capped it at the invoice amount — so once two receipts had
// closed an invoice, reversing either one restored the wrong balance and the
// difference was unrecoverable. The ledger only ever moves `paidAmount`, by
// exactly the amount applied, and recomputes the balance from it, which makes
// apply/reverse an exact identity in any order.
const customerLedger = createOpenItemLedger({
  delegateOf: (tx) => tx.customerOutstanding,
  partyField: 'customerName',
  documentWord: 'receipt',
});

const supplierLedger = createOpenItemLedger({
  delegateOf: (tx) => tx.supplierOutstanding,
  partyField: 'supplierName',
  documentWord: 'payment',
});

const applyToCustomerOutstanding = (tx, apps) => customerLedger.apply(tx, apps);
const reverseCustomerOutstanding = (tx, apps) => customerLedger.reverse(tx, apps);
const applyToSupplierOutstanding = (tx, apps) => supplierLedger.apply(tx, apps);
const reverseSupplierOutstanding = (tx, apps) => supplierLedger.reverse(tx, apps);

// Maps the open-item ledger's settlement status (Paid/Partial/Unpaid, see
// utils/openItemLedger.js's settlementStatus()) to the wording SalesInvoice
// and SalesOrder use for the same idea ('Paid'/'Partially Paid'/'Unpaid').
function toPaymentStatus(ledgerStatus) {
  if (ledgerStatus === 'Paid') return 'Paid';
  if (ledgerStatus === 'Partial') return 'Partially Paid';
  return 'Unpaid';
}

// A sales order's paymentStatus follows the invoice(s) raised against it —
// Paid once every one of them is Paid, Partially Paid as soon as any of them
// carries a payment, otherwise Unpaid. An order with no active invoice yet is
// left alone (still whatever it was created with) rather than being forced to
// Unpaid, so this never fights with an order that was never invoiced.
async function recomputeSalesOrderPaymentStatus(tx, orderNo) {
  if (!orderNo) return;
  const invoices = await tx.salesInvoice.findMany({
    where: { orderNo, status: { notIn: ['Draft', 'Cancelled'] } },
    select: { paymentStatus: true },
  });
  if (!invoices.length) return;
  let paymentStatus = 'Unpaid';
  if (invoices.every((inv) => inv.paymentStatus === 'Paid')) paymentStatus = 'Paid';
  else if (invoices.some((inv) => inv.paymentStatus === 'Paid' || inv.paymentStatus === 'Partially Paid')) paymentStatus = 'Partially Paid';
  await tx.salesOrder.updateMany({ where: { orderNo }, data: { paymentStatus } });
}

// Keeps SalesInvoice.paymentStatus — and, through it, the fulfilling
// SalesOrder's paymentStatus — in step with what CustomerOutstanding actually
// records as settled. Collection Entry only ever wrote to CustomerOutstanding
// itself (via customerLedger.apply/reverse above); nothing propagated that
// back to the invoice or order, so both kept showing "Unpaid" forever even
// after a collection paid the invoice off in full. Called after every place
// that changes an invoice's open-item balance: posting/editing/deleting a
// Collection, and creating/editing the invoice itself.
async function syncSalesInvoicePaymentStatus(tx, invoiceNo) {
  if (!invoiceNo) return;
  const openItem = await tx.customerOutstanding.findFirst({ where: { invoiceNo } });
  const paymentStatus = toPaymentStatus(openItem?.status);
  const invoice = await tx.salesInvoice.findFirst({ where: { invoiceNo } });
  if (!invoice) return;
  if (invoice.paymentStatus !== paymentStatus) {
    await tx.salesInvoice.update({ where: { id: invoice.id }, data: { paymentStatus } });
  }
  await recomputeSalesOrderPaymentStatus(tx, invoice.orderNo);
}

// Keeps PurchaseInvoice.paymentStatus in step with what SupplierOutstanding
// actually records as settled — same gap as SalesInvoice above, mirrored on
// the payables side: Payment Entry only ever wrote to SupplierOutstanding
// itself (via supplierLedger.apply/reverse above), so a purchase invoice paid
// off in full through Payment Entry still showed "Unpaid" forever. Unlike
// SalesOrder, PurchaseOrder has no paymentStatus column at all (see
// schema.prisma), so there is no order-level cascade needed here — this is
// the whole fix. Called after every place that changes an invoice's open-item
// balance: posting/editing/deleting a Payment Entry, and creating/editing the
// invoice itself.
async function syncPurchaseInvoicePaymentStatus(tx, invoiceNo) {
  if (!invoiceNo) return;
  const openItem = await tx.supplierOutstanding.findFirst({ where: { invoiceNo } });
  const paymentStatus = toPaymentStatus(openItem?.status);
  const invoice = await tx.purchaseInvoice.findFirst({ where: { invoiceNo } });
  if (!invoice) return;
  if (invoice.paymentStatus !== paymentStatus) {
    await tx.purchaseInvoice.update({ where: { id: invoice.id }, data: { paymentStatus } });
  }
}

const collectionInclude = { invoiceApplications: { orderBy: { id: 'asc' } } };

function toCollectionApplicationData(app) {
  return {
    invoiceNo: app.invoiceNo || null,
    invoiceDate: app.invoiceDate || null,
    dueDate: app.dueDate || null,
    totalAmount: app.totalAmount != null ? Number(app.totalAmount) : 0,
    outstandingAtTimeOfApplication: app.outstandingAtTimeOfApplication != null ? Number(app.outstandingAtTimeOfApplication) : 0,
    amountApplied: app.amountApplied != null ? Number(app.amountApplied) : 0,
  };
}



router.get('/receivables/collections', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { collectionNo: { contains: q } },
        { customerName: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.collection.findMany({ where: withBranchScope(where, req), include: collectionInclude, orderBy: { id: 'desc' } });
  res.json({ success: true, data: rows });
}));

router.get('/receivables/collections/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.collection.findUnique({ where: { id: Number(req.params.id) }, include: collectionInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  res.json({ success: true, data: row });
}));

router.post('/receivables/collections', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue collectionNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { invoiceApplications = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const appData = invoiceApplications.map(toCollectionApplicationData);
  const totalAppliedAmount = appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0);
  const row = await prisma.$transaction(async (tx) => {
    // collectionNo now comes from the configured RV (Receipt Voucher)
    // numbering series rather than free text — see resolveDocumentNumber
    // above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('RV', header.collectionNo, tx, seriesId || null);
    const created = await tx.collection.create({
      data: { ...header, collectionNo: documentNumber, totalAppliedAmount, invoiceApplications: { create: appData } },
      include: collectionInclude,
    });
    if (syncManual) await syncManual();
    if (created.status === 'Posted') {
      // Validate before applying, and after any previous version of this
      // receipt has been reversed, so the balances checked are the ones the
      // new applications will actually be measured against. A receipt that
      // over-settles is rejected outright rather than partially posted.
      await customerLedger.assertApplicationsValid(tx, appData, {
        paymentAmount: created.paymentAmount,
        partyName: created.customerName,
      });
      await applyToCustomerOutstanding(tx, appData);
      for (const app of appData) {
        if (app.invoiceNo) await syncSalesInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
    await syncBankReconciliationTxn(tx, {
      bankAccount: created.depositTo, voucherType: 'Receipt', voucherNo: created.collectionNo,
      txnDate: created.receiptDate, type: 'Credit', amount: created.paymentAmount,
      description: `Receipt from ${created.customerName || 'customer'}`, remarks: created.notes,
      isActive: created.status === 'Posted',
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/receivables/collections/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { invoiceApplications = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const appData = invoiceApplications.map(toCollectionApplicationData);
  const totalAppliedAmount = appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0);
  // Replace the applied-invoice set wholesale on every save -- simpler and
  // safer than diffing which rows were added/removed/edited client-side.
  const row = await prisma.$transaction(async (tx) => {
    // If this collection was already Posted before this save, its previous
    // invoiceApplications were already subtracted from CustomerOutstanding —
    // reverse that first so re-saving (with the same or edited amounts)
    // doesn't double-decrement the invoice balance.
    const existing = await tx.collection.findUnique({ where: { id }, include: collectionInclude });
    if (existing?.status === 'Posted') {
      await reverseCustomerOutstanding(tx, existing.invoiceApplications);
    }
    await tx.collectionInvoiceApplication.deleteMany({ where: { collectionId: id } });
    const updated = await tx.collection.update({
      where: { id },
      data: { ...header, totalAppliedAmount, invoiceApplications: { create: appData } },
      include: collectionInclude,
    });
    if (updated.status === 'Posted') {
      // Validate before applying, and after any previous version of this
      // receipt has been reversed, so the balances checked are the ones the
      // new applications will actually be measured against. A receipt that
      // over-settles is rejected outright rather than partially posted.
      await customerLedger.assertApplicationsValid(tx, appData, {
        paymentAmount: updated.paymentAmount,
        partyName: updated.customerName,
      });
      await applyToCustomerOutstanding(tx, appData);
    }
    // Sync every invoice touched by either the old or the new application
    // set — an invoice dropped from this collection needs its paymentStatus
    // pulled back down just as much as one newly added to it needs pushing up.
    const touchedInvoiceNos = new Set([
      ...(existing?.invoiceApplications || []).map((a) => a.invoiceNo).filter(Boolean),
      ...appData.map((a) => a.invoiceNo).filter(Boolean),
    ]);
    for (const invoiceNo of touchedInvoiceNos) {
      await syncSalesInvoicePaymentStatus(tx, invoiceNo);
    }
    await syncBankReconciliationTxn(tx, {
      bankAccount: updated.depositTo, voucherType: 'Receipt', voucherNo: updated.collectionNo,
      txnDate: updated.receiptDate, type: 'Credit', amount: updated.paymentAmount,
      description: `Receipt from ${updated.customerName || 'customer'}`, remarks: updated.notes,
      isActive: updated.status === 'Posted',
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/receivables/collections/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // CollectionInvoiceApplication.collection has onDelete: Cascade, so
  // applications go with it. If this collection was Posted, its effect on
  // CustomerOutstanding needs reversing first, or the deleted collection's
  // payment stays "applied" forever with no record of why the balance is low.
  await prisma.$transaction(async (tx) => {
    const existing = await tx.collection.findUnique({ where: { id: Number(req.params.id) }, include: collectionInclude });
    if (existing?.status === 'Posted') {
      await reverseCustomerOutstanding(tx, existing.invoiceApplications);
    }
    if (existing) {
      await syncBankReconciliationTxn(tx, {
        bankAccount: existing.depositTo, voucherNo: existing.collectionNo, isActive: false,
      });
    }
    await tx.collection.delete({ where: { id: Number(req.params.id) } });
    if (existing?.status === 'Posted') {
      for (const app of existing.invoiceApplications) {
        if (app.invoiceNo) await syncSalesInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Collection Register report — bespoke aggregation endpoint for the
// Reports > Receivable > Collection Register page.
//
// RECONCILES WITH THE DASHBOARD'S "Total Receivables" CARD
// (routes/dashboard.js) and with the Sales Invoice Register, using the same
// rules as the Payment Register on the payable side:
//   * partyType=Customer (default): every Collection ("Receipt Entry") AND
//     every Payment Receipt ("Incoming Payment") against a Customer — the
//     two document types the dashboard sums. Paid Amount is what was actually
//     APPLIED to active (non-Draft/Cancelled) sales invoices by a Posted,
//     not-on-account document, capped per invoice at the invoice's own
//     amount. With the default filters stats.totalCollections === dashboard
//     totalReceivables.
//   * Every collection document is LISTED whatever its status (Posted /
//     Draft / Cancelled) and whether or not it settled an invoice, so nothing
//     is hidden; only `counted` rows (Posted, settling an active invoice)
//     feed the totals and stat cards, which keeps them equal to the dashboard.
//   * Invoice Amount is the Sales Invoice's own `amount` — the "Net Amount"
//     the Sales Invoice Register shows — counted ONCE per invoice (on the
//     earliest receipt that settles it). Sales invoices no counted receipt
//     settles are listed too, as an invoice-only row (no receipt no., Paid
//     Amount 0, Outstanding = the invoice amount, Status = the invoice's own
//     Paid/Unpaid/Partial state), so the Invoice Amount total equals the
//     Sales Invoice Register's Net Amount total.
//   * partyType=Account / Vendor: Payment Receipts against a Chart-of-Accounts
//     Account or a Vendor (e.g. a supplier refund) — no sales invoices are
//     involved, so Invoice Amount is 0 and Paid Amount is the receipt amount.
//     An Account filter works on Account Code (`account`).
// Filters: fromDate/toDate (no bound when empty), branch, customer (name) or
// account (code), salesPerson, paymentMode, include (Posted Only / Draft Only
// / All Payments — default lists every status), currency.
router.get('/receivables/collection-register/report', auth(), asyncHandler(async (req, res) => {
  const {
    fromDate, toDate, customer, account, salesPerson, paymentMode, include, branch, currency,
  } = req.query;
  const partyType = ['Account', 'Vendor'].includes(req.query.partyType) ? req.query.partyType : 'Customer';

  const from = fromDate ? new Date(fromDate) : null;
  if (from) from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : null;
  if (to) to.setHours(23, 59, 59, 999);

  let statusFilter;
  if (include === 'Posted Only') statusFilter = { in: ['Posted'] };
  else if (include === 'Draft Only') statusFilter = { in: ['Draft'] };

  const normCurrency = (c) => String(c || 'INR').replace(/^N?'|'$/g, '').trim().toUpperCase() || 'INR';

  let candidates = [];
  let codeByPartyName = {};
  const invoiceAmountByNo = {};
  let capFactor = () => 1;

  if (partyType === 'Customer') {
    const [customers, allInvoices, collections, receipts] = await Promise.all([
      prisma.businessPartner.findMany({ where: { partnerType: 'Customer' }, select: { partnerName: true, partnerCode: true, salesPerson: true } }),
      // EVERY sales invoice (same population as the Sales Invoice Register) —
      // `status` separates the active ones used for settlement.
      prisma.salesInvoice.findMany({
        select: { invoiceNo: true, amount: true, customer: true, invoiceDate: true, paymentStatus: true, status: true, branch: true, salesPerson: true },
      }),
      prisma.collection.findMany({
        where: statusFilter ? { status: statusFilter } : {},
        include: { invoiceApplications: true },
      }),
      prisma.paymentReceipt.findMany({
        where: { partyType: 'Customer', ...(statusFilter ? { status: statusFilter } : {}) },
        include: { applications: true },
      }),
    ]);

    codeByPartyName = Object.fromEntries(customers.map((c) => [c.partnerName, c.partnerCode]));
    const salesPersonByName = Object.fromEntries(customers.map((c) => [c.partnerName, c.salesPerson]));
    // Settlement (and the dashboard's cap) only ever looks at active invoices.
    allInvoices
      .filter((i) => !['Draft', 'Cancelled'].includes(i.status))
      .forEach((i) => { if (i.invoiceNo) invoiceAmountByNo[i.invoiceNo] = Number(i.amount || 0); });

    // Per-invoice cap, computed over every POSTED application all-time (the
    // same population the dashboard caps over) so filtering by date/customer
    // never changes how much an individual receipt is credited.
    const appliedByInvoice = {};
    const addPosted = (apps) => apps.forEach((a) => {
      if (a.invoiceNo && Object.prototype.hasOwnProperty.call(invoiceAmountByNo, a.invoiceNo)) {
        appliedByInvoice[a.invoiceNo] = (appliedByInvoice[a.invoiceNo] || 0) + Number(a.amountApplied || 0);
      }
    });
    collections.filter((c) => c.status === 'Posted').forEach((c) => addPosted(c.invoiceApplications));
    receipts.filter((r) => r.status === 'Posted' && !r.paymentOnAccount).forEach((r) => addPosted(r.applications));
    capFactor = (invoiceNo) => {
      const applied = appliedByInvoice[invoiceNo] || 0;
      const cap = invoiceAmountByNo[invoiceNo];
      return applied > cap && applied > 0 ? cap / applied : 1;
    };

    const settle = (apps) => {
      let paidAmount = 0;
      let outstanding = 0;
      const invoiceNos = [];
      (apps || []).forEach((a) => {
        if (!a.invoiceNo || !Object.prototype.hasOwnProperty.call(invoiceAmountByNo, a.invoiceNo)) return; // not an active sales invoice
        const applied = Number(a.amountApplied || 0) * capFactor(a.invoiceNo);
        paidAmount += applied;
        outstanding += Math.max(Number(a.outstandingAtTimeOfApplication || 0) - applied, 0);
        if (!invoiceNos.includes(a.invoiceNo)) invoiceNos.push(a.invoiceNo);
      });
      return { paidAmount, outstanding, invoiceNos };
    };

    candidates = [
      ...collections.map((c) => ({
        key: `CL-${c.id}`,
        docNo: c.collectionNo,
        date: c.receiptDate,
        partyCode: null,
        partyName: c.customerName,
        paymentMode: c.paymentMode,
        referenceNo: c.instrumentNo,
        bankName: c.depositTo,
        collectedBy: c.receivedBy,
        status: c.status,
        branch: c.branch,
        currency: normCurrency(c.paymentCurrency),
        docAmount: Number(c.paymentAmount || 0),
        onAccount: false,
        ...settle(c.invoiceApplications),
      })),
      ...receipts.map((r) => ({
        key: `PR-${r.id}`,
        docNo: r.paymentReceiptNo,
        date: r.documentDate || r.postingDate,
        partyCode: r.partyCode,
        partyName: r.partyName,
        paymentMode: r.paymentMode,
        referenceNo: r.transactionNo || r.reference,
        bankName: r.paymentGlAccount,
        collectedBy: null,
        status: r.status,
        branch: r.branch,
        currency: normCurrency(r.currency),
        docAmount: Number(r.totalAmountDue || 0),
        onAccount: Boolean(r.paymentOnAccount),
        ...settle(r.applications),
      })),
    ].map((c) => {
      // Counted = exactly what the dashboard's "Total Receivables" counts: a
      // Posted, not-on-account document that settled an active sales
      // invoice. Anything else is still listed (full document amount) so no
      // receipt is hidden, but stays out of the totals.
      const counted = c.status === 'Posted' && !c.onAccount && c.invoiceNos.length > 0;
      return {
        ...c,
        counted,
        paidAmount: counted ? c.paidAmount : c.docAmount,
        outstanding: counted ? c.outstanding : 0,
        invoiceNos: counted ? c.invoiceNos : [],
      };
    });

    // Sales invoices that no counted receipt settles are still listed — as an
    // invoice-only row — so every invoice the Sales Invoice Register shows
    // also appears here.
    const coveredInvoices = new Set();
    candidates.filter((c) => c.counted).forEach((c) => c.invoiceNos.forEach((no) => coveredInvoices.add(no)));
    allInvoices
      .filter((i) => i.invoiceNo && !coveredInvoices.has(i.invoiceNo))
      .forEach((i) => {
        candidates.push({
          key: `SI-${i.invoiceNo}`,
          docNo: '—',
          date: i.invoiceDate,
          partyCode: null,
          partyName: i.customer,
          paymentMode: null,
          referenceNo: null,
          bankName: null,
          collectedBy: null,
          status: i.paymentStatus || 'Unpaid',
          branch: i.branch,
          currency: 'INR',
          docAmount: 0,
          onAccount: false,
          paidAmount: 0,
          outstanding: ['Paid'].includes(i.paymentStatus) ? 0 : Number(i.amount || 0),
          invoiceNos: [],
          counted: true,
          invoiceOnly: true,
          fixedInvoiceAmount: Number(i.amount || 0),
          salesPersonOverride: i.salesPerson,
        });
      });
    candidates = candidates
      .filter((c) => !customer || c.partyName === customer)
      .filter((c) => !salesPerson || (c.salesPersonOverride !== undefined ? c.salesPersonOverride : salesPersonByName[c.partyName]) === salesPerson);
  } else {
    const accountReceipts = await prisma.paymentReceipt.findMany({
      where: { partyType, ...(statusFilter ? { status: statusFilter } : {}) },
    });
    candidates = accountReceipts.map((r) => ({
      key: `PR-${r.id}`,
      docNo: r.paymentReceiptNo,
      date: r.documentDate || r.postingDate,
      partyCode: r.partyCode,
      partyName: r.partyName,
      paymentMode: r.paymentMode,
      referenceNo: r.transactionNo || r.reference,
      bankName: r.paymentGlAccount,
      collectedBy: null,
      status: r.status,
      branch: r.branch,
      currency: normCurrency(r.currency),
      paidAmount: Number(r.totalAmountDue || 0),
      outstanding: 0,
      invoiceNos: [],
      counted: r.status === 'Posted',
    }))
      .filter((c) => !account || c.partyCode === account);
    accountReceipts.forEach((r) => { if (r.partyCode) codeByPartyName[r.partyName] = r.partyCode; });
  }

  candidates = candidates
    .filter((c) => !paymentMode || c.paymentMode === paymentMode)
    .filter((c) => !branch || c.branch === branch)
    .filter((c) => !currency || c.currency === String(currency).toUpperCase());

  const toRow = (c, idx) => ({
    id: c.key,
    receiptNo: c.docNo,
    receiptDate: c.date,
    customerCode: codeByPartyName[c.partyName] || c.partyCode || '—',
    customerName: c.partyName || 'Unknown',
    supplierCode: c.partyCode || codeByPartyName[c.partyName] || '—',
    supplierName: c.partyName || 'Unknown',
    accountCode: c.partyCode || codeByPartyName[c.partyName] || '—',
    accountName: c.partyName || 'Unknown',
    paymentMode: c.paymentMode || '—',
    referenceNo: c.referenceNo || '—',
    bankName: c.bankName || '—',
    invoiceNos: c.invoiceNos,
    invoiceAmount: c.fixedInvoiceAmount != null ? c.fixedInvoiceAmount : 0,
    invoiceOnly: Boolean(c.invoiceOnly),
    paidAmount: c.paidAmount,
    outstanding: c.outstanding,
    collectedBy: c.collectedBy || '—',
    status: c.status,
    counted: c.counted,
    _t: c.date ? new Date(c.date).getTime() : 0,
    _i: idx,
  });

  const allRows = candidates.map(toRow).sort((a, b) => (b._t - a._t) || (a._i - b._i));
  const inPeriod = (r) => {
    if (!r._t) return !from && !to;
    if (from && r._t < from.getTime()) return false;
    if (to && r._t > to.getTime()) return false;
    return true;
  };
  const periodRows = allRows.filter(inPeriod);

  // Invoice Amount: the invoice's Net Amount (SalesInvoice.amount), once per
  // invoice, on the earliest receipt that settles it.
  const seenInvoices = new Set();
  [...periodRows].reverse().forEach((r) => {
    if (r.invoiceOnly) return;
    let amt = 0;
    r.invoiceNos.forEach((no) => {
      if (seenInvoices.has(no)) return;
      seenInvoices.add(no);
      amt += invoiceAmountByNo[no] || 0;
    });
    r.invoiceAmount = amt;
  });
  const rows = periodRows.map(({ _t, _i, invoiceNos, ...r }) => ({ ...r, receiptDate: r.invoiceOnly ? null : r.receiptDate }));

  const countedRows = rows.filter((r) => r.counted);
  const paidRows = countedRows.filter((r) => r.paidAmount > 0);
  const totals = countedRows.reduce((acc, r) => ({
    invoiceAmount: acc.invoiceAmount + r.invoiceAmount,
    paidAmount: acc.paidAmount + r.paidAmount,
    outstanding: acc.outstanding + r.outstanding,
  }), { invoiceAmount: 0, paidAmount: 0, outstanding: 0 });

  const totalCollections = totals.paidAmount;
  const KNOWN_MODES = ['Cash', 'Cheque', 'Bank Transfer', 'UPI', 'NEFT', 'RTGS'];
  const cashAmount = paidRows.filter((r) => r.paymentMode === 'Cash').reduce((sum, r) => sum + r.paidAmount, 0);
  const otherModeAmount = paidRows.filter((r) => !KNOWN_MODES.includes(r.paymentMode)).reduce((sum, r) => sum + r.paidAmount, 0);
  const bankAmount = Math.max(totalCollections - cashAmount - otherModeAmount, 0);

  // Collection by Payment Mode — donut over the exact payment mode values in
  // use (Top 5 + Others), across the counted set.
  const byModeValue = {};
  paidRows.forEach((r) => { byModeValue[r.paymentMode] = (byModeValue[r.paymentMode] || 0) + r.paidAmount; });
  const modeEntries = Object.entries(byModeValue).sort((a, b) => b[1] - a[1]);
  const modeGrandTotal = totalCollections || 1;
  const top5Modes = modeEntries.slice(0, 5);
  const othersModeValue = modeEntries.slice(5).reduce((sum, [, v]) => sum + v, 0);
  const collectionByPaymentMode = [
    ...top5Modes.map(([name, value]) => ({ name, value: Math.round(value), percent: Math.round((value / modeGrandTotal) * 1000) / 10 })),
    ...(othersModeValue > 0 ? [{ name: 'Others', value: Math.round(othersModeValue), percent: Math.round((othersModeValue / modeGrandTotal) * 1000) / 10 }] : []),
  ];

  // Collection Trend (Last 7 Days) — always the 7 calendar days ending at `to`
  // (or today), independent of the From date, built from the same reconciled
  // rows so it can never disagree with the table.
  const trendEnd = to ? new Date(to) : new Date();
  const trendDays = [];
  for (let i = 6; i >= 0; i -= 1) {
    const d = new Date(trendEnd);
    d.setDate(d.getDate() - i);
    d.setHours(0, 0, 0, 0);
    trendDays.push(d);
  }
  const pad2 = (n) => String(n).padStart(2, '0');
  const collectionTrend = trendDays.map((d) => {
    const dayTotal = allRows
      .filter((r) => r.counted && !r.invoiceOnly && r._t && new Date(r._t).toDateString() === d.toDateString())
      .reduce((sum, r) => sum + r.paidAmount, 0);
    return { name: `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}`, value: Math.round(dayTotal) };
  });

  // Top 5 Customers (or Accounts) by Collection.
  const byPartyValue = {};
  paidRows.forEach((r) => { byPartyValue[r.customerName] = (byPartyValue[r.customerName] || 0) + r.paidAmount; });
  const top5CustomersByCollection = Object.entries(byPartyValue).sort((a, b) => b[1] - a[1]).slice(0, 5)
    .map(([name, value]) => ({ name, value: Math.round(value) }));

  res.json({
    success: true,
    data: {
      partyType,
      rows,
      totals,
      stats: {
        totalCollections,
        totalReceipts: rows.filter((r) => !r.invoiceOnly).length,
        totalCustomers: new Set(paidRows.map((r) => r.customerName)).size,
        cashAmount,
        bankAmount,
        otherModeAmount,
      },
      collectionByPaymentMode,
      collectionTrend,
      top5CustomersByCollection,
    },
  });
}));

// Customer Ledger report — the Business Partner Ledger view for Customers
// (Reports > Sales > Customer Ledger). One row per AR-relevant transaction
// for a single customer, chronologically ordered with a running balance —
// the same idea as SAP Business One's Business Partner Ledger. Modelled on
// the Collection Register report above for the "resolve customer -> per-
// document-type where clause -> union into rows -> sort by date" shape.
//
// Five document types post to a customer's receivable balance and are
// unioned here: SalesInvoice (debit), SalesReturn (credit), SalesCreditMemo
// (credit), Collection (credit) and PaymentReceipt where partyType is
// 'Customer' (credit). Payment Voucher is deliberately excluded:
// PaymentVoucher.partyType is 'Vendor' | 'Account' only (see model
// PaymentVoucher) — there is no Customer option in this schema, so
// including it here would mean fabricating a join that doesn't exist. If a
// customer refund genuinely needs to post through Payment Voucher, that is
// a schema change (adding a Customer partyType option), not something this
// report can paper over.
//
// "Reconciled" per row:
//   - SalesInvoice / SalesCreditMemo: looked up against CustomerOutstanding
//     by invoiceNo (balanceAmount <= EPSILON). SalesCreditMemo only carries
//     a single optional invoiceNo pointing at the invoice it was raised
//     against — no CustomerOutstanding row is ever created FOR the credit
//     memo itself (syncCustomerOutstanding is only called from Sales
//     Invoice create/update), so this is genuinely the settlement status of
//     the referenced invoice, not the credit memo's own. Falls back to the
//     document's own status (Paid/Closed) when there is no
//     CustomerOutstanding match.
//   - Collection: reconciled once the receipt's own paymentAmount has been
//     fully applied (paymentAmount - totalAppliedAmount <= EPSILON) — both
//     header fields the app already maintains, so no need to re-sum child
//     rows.
//   - PaymentReceipt: reconciled once openBalance <= EPSILON (same
//     header-field shortcut; openBalance is maintained as totalAmountDue -
//     appliedAmount - roundOff, see the Payment Receipt create/update
//     handlers below).
//   - SalesReturn: this model has no invoiceApplications/applications
//     relation at all (see model SalesReturn) — there is no "open item"
//     concept for a return in this schema, so it never has anything left
//     outstanding to reconcile. Always reported as reconciled = true. This
//     is a documented schema gap, structurally the same kind of gap as the
//     Payment Voucher exclusion above, not a fabricated join — flagging it
//     here rather than inventing an applications table that doesn't exist.
//
// The running `balance` and `closingBalance` are computed once over every
// row in range regardless of the Reconciled/Unreconciled checkboxes, since
// they describe the account's actual state — only which rows are LISTED
// (and the Debit/Credit totals under them) narrow with the checkboxes.
// Both checkboxes checked, or both unchecked, shows every row — never an
// empty report by default.
router.get('/receivables/customer-ledger/report', auth(), asyncHandler(async (req, res) => {
  const { customer, fromDate, toDate, reconciled, unreconciled } = req.query;
  if (!customer) {
    return res.status(400).json({ success: false, message: 'customer is required' });
  }

  const from = fromDate ? new Date(fromDate) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : new Date();
  to.setHours(23, 59, 59, 999);

  const wantReconciled = reconciled === 'true' || reconciled === true;
  const wantUnreconciled = unreconciled === 'true' || unreconciled === true;
  const filterByReconciled = wantReconciled && !wantUnreconciled;
  const filterByUnreconciled = wantUnreconciled && !wantReconciled;

  const bp = await prisma.businessPartner.findFirst({ where: { partnerType: 'Customer', partnerName: customer } });

  // Cancelled/void documents never post to the receivable balance — same
  // convention as the Collection Register report's statusWhere above.
  const notCancelled = { notIn: ['Cancelled'] };

  async function loadInvoiceReconciledMap(invoiceNos) {
    if (!invoiceNos.length) return {};
    const outstandingRows = await prisma.customerOutstanding.findMany({ where: { invoiceNo: { in: invoiceNos } } });
    const map = {};
    outstandingRows.forEach((r) => {
      map[r.invoiceNo] = round2(num(r.balanceAmount)) <= EPSILON;
    });
    return map;
  }

  // --- Opening balance: the customer's master opening balance plus the net
  // effect of every AR transaction strictly before `from` — same "fixed
  // baseline + aggregates up to a cut-off date" idea as
  // computeCashBalanceAsOf above, scoped to this one customer and to AR
  // movements instead of cash.
  //
  // BP Opening Balance (Company Setup > BP Opening Balance) documents dated
  // before `from` count here too — that page posts a real Dr Accounts
  // Receivable / Cr Opening Balance Account entry per line (see the
  // BP_OPENING_BALANCE builder in utils/glPosting.js), so a customer's
  // documented starting balance belongs in the same "prior AR movements"
  // bucket as an invoice, not left stranded off this report the way it was
  // before this bpName match was added (only bp.openingBalance, the
  // separate Business Partner master field, was ever read here).
  const [
    priorInvoices, priorReturns, priorCreditMemos, priorCollections, priorReceipts, priorBpOpenings,
  ] = await Promise.all([
    prisma.salesInvoice.findMany({ where: withBranchScope({ customer, status: notCancelled, invoiceDate: { lt: from } }, req), select: { amount: true } }),
    prisma.salesReturn.findMany({ where: withBranchScope({ customer, status: notCancelled, documentDate: { lt: from } }, req), select: { amount: true } }),
    prisma.salesCreditMemo.findMany({ where: withBranchScope({ customer, status: notCancelled, documentDate: { lt: from } }, req), select: { amount: true } }),
    prisma.collection.findMany({ where: withBranchScope({ customerName: customer, receiptDate: { lt: from } }, req), select: { paymentAmount: true } }),
    prisma.paymentReceipt.findMany({ where: withBranchScope({ partyType: 'Customer', partyName: customer, postingDate: { lt: from } }, req), select: { totalAmountDue: true } }),
    prisma.businessPartnerOpeningBalance.findMany({ where: { bpType: 'Customer', bpName: customer, documentDate: { lt: from } }, select: { openingBalance: true } }),
  ]);
  // A BP Opening Balance amount is signed the same way an invoice's is (a
  // positive amount is the customer owing more), so it folds straight into
  // priorDebit — a negative one (a customer opened in credit) nets itself
  // out here exactly the way postJournalEntry's own debit()/credit() flip
  // already treats it, no separate "negative opening balance" branch needed.
  const priorDebit = priorInvoices.reduce((sum, r) => sum + num(r.amount), 0)
    + priorBpOpenings.reduce((sum, r) => sum + num(r.openingBalance), 0);
  const priorCredit = priorReturns.reduce((sum, r) => sum + num(r.amount), 0)
    + priorCreditMemos.reduce((sum, r) => sum + num(r.amount), 0)
    + priorCollections.reduce((sum, r) => sum + num(r.paymentAmount), 0)
    + priorReceipts.reduce((sum, r) => sum + num(r.totalAmountDue), 0);
  const openingBalance = round2(num(bp?.openingBalance) + priorDebit - priorCredit);

  // --- The rows themselves, one query per document type within the range.
  const [invoices, returns, creditMemos, collections, receipts, bpOpenings] = await Promise.all([
    prisma.salesInvoice.findMany({ where: withBranchScope({ customer, status: notCancelled, invoiceDate: { gte: from, lte: to } }, req) }),
    prisma.salesReturn.findMany({ where: withBranchScope({ customer, status: notCancelled, documentDate: { gte: from, lte: to } }, req) }),
    prisma.salesCreditMemo.findMany({ where: withBranchScope({ customer, status: notCancelled, documentDate: { gte: from, lte: to } }, req) }),
    prisma.collection.findMany({ where: withBranchScope({ customerName: customer, receiptDate: { gte: from, lte: to } }, req) }),
    prisma.paymentReceipt.findMany({ where: withBranchScope({ partyType: 'Customer', partyName: customer, postingDate: { gte: from, lte: to } }, req) }),
    prisma.businessPartnerOpeningBalance.findMany({ where: { bpType: 'Customer', bpName: customer, documentDate: { gte: from, lte: to } } }),
  ]);

  const invoiceNos = invoices.map((i) => i.invoiceNo).filter(Boolean);
  const creditMemoInvoiceNos = creditMemos.map((c) => c.invoiceNo).filter(Boolean);
  const reconciledMap = await loadInvoiceReconciledMap([...new Set([...invoiceNos, ...creditMemoInvoiceNos])]);

  const rows = [];
  invoices.forEach((inv) => {
    rows.push({
      date: inv.invoiceDate,
      docType: 'Sales Invoice',
      docNo: inv.invoiceNo,
      description: inv.remarks || 'Sales Invoice',
      debit: round2(num(inv.amount)),
      credit: 0,
      dueDate: inv.dueDate,
      status: inv.status,
      reconciled: inv.invoiceNo in reconciledMap ? reconciledMap[inv.invoiceNo] : inv.paymentStatus === 'Paid',
    });
  });
  returns.forEach((ret) => {
    rows.push({
      date: ret.documentDate,
      docType: 'Sales Return',
      docNo: ret.returnNo,
      description: ret.reason || ret.narration || 'Sales Return',
      debit: 0,
      credit: round2(num(ret.amount)),
      dueDate: ret.dueDate,
      status: ret.status,
      // No invoiceApplications/applications relation exists on SalesReturn
      // — see the doc comment above this route.
      reconciled: true,
    });
  });
  creditMemos.forEach((cm) => {
    rows.push({
      date: cm.documentDate,
      docType: 'Sales Credit Memo',
      docNo: cm.creditNo,
      description: cm.reason || cm.narration || 'Sales Credit Memo',
      debit: 0,
      credit: round2(num(cm.amount)),
      dueDate: cm.dueDate,
      status: cm.status,
      reconciled: cm.invoiceNo && cm.invoiceNo in reconciledMap ? reconciledMap[cm.invoiceNo] : cm.status === 'Closed',
    });
  });
  collections.forEach((c) => {
    rows.push({
      date: c.receiptDate,
      docType: 'Collection',
      docNo: c.collectionNo,
      description: c.notes || 'Collection',
      debit: 0,
      credit: round2(num(c.paymentAmount)),
      dueDate: null,
      status: c.status,
      reconciled: round2(num(c.paymentAmount) - num(c.totalAppliedAmount)) <= EPSILON,
    });
  });
  receipts.forEach((p) => {
    rows.push({
      date: p.postingDate,
      docType: 'Payment Receipt',
      docNo: p.paymentReceiptNo,
      description: p.remarks || 'Payment Receipt',
      debit: 0,
      credit: round2(num(p.totalAmountDue)),
      dueDate: p.dueDate,
      status: p.status,
      reconciled: round2(num(p.openBalance)) <= EPSILON,
    });
  });
  // BP Opening Balance rows dated inside the range — same signed-amount
  // convention as the priorBpOpenings fold-in above: a positive amount is a
  // debit (the customer starts out owing this much), a negative one a
  // credit. There is no open-item/applications concept for a starting
  // balance — it isn't something a later payment applies against by
  // reference the way an invoice is — so it's always reported settled, the
  // same documented gap as Sales Return's own reconciled: true above.
  bpOpenings.forEach((ob) => {
    const amount = round2(num(ob.openingBalance));
    rows.push({
      date: ob.documentDate,
      docType: 'Opening Balance',
      docNo: ob.documentNumber,
      description: ob.remarks || 'BP Opening Balance',
      debit: amount > 0 ? amount : 0,
      credit: amount < 0 ? Math.abs(amount) : 0,
      dueDate: null,
      status: ob.status,
      reconciled: true,
    });
  });

  rows.sort((a, b) => new Date(a.date) - new Date(b.date));

  // Running balance over the FULL set, before the checkbox filter narrows
  // what's displayed — see the doc comment above.
  let running = openingBalance;
  const withBalance = rows.map((r) => {
    running = round2(running + r.debit - r.credit);
    return { ...r, balance: running };
  });
  const closingBalance = withBalance.length ? withBalance[withBalance.length - 1].balance : openingBalance;

  let visibleRows = withBalance;
  if (filterByReconciled) visibleRows = visibleRows.filter((r) => r.reconciled);
  if (filterByUnreconciled) visibleRows = visibleRows.filter((r) => !r.reconciled);

  const totals = visibleRows.reduce((acc, r) => ({
    debit: round2(acc.debit + r.debit),
    credit: round2(acc.credit + r.credit),
  }), { debit: 0, credit: 0 });

  res.json({
    success: true,
    data: {
      rows: visibleRows,
      openingBalance,
      closingBalance,
      totals,
    },
  });
}));

// Customer Aging Report — SAP Business One's "Customer Receivables Aging"
// layout (Reports > Sales > Customer Aging Report). Unlike
// /receivables/outstanding/report above (one row per customer, four fixed
// buckets), this report groups rows by (Customer, Invoice Document Sales
// Employee) — the salesPerson value stamped on each individual SalesInvoice,
// not the Customer master's own assigned rep — and buckets against however
// many boundaries the caller submits, not a hardcoded four.

// Default matches the report design's own default interval (30/60/.../240).
const DEFAULT_AGING_BOUNDARIES = [30, 60, 90, 120, 150, 180, 210, 240];

// `raw` is a comma-separated string of ascending day boundaries (the 8
// editable Interval inputs on the filter bar, though there is nothing here
// that requires exactly 8 — however many are submitted is however many
// bucket columns come back). Falls back to the design's default whenever
// nothing usable is submitted.
function parseAgingBoundaries(raw) {
  if (!raw) return DEFAULT_AGING_BOUNDARIES;
  const nums = String(raw).split(',').map((s) => Number(s.trim())).filter((n) => Number.isFinite(n) && n > 0);
  const sorted = Array.from(new Set(nums)).sort((a, b) => a - b);
  return sorted.length ? sorted : DEFAULT_AGING_BOUNDARIES;
}

// Bucket 0 catches everything up to and including the first boundary
// (not-yet-due invoices included, same "0 - 30 combined" convention as
// /receivables/outstanding/report's own bucket.notDue + bucket.d1to30), each
// middle bucket is (previous boundary, this boundary], and the last bucket
// is everything past the final boundary — labelled and keyed purely from
// whatever boundaries were actually submitted, so the frontend renders
// exactly as many columns as configured.
function buildAgingBucketDefs(boundaries) {
  const defs = [];
  let prev = 0;
  boundaries.forEach((b, i) => {
    defs.push({ key: `b${i}`, label: `${prev + 1}-${b}` });
    prev = b;
  });
  defs.push({ key: `b${boundaries.length}`, label: `>${prev}` });
  return defs;
}

function agingBucketIndex(daysOverdue, boundaries) {
  for (let i = 0; i < boundaries.length; i += 1) {
    if (daysOverdue <= boundaries[i]) return i;
  }
  return boundaries.length;
}

// Pseudo sales-employee group for credit-side documents that cannot be
// traced back to the invoice they settle, and therefore cannot be
// attributed to a specific Invoice Document Sales Employee:
//   - SalesReturn has no invoiceNo/applications relation at all (see model
//     SalesReturn in schema.prisma) — there is nothing to resolve here,
//     structurally the same schema gap already flagged on the Customer
//     Ledger report.
//   - SalesCreditMemo, Collection and PaymentReceipt DO carry invoiceNo
//     links (a single field, or child application rows respectively), but
//     a credit memo with no invoiceNo, or the unapplied "on account"
//     portion of a Collection/PaymentReceipt, has nothing to resolve
//     either.
// Rather than dropping these amounts from the report (which would make the
// per-group totals not add up to the customer's real Opening/Debit/Credit/
// Closing figures), they are attributed to this pseudo-group per customer,
// clearly labelled so it's obvious in the UI that these rows are the
// "couldn't be traced to a salesperson" bucket, not a real employee.
const AGING_UNASSIGNED_GROUP = '— (Unassigned)';

router.get('/receivables/customer-aging/report', auth(), asyncHandler(async (req, res) => {
  const {
    customers, branch, salesEmployee, agingDate, dateType, fromDate, toDate, boundaries: boundariesRaw,
  } = req.query;

  const boundaries = parseAgingBoundaries(boundariesRaw);
  const bucketDefs = buildAgingBucketDefs(boundaries);

  const aging = agingDate ? new Date(agingDate) : new Date();
  aging.setHours(0, 0, 0, 0);
  // "Document Date" = invoice date, same relabeling of agingBasedOn as the
  // outstanding report's own AGING_BASIS_OPTIONS.
  const basisField = dateType === 'Due Date' ? 'dueDate' : 'invoiceDate';

  const from = fromDate ? new Date(fromDate) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : new Date();
  to.setHours(23, 59, 59, 999);

  // `customers` is the multi-select Business Partner filter, sent as a
  // single comma-joined string (see customerAgingReportApi.js) rather than
  // a repeated query key — parsed the same way `boundaries` is below.
  // Still tolerates an actual array, in case a future caller sends
  // `customers[]=A&customers[]=B` instead. Empty/absent means "all
  // customers."
  const customerNames = Array.isArray(customers)
    ? customers.filter(Boolean)
    : (customers ? String(customers).split(',').map((s) => s.trim()).filter(Boolean) : []);

  const customerWhere = { partnerType: 'Customer' };
  if (customerNames.length) customerWhere.partnerName = { in: customerNames };
  else customerWhere.status = 'Active';
  const bpRows = await prisma.businessPartner.findMany({ where: customerWhere });
  const bucketDefsEmpty = bucketDefs; // stable reference for the early-return payload below
  if (!bpRows.length) {
    return res.json({
      success: true,
      data: { rows: [], totals: { openingBalance: 0, debit: 0, collected: 0, creditAllDocs: 0, closingBalance: 0, buckets: new Array(bucketDefsEmpty.length).fill(0) }, bucketDefs, boundaries, agingDate: aging },
    });
  }
  const names = bpRows.map((c) => c.partnerName);
  const bpByName = Object.fromEntries(bpRows.map((c) => [c.partnerName, c]));

  // Cancelled/void documents never post to the receivable balance — same
  // convention as the Collection Register and Customer Ledger reports above.
  const notCancelled = { notIn: ['Cancelled'] };
  const branchFilter = branch ? { branch } : {};

  // SQL Server caps a single query at 2100 bound parameters. `names` is
  // every ACTIVE customer in the company whenever the Business Partner
  // filter is left empty ("all customers") — easily hundreds of rows — and
  // an `IN (...)` list that long, combined with the `status: notIn`
  // negation filter (which Prisma cannot auto-split across queries once a
  // negation is involved — see Prisma error P2029), blew straight through
  // that cap. Filtering these five bulk queries down to "in names" at the
  // database was never actually necessary: every row is matched into a
  // group by customer name in JS immediately below anyway, so an
  // out-of-scope customer's rows are simply never turned into a group.
  // Only push the filter down to the database when the caller explicitly
  // narrowed to a bounded, UI-picked list of customers (customerNames) —
  // small enough by construction that this can't recur.
  const nameSet = new Set(names);
  const explicitCustomerFilter = customerNames.length ? { in: customerNames } : undefined;

  const [allInvoices, allReturns, allCreditMemos, allCollections, allReceipts, allOutstanding] = await Promise.all([
    prisma.salesInvoice.findMany({ where: withBranchScope({ ...(explicitCustomerFilter ? { customer: explicitCustomerFilter } : {}), status: notCancelled, ...branchFilter }, req) }),
    prisma.salesReturn.findMany({ where: withBranchScope({ ...(explicitCustomerFilter ? { customer: explicitCustomerFilter } : {}), status: notCancelled, ...branchFilter }, req) }),
    prisma.salesCreditMemo.findMany({ where: withBranchScope({ ...(explicitCustomerFilter ? { customer: explicitCustomerFilter } : {}), status: notCancelled, ...branchFilter }, req) }),
    prisma.collection.findMany({ where: withBranchScope({ ...(explicitCustomerFilter ? { customerName: explicitCustomerFilter } : {}), ...branchFilter }, req), include: { invoiceApplications: true } }),
    prisma.paymentReceipt.findMany({ where: withBranchScope({ partyType: 'Customer', ...(explicitCustomerFilter ? { partyName: explicitCustomerFilter } : {}), ...branchFilter }, req), include: { applications: true } }),
    prisma.customerOutstanding.findMany({ where: explicitCustomerFilter ? { customerName: explicitCustomerFilter } : {} }),
  ]);

  // invoiceNo -> the group (salesPerson) and branch it belongs to, so every
  // credit-side document that links back to a specific invoice (Credit
  // Memo's invoiceNo, Collection/Payment Receipt's application rows,
  // CustomerOutstanding's own invoiceNo) resolves to the same group as the
  // invoice itself, rather than by guessing from its own (nonexistent)
  // salesPerson field.
  const invoiceGroupOf = {};
  allInvoices.forEach((inv) => {
    if (!inv.invoiceNo) return;
    invoiceGroupOf[inv.invoiceNo] = { salesPerson: inv.salesPerson || AGING_UNASSIGNED_GROUP, branch: inv.branch };
  });

  const groups = {};
  function ensureGroup(customerName, salesPerson, branchName) {
    const key = `${customerName}::${salesPerson}`;
    if (!groups[key]) {
      groups[key] = {
        customer: customerName,
        salesPerson,
        branch: branchName || null,
        openingDebit: 0,
        openingCredit: 0,
        debit: 0,
        collected: 0,
        creditAllDocs: 0,
        buckets: new Array(bucketDefs.length).fill(0),
      };
    } else if (branchName && !groups[key].branch) {
      groups[key].branch = branchName;
    }
    return groups[key];
  }

  // --- Debit side: every invoice seeds/grows its own (customer, salesPerson)
  // group, split into pre-period (Opening) and in-period (Debit) by
  // invoiceDate — groups exist for every invoice ever raised, not just ones
  // in range, so a group's Opening Balance and aging buckets are correct
  // even in a period with no new invoices for it.
  allInvoices.forEach((inv) => {
    if (!inv.customer || !nameSet.has(inv.customer)) return;
    const g = ensureGroup(inv.customer, inv.salesPerson || AGING_UNASSIGNED_GROUP, inv.branch);
    const amt = round2(num(inv.amount));
    const d = inv.invoiceDate ? new Date(inv.invoiceDate) : null;
    if (d && d < from) g.openingDebit = round2(g.openingDebit + amt);
    else if (d && d >= from && d <= to) g.debit = round2(g.debit + amt);
  });

  // --- Credit side: Sales Return has no invoiceNo at all (see model
  // SalesReturn) — always the Unassigned pseudo-group for this customer.
  allReturns.forEach((ret) => {
    if (!ret.customer || !nameSet.has(ret.customer)) return;
    const g = ensureGroup(ret.customer, AGING_UNASSIGNED_GROUP, ret.branch);
    const amt = round2(num(ret.amount));
    const d = ret.documentDate ? new Date(ret.documentDate) : null;
    if (d && d < from) g.openingCredit = round2(g.openingCredit + amt);
    else if (d && d >= from && d <= to) g.creditAllDocs = round2(g.creditAllDocs + amt);
  });

  // --- Sales Credit Memo resolves through its own (single, optional)
  // invoiceNo when it has one.
  allCreditMemos.forEach((cm) => {
    if (!cm.customer || !nameSet.has(cm.customer)) return;
    const resolved = cm.invoiceNo ? invoiceGroupOf[cm.invoiceNo] : null;
    const g = ensureGroup(cm.customer, resolved ? resolved.salesPerson : AGING_UNASSIGNED_GROUP, resolved ? resolved.branch : cm.branch);
    const amt = round2(num(cm.amount));
    const d = cm.documentDate ? new Date(cm.documentDate) : null;
    if (d && d < from) g.openingCredit = round2(g.openingCredit + amt);
    else if (d && d >= from && d <= to) g.creditAllDocs = round2(g.creditAllDocs + amt);
  });

  // --- Collection: split across every invoice it actually applied against;
  // whatever wasn't applied to any invoice (a receipt kept "on account")
  // goes to the Unassigned pseudo-group so it's still counted somewhere.
  // Collected Amount and Credit Amount (All Docs) both grow together here —
  // Collected Amount is always a subset of Credit Amount (All Docs), per
  // the report spec.
  allCollections.forEach((col) => {
    if (!col.customerName || !nameSet.has(col.customerName)) return;
    const apps = col.invoiceApplications || [];
    let appliedSum = 0;
    const d = col.receiptDate ? new Date(col.receiptDate) : null;
    apps.forEach((app) => {
      const amt = round2(num(app.amountApplied));
      appliedSum = round2(appliedSum + amt);
      const resolved = app.invoiceNo ? invoiceGroupOf[app.invoiceNo] : null;
      const g = ensureGroup(col.customerName, resolved ? resolved.salesPerson : AGING_UNASSIGNED_GROUP, resolved ? resolved.branch : col.branch);
      if (d && d < from) g.openingCredit = round2(g.openingCredit + amt);
      else if (d && d >= from && d <= to) {
        g.collected = round2(g.collected + amt);
        g.creditAllDocs = round2(g.creditAllDocs + amt);
      }
    });
    const leftover = round2(num(col.paymentAmount) - appliedSum);
    if (leftover > EPSILON) {
      const g = ensureGroup(col.customerName, AGING_UNASSIGNED_GROUP, col.branch);
      if (d && d < from) g.openingCredit = round2(g.openingCredit + leftover);
      else if (d && d >= from && d <= to) {
        g.collected = round2(g.collected + leftover);
        g.creditAllDocs = round2(g.creditAllDocs + leftover);
      }
    }
  });

  // --- Payment Receipt (Customer party only) — same split/leftover idea as
  // Collection above, keyed off its own applications and totalAmountDue
  // (the actual receipt amount — see the Customer Ledger report's comment
  // on why totalAmountDue, not appliedAmount, is the money received).
  allReceipts.forEach((pr) => {
    if (!pr.partyName || !nameSet.has(pr.partyName)) return;
    const apps = pr.applications || [];
    let appliedSum = 0;
    const d = pr.postingDate ? new Date(pr.postingDate) : null;
    apps.forEach((app) => {
      const amt = round2(num(app.amountApplied));
      appliedSum = round2(appliedSum + amt);
      const resolved = app.invoiceNo ? invoiceGroupOf[app.invoiceNo] : null;
      const g = ensureGroup(pr.partyName, resolved ? resolved.salesPerson : AGING_UNASSIGNED_GROUP, resolved ? resolved.branch : pr.branch);
      if (d && d < from) g.openingCredit = round2(g.openingCredit + amt);
      else if (d && d >= from && d <= to) {
        g.collected = round2(g.collected + amt);
        g.creditAllDocs = round2(g.creditAllDocs + amt);
      }
    });
    const leftover = round2(num(pr.totalAmountDue) - appliedSum);
    if (leftover > EPSILON) {
      const g = ensureGroup(pr.partyName, AGING_UNASSIGNED_GROUP, pr.branch);
      if (d && d < from) g.openingCredit = round2(g.openingCredit + leftover);
      else if (d && d >= from && d <= to) {
        g.collected = round2(g.collected + leftover);
        g.creditAllDocs = round2(g.creditAllDocs + leftover);
      }
    }
  });

  // --- Aging buckets: every still-open CustomerOutstanding row, bucketed by
  // days overdue from Aging Date (using the Date Type basis), attributed to
  // whichever group its own invoice belongs to.
  allOutstanding.forEach((row) => {
    if (!row.customerName || !nameSet.has(row.customerName)) return;
    const balance = row.balanceAmount != null ? num(row.balanceAmount) : num(row.invoiceAmount) - num(row.paidAmount);
    if (row.status === 'Paid' || balance <= EPSILON) return;
    const resolved = row.invoiceNo ? invoiceGroupOf[row.invoiceNo] : null;
    const g = ensureGroup(row.customerName, resolved ? resolved.salesPerson : AGING_UNASSIGNED_GROUP, resolved ? resolved.branch : null);
    const basisDate = row[basisField];
    let daysOverdue = 0;
    if (basisDate) {
      const d = new Date(basisDate);
      d.setHours(0, 0, 0, 0);
      daysOverdue = Math.round((aging - d) / (1000 * 60 * 60 * 24));
    }
    const idx = agingBucketIndex(daysOverdue, boundaries);
    g.buckets[idx] = round2(g.buckets[idx] + balance);
  });

  let rows = Object.values(groups).map((g) => {
    const bp = bpByName[g.customer] || {};
    const openingBalance = round2(g.openingDebit - g.openingCredit);
    const closingBalance = round2(openingBalance + g.debit - g.creditAllDocs);
    return {
      customerCode: bp.partnerCode || '—',
      customerName: g.customer,
      // The Customer master's own assigned rep — distinct from
      // invoiceSalesPerson, the grouping key below.
      salesExecutiveName: bp.salesPerson || '—',
      invoiceSalesPerson: g.salesPerson,
      branch: g.branch || '—',
      openingBalance,
      debit: g.debit,
      collected: g.collected,
      creditAllDocs: g.creditAllDocs,
      closingBalance,
      buckets: g.buckets,
    };
  });

  if (salesEmployee) rows = rows.filter((r) => r.invoiceSalesPerson === salesEmployee);

  rows.sort((a, b) => a.customerCode.localeCompare(b.customerCode) || a.invoiceSalesPerson.localeCompare(b.invoiceSalesPerson));

  const totals = rows.reduce((acc, r) => {
    acc.openingBalance = round2(acc.openingBalance + r.openingBalance);
    acc.debit = round2(acc.debit + r.debit);
    acc.collected = round2(acc.collected + r.collected);
    acc.creditAllDocs = round2(acc.creditAllDocs + r.creditAllDocs);
    acc.closingBalance = round2(acc.closingBalance + r.closingBalance);
    r.buckets.forEach((v, i) => { acc.buckets[i] = round2((acc.buckets[i] || 0) + v); });
    return acc;
  }, { openingBalance: 0, debit: 0, collected: 0, creditAllDocs: 0, closingBalance: 0, buckets: new Array(bucketDefs.length).fill(0) });

  res.json({
    success: true,
    data: {
      rows,
      totals,
      bucketDefs,
      boundaries,
      agingDate: aging,
      dateType: dateType || 'Document Date',
    },
  });
}));

// Payables
// Bespoke aging-report endpoint for the Supplier Outstanding page — mounted
// BEFORE the crudRouter below so `/report` doesn't get swallowed by that
// router's `/:id` route. Unlike /receivables/outstanding/report (which ages
// backward from "days since due"), this report is forward-looking — it
// buckets each open invoice by how soon it falls due (Overdue / Due Within
// 30 Days / Due 31-60 Days / Due Above 60 Days), matching the design's
// payables-focused framing ("what do we owe, and when"). "supplierGroup"
// filters against Supplier.supplierType (the only classification field on
// Supplier, whose sample values — Raw Materials/Electricals/Packaging/
// etc — match the report design's "Supplier Group" exactly). "Branch" and
// "Currency" are no-ops for the same reason as the other reports.
// "Show Paid Invoices" is a genuinely new toggle versus the old version of
// this report: default (No) excludes fully-paid SupplierOutstanding rows
// entirely from both the invoice count and Total Outstanding sum, giving a
// real live "what's currently owed" picture; "Yes" brings historical paid
// invoices back in (their own past invoiceAmount, contributing 0 to every
// ageing bucket), for a full historical register view.
function computeSupplierOutstandingSnapshot(outstandingRows, asOn, basisField, showPaidInvoices) {
  const bySupplier = {};
  outstandingRows.forEach((row) => {
    const balance = row.balanceAmount != null
      ? Number(row.balanceAmount)
      : Number(row.invoiceAmount || 0) - Number(row.paidAmount || 0);
    const isPaid = row.status === 'Paid' || balance <= 0;
    if (isPaid && showPaidInvoices !== 'Yes') return;

    const name = row.supplierName || 'Unknown';
    if (!bySupplier[name]) {
      bySupplier[name] = {
        totalInvoices: 0, totalOutstanding: 0,
        overdue: 0, dueWithin30: 0, due31to60: 0, dueAbove60: 0,
        // Backward "days since due" aging (same bucketing the Receivables >
        // Customer Outstanding report uses), tracked alongside the
        // forward-looking dueWithin30/due31to60/dueAbove60/overdue buckets
        // above (which the Reports > Supplier Outstanding page's chart and
        // table still read as-is). Only used by the Payables > Supplier
        // Outstanding page.
        agedNotDue: 0, agedD1to30: 0, agedD31to60: 0, agedD61to90: 0, agedAbove90: 0,
      };
    }
    const bucket = bySupplier[name];
    bucket.totalInvoices += 1;
    if (isPaid) {
      // Only reached when showPaidInvoices === 'Yes' — contributes this
      // invoice's original amount to the historical Total Outstanding
      // figure (per the "full historical register view" behavior above),
      // but nothing to any ageing bucket, since it's already settled.
      bucket.totalOutstanding += Number(row.invoiceAmount || 0);
      return;
    }
    // Total Outstanding is the money actually still owed — the remaining
    // balance — not the invoice's original amount. Using invoiceAmount here
    // (the previous behavior) meant a Partial invoice's already-paid
    // portion still counted toward Total Outstanding, so it came out
    // bigger than what any of the ageing columns added up to.
    bucket.totalOutstanding += balance;

    const basisDate = row[basisField];
    let daysPast = 0;
    if (basisDate) {
      const d = new Date(basisDate);
      d.setHours(0, 0, 0, 0);
      daysPast = Math.round((asOn - d) / (1000 * 60 * 60 * 24));
    }

    if (daysPast > 0) bucket.overdue += balance;
    else if (-daysPast <= 30) bucket.dueWithin30 += balance;
    else if (-daysPast <= 60) bucket.due31to60 += balance;
    else bucket.dueAbove60 += balance;

    if (daysPast <= 0) bucket.agedNotDue += balance;
    else if (daysPast <= 30) bucket.agedD1to30 += balance;
    else if (daysPast <= 60) bucket.agedD31to60 += balance;
    else if (daysPast <= 90) bucket.agedD61to90 += balance;
    else bucket.agedAbove90 += balance;
  });
  return bySupplier;
}

router.get('/payables/outstanding/report', auth(), asyncHandler(async (req, res) => {
  const {
    branch, supplierGroup, supplier, currency, include, showPaidInvoices, asOnDate, agingBasedOn,
  } = req.query;
  const basisField = agingBasedOn === 'Invoice Date' ? 'invoiceDate' : 'dueDate';
  const asOn = asOnDate ? new Date(asOnDate) : new Date();
  asOn.setHours(0, 0, 0, 0);

  const supplierWhere = { status: 'Active', partnerType: 'Vendor' };
  // supplierGroup ("Supplier Group") is a no-op — that classification lived
  // on the retired Supplier Master's supplierType field, which Business
  // Partner has no equivalent of.
  if (supplier) supplierWhere.partnerName = supplier;

  const suppliers = await prisma.businessPartner.findMany({ where: supplierWhere });
  const names = suppliers.map((s) => s.partnerName);
  const codeGroupByName = Object.fromEntries(suppliers.map((s) => [s.partnerName, { code: s.partnerCode, group: 'Uncategorized' }]));

  const outstandingRows = names.length
    ? await prisma.supplierOutstanding.findMany({ where: { supplierName: { in: names } } })
    : [];

  const bySupplier = computeSupplierOutstandingSnapshot(outstandingRows, asOn, basisField, showPaidInvoices);

  const allRows = suppliers.map((s) => {
    const agg = bySupplier[s.partnerName] || {
      totalInvoices: 0, totalOutstanding: 0, overdue: 0, dueWithin30: 0, due31to60: 0, dueAbove60: 0,
      agedNotDue: 0, agedD1to30: 0, agedD31to60: 0, agedD61to90: 0, agedAbove90: 0,
    };
    return {
      supplierCode: s.partnerCode,
      supplierName: s.partnerName,
      // Business Partner has no equivalent of the retired Supplier Master's
      // supplierType ("Supplier Group") — always 'Uncategorized' now.
      supplierGroup: 'Uncategorized',
      totalInvoices: agg.totalInvoices,
      totalOutstanding: agg.totalOutstanding,
      overdue: agg.overdue,
      dueWithin30: agg.dueWithin30,
      due31to60: agg.due31to60,
      dueAbove60: agg.dueAbove60,
      // Backward-aged buckets + row-level overdue total for the Payables >
      // Supplier Outstanding page.
      notDue: agg.agedNotDue,
      d1to30: agg.agedD1to30,
      d31to60: agg.agedD31to60,
      d61to90: agg.agedD61to90,
      above90: agg.agedAbove90,
      overdueAmount: agg.agedD1to30 + agg.agedD31to60 + agg.agedD61to90 + agg.agedAbove90,
    };
  }).sort((a, b) => a.supplierCode.localeCompare(b.supplierCode));

  // "Include": 'Overdue Invoices Only' narrows to suppliers currently past
  // due (same "default is everyone, narrower option filters down" pattern
  // used elsewhere, e.g. Reorder Level's "Reorder Status"). 'Suppliers with
  // Outstanding Only' is broader than that — any real balance owed, whether
  // or not it's due yet — which is what actually matches "this supplier has
  // an open invoice" (unlike 'Overdue', which would hide a supplier whose
  // only unpaid invoice isn't due yet).
  const rows = include === 'Overdue Invoices Only'
    ? allRows.filter((r) => r.overdue > 0)
    : include === 'Suppliers with Outstanding Only'
      ? allRows.filter((r) => r.totalOutstanding > 0)
      : allRows;

  const totals = rows.reduce((acc, r) => {
    acc.totalInvoices += r.totalInvoices;
    acc.totalOutstanding += r.totalOutstanding;
    acc.overdue += r.overdue;
    acc.dueWithin30 += r.dueWithin30;
    acc.due31to60 += r.due31to60;
    acc.dueAbove60 += r.dueAbove60;
    acc.notDue += r.notDue;
    acc.d1to30 += r.d1to30;
    acc.d31to60 += r.d31to60;
    acc.d61to90 += r.d61to90;
    acc.above90 += r.above90;
    acc.overdueAmount += r.overdueAmount;
    return acc;
  }, {
    totalInvoices: 0, totalOutstanding: 0, overdue: 0, dueWithin30: 0, due31to60: 0, dueAbove60: 0,
    notDue: 0, d1to30: 0, d31to60: 0, d61to90: 0, above90: 0, overdueAmount: 0,
  });

  // "Due Today" — same convention as the Receivables report: always keyed
  // off dueDate specifically, regardless of the Aging Based On filter.
  let dueToday = 0;
  outstandingRows.forEach((row) => {
    const balance = row.balanceAmount != null
      ? Number(row.balanceAmount)
      : Number(row.invoiceAmount || 0) - Number(row.paidAmount || 0);
    if (row.status === 'Paid' || balance <= 0 || !row.dueDate) return;
    const d = new Date(row.dueDate);
    d.setHours(0, 0, 0, 0);
    if (d.getTime() === asOn.getTime()) dueToday += balance;
  });

  const ageingTotal = totals.totalOutstanding || 1;
  const outstandingByAgeing = [
    { name: 'Overdue', value: Math.round(totals.overdue), percent: Math.round((totals.overdue / ageingTotal) * 1000) / 10 },
    { name: 'Due Within 30 Days', value: Math.round(totals.dueWithin30), percent: Math.round((totals.dueWithin30 / ageingTotal) * 1000) / 10 },
    { name: 'Due 31-60 Days', value: Math.round(totals.due31to60), percent: Math.round((totals.due31to60 / ageingTotal) * 1000) / 10 },
    { name: 'Due Above 60 Days', value: Math.round(totals.dueAbove60), percent: Math.round((totals.dueAbove60 / ageingTotal) * 1000) / 10 },
  ];

  // Top 5 Suppliers by Outstanding.
  const top5SuppliersByOutstanding = [...rows].sort((a, b) => b.totalOutstanding - a.totalOutstanding).slice(0, 5)
    .map((r) => ({ name: r.supplierName, value: Math.round(r.totalOutstanding) }));

  // Outstanding Trend (Last 6 Months) — a snapshot of what Total
  // Outstanding would have been if this same report were run as of the end
  // of each of the last 6 months (same filters, same showPaidInvoices
  // toggle), not a month-over-month collections delta.
  const outstandingTrend = [];
  for (let i = 5; i >= 0; i -= 1) {
    const monthEnd = new Date(asOn.getFullYear(), asOn.getMonth() - i + 1, 0);
    monthEnd.setHours(23, 59, 59, 999);
    const snapshotDate = i === 0 ? asOn : monthEnd;
    const snapshot = computeSupplierOutstandingSnapshot(outstandingRows, snapshotDate, basisField, showPaidInvoices);
    const monthTotal = Object.values(snapshot).reduce((sum, s) => sum + s.totalOutstanding, 0);
    outstandingTrend.push({ name: snapshotDate.toLocaleDateString('en-US', { month: 'short', year: 'numeric' }), value: Math.round(monthTotal) });
  }

  res.json({
    success: true,
    data: {
      asOnDate: asOn,
      agingBasedOn: agingBasedOn || 'Due Date',
      stats: {
        totalSuppliers: rows.length,
        totalOutstandingAmount: totals.totalOutstanding,
        overdue: totals.overdue,
        dueWithin30: totals.dueWithin30,
        due31to60: totals.due31to60,
        dueAbove60: totals.dueAbove60,
        overdueAmount: totals.overdueAmount,
        dueToday,
      },
      rows,
      totals,
      outstandingByAgeing,
      top5SuppliersByOutstanding,
      outstandingTrend,
    },
  });
}));

router.use('/payables/outstanding', crudRouter(prisma.supplierOutstanding, { searchFields: ['supplierName', 'invoiceNo'] }));

// Payment Entry -- a master/detail resource (SupplierPayment has many
// PaymentInvoiceApplication rows), same bespoke-route pattern as the
// Collection Entry routes above (mirrors crudRouter's URL/method/response
// shape so the frontend keeps using the generic supplierPaymentApi from
// createCrudApi). Replaces the old flat crudRouter(prisma.supplierPayment,
// ...) mount now that the model has a nested line-items collection.
const supplierPaymentInclude = { invoiceApplications: { orderBy: { id: 'asc' } } };

function toPaymentApplicationData(app) {
  return {
    invoiceNo: app.invoiceNo || null,
    invoiceDate: app.invoiceDate || null,
    dueDate: app.dueDate || null,
    totalAmount: app.totalAmount != null ? Number(app.totalAmount) : 0,
    outstandingAtTimeOfApplication: app.outstandingAtTimeOfApplication != null ? Number(app.outstandingAtTimeOfApplication) : 0,
    amountApplied: app.amountApplied != null ? Number(app.amountApplied) : 0,
  };
}



router.get('/payables/payments', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { paymentNo: { contains: q } },
        { supplierName: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.supplierPayment.findMany({ where: withBranchScope(where, req), include: supplierPaymentInclude, orderBy: { id: 'desc' } });
  res.json({ success: true, data: rows });
}));

router.get('/payables/payments/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.supplierPayment.findUnique({ where: { id: Number(req.params.id) }, include: supplierPaymentInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  res.json({ success: true, data: row });
}));

router.post('/payables/payments', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue paymentNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { invoiceApplications = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const appData = invoiceApplications.map(toPaymentApplicationData);
  const totalAppliedAmount = appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0);
  const row = await prisma.$transaction(async (tx) => {
    // paymentNo now comes from the configured PV (Payment Voucher)
    // numbering series rather than free text — see resolveDocumentNumber
    // above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('PV', header.paymentNo, tx, seriesId || null);
    const created = await tx.supplierPayment.create({
      data: { ...header, paymentNo: documentNumber, totalAppliedAmount, invoiceApplications: { create: appData } },
      include: supplierPaymentInclude,
    });
    if (syncManual) await syncManual();
    if (created.status === 'Posted') {
      // Same pre-flight as the receipts side — see customerLedger above.
      await supplierLedger.assertApplicationsValid(tx, appData, {
        paymentAmount: created.paymentAmount,
        partyName: created.supplierName,
      });
      await applyToSupplierOutstanding(tx, appData);
      for (const app of appData) {
        if (app.invoiceNo) await syncPurchaseInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
    await syncBankReconciliationTxn(tx, {
      bankAccount: created.payFromAccount, voucherType: 'Payment', voucherNo: created.paymentNo,
      txnDate: created.paymentDate, type: 'Debit', amount: created.paymentAmount,
      description: `Payment to ${created.supplierName || 'supplier'}`, remarks: created.notes,
      isActive: created.status === 'Posted',
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/payables/payments/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { invoiceApplications = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader);
  const appData = invoiceApplications.map(toPaymentApplicationData);
  const totalAppliedAmount = appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0);
  // Replace the applied-invoice set wholesale on every save -- simpler and
  // safer than diffing which rows were added/removed/edited client-side.
  const row = await prisma.$transaction(async (tx) => {
    // If this payment was already Posted before this save, its previous
    // invoiceApplications were already subtracted from SupplierOutstanding —
    // reverse that first so re-saving (with the same or edited amounts)
    // doesn't double-decrement the invoice balance.
    const existing = await tx.supplierPayment.findUnique({ where: { id }, include: supplierPaymentInclude });
    if (existing?.status === 'Posted') {
      await reverseSupplierOutstanding(tx, existing.invoiceApplications);
    }
    await tx.paymentInvoiceApplication.deleteMany({ where: { paymentId: id } });
    const updated = await tx.supplierPayment.update({
      where: { id },
      data: { ...header, totalAppliedAmount, invoiceApplications: { create: appData } },
      include: supplierPaymentInclude,
    });
    if (updated.status === 'Posted') {
      // Same pre-flight as the receipts side — see customerLedger above.
      await supplierLedger.assertApplicationsValid(tx, appData, {
        paymentAmount: updated.paymentAmount,
        partyName: updated.supplierName,
      });
      await applyToSupplierOutstanding(tx, appData);
    }
    // Sync every invoice touched by either the old or the new application
    // set — an invoice dropped from this payment needs its paymentStatus
    // pulled back down just as much as one newly added to it needs pushing up.
    const touchedInvoiceNos = new Set([
      ...(existing?.invoiceApplications || []).map((a) => a.invoiceNo).filter(Boolean),
      ...appData.map((a) => a.invoiceNo).filter(Boolean),
    ]);
    for (const invoiceNo of touchedInvoiceNos) {
      await syncPurchaseInvoicePaymentStatus(tx, invoiceNo);
    }
    await syncBankReconciliationTxn(tx, {
      bankAccount: updated.payFromAccount, voucherType: 'Payment', voucherNo: updated.paymentNo,
      txnDate: updated.paymentDate, type: 'Debit', amount: updated.paymentAmount,
      description: `Payment to ${updated.supplierName || 'supplier'}`, remarks: updated.notes,
      isActive: updated.status === 'Posted',
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/payables/payments/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // PaymentInvoiceApplication.payment has onDelete: Cascade, so
  // applications go with it. If this payment was Posted, its effect on
  // SupplierOutstanding needs reversing first, or the deleted payment's
  // amount stays "applied" forever with no record of why the balance is low.
  await prisma.$transaction(async (tx) => {
    const existing = await tx.supplierPayment.findUnique({ where: { id: Number(req.params.id) }, include: supplierPaymentInclude });
    if (existing?.status === 'Posted') {
      await reverseSupplierOutstanding(tx, existing.invoiceApplications);
    }
    if (existing) {
      await syncBankReconciliationTxn(tx, {
        bankAccount: existing.payFromAccount, voucherNo: existing.paymentNo, isActive: false,
      });
    }
    await tx.supplierPayment.delete({ where: { id: Number(req.params.id) } });
    if (existing?.status === 'Posted') {
      for (const app of existing.invoiceApplications) {
        if (app.invoiceNo) await syncPurchaseInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Payment Register report — bespoke aggregation endpoint for the
// Reports > Payable > Payment Register page.
//
// RECONCILES WITH THE DASHBOARD'S "Total Payables" CARD (routes/dashboard.js)
// and with the Purchase Invoice Register, using the same rules:
//   * partyType=Vendor (default): every Posted Supplier Payment AND every
//     Posted Payment Voucher ("Outgoing Payment") against a Vendor with
//     Payment on Account unchecked — the exact two document types the
//     dashboard sums. Payment Amount / Net Paid is what was actually APPLIED
//     to active (non-Draft/Cancelled) purchase invoices, capped per invoice
//     at the invoice's own amount. With the default filters,
//     stats.totalPayments === dashboard totalPayables.
//   * Invoice Amount is the Purchase Invoice's own `amount` — the "Net
//     Amount" the Purchase Invoice Register shows — counted ONCE per invoice
//     (on the earliest payment row that settles it), so a part-paid-twice
//     invoice never inflates the column total: Σ Invoice Amount = Σ Net
//     Amount of the invoices the listed payments settle.
//   * Every payment document is LISTED whatever its status (Posted / Draft /
//     Cancelled) and whether or not it settled an invoice, so nothing is hidden;
//     only `counted` rows (Posted, settling an active invoice) feed the totals
//     and stat cards, which keeps them equal to the dashboard.
//   * partyType=Account: Payment Vouchers against a Chart-of-Accounts
//     Account (no invoices are involved — Invoice Amount is 0). The party
//     filter then works on Account Code (`account`).
// Filters: fromDate/toDate (no bound when empty), branch, supplier (name) or
// account (code), paymentMode, paymentMethod (derived from the mode:
// Cash -> Cash, Cheque/Bank Transfer -> Bank, UPI/NEFT/RTGS -> Online),
// referenceType (derived from the mode: Cheque -> Cheque No., Bank Transfer/
// NEFT/RTGS -> UTR, UPI -> UPI Ref.), include (Posted Only is the default —
// a Draft has not paid anybody), currency, showCancelledPayments (Yes adds
// Cancelled documents), showUnreconciledPayments (Yes keeps only payments
// whose Bank Reconciliation line is still Unreconciled).
// "Discount" has no backing column anywhere, so it is always 0 and "Net
// Paid" equals Payment Amount.
router.get('/payables/payment-register/report', auth(), asyncHandler(async (req, res) => {
  const {
    fromDate, toDate, supplier, account, paymentMode, paymentMethod, referenceType,
    include, branch, currency, showCancelledPayments, showUnreconciledPayments,
  } = req.query;
  const partyType = req.query.partyType === 'Account' ? 'Account' : 'Vendor';

  const from = fromDate ? new Date(fromDate) : null;
  if (from) from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : null;
  if (to) to.setHours(23, 59, 59, 999);

  // Every payment document is listed regardless of status (Posted, Draft,
  // Cancelled, ...) unless the caller narrows it with `include`. Only Posted
  // documents that settle active purchase invoices count toward the totals
  // (see `counted` below) — that is the dashboard's basis.
  let statusFilter;
  if (include === 'Posted Only') statusFilter = { in: ['Posted'] };
  else if (include === 'Draft Only') statusFilter = { in: ['Draft'] };
  else if (showCancelledPayments === 'No') statusFilter = { not: 'Cancelled' };

  const normCurrency = (c) => String(c || 'INR').replace(/^N?'|'$/g, '').trim().toUpperCase() || 'INR';
  const METHOD_OF_MODE = { Cash: 'Cash', Cheque: 'Bank', 'Bank Transfer': 'Bank', UPI: 'Online', NEFT: 'Online', RTGS: 'Online' };
  const REFERENCE_TYPE_OF_MODE = { Cheque: 'Cheque No.', 'Bank Transfer': 'UTR', NEFT: 'UTR', RTGS: 'UTR', UPI: 'UPI Ref.' };

  let candidates = [];
  let codeByPartyName = {};
  let invoiceAmountByNo = {};
  let capFactor = () => 1;

  if (partyType === 'Vendor') {
    const [vendors, allInvoices, supplierPayments, paymentVouchers] = await Promise.all([
      prisma.businessPartner.findMany({ where: { partnerType: 'Vendor' }, select: { partnerName: true, partnerCode: true } }),
      // EVERY purchase invoice (same population as the Purchase Invoice
      // Register) — `status` separates the active ones used for settlement.
      prisma.purchaseInvoice.findMany({
        select: { invoiceNo: true, amount: true, supplier: true, invoiceDate: true, paymentStatus: true, status: true, branch: true },
      }),
      prisma.supplierPayment.findMany({
        where: statusFilter ? { status: statusFilter } : {},
        include: { invoiceApplications: true },
      }),
      prisma.paymentVoucher.findMany({
        where: { partyType: 'Vendor', ...(statusFilter ? { status: statusFilter } : {}) },
        include: { applications: true },
      }),
    ]);

    codeByPartyName = Object.fromEntries(vendors.map((v) => [v.partnerName, v.partnerCode]));
    // Settlement (and the dashboard's cap) only ever looks at active invoices.
    allInvoices
      .filter((i) => !['Draft', 'Cancelled'].includes(i.status))
      .forEach((i) => { if (i.invoiceNo) invoiceAmountByNo[i.invoiceNo] = Number(i.amount || 0); });

    // Per-invoice cap, computed over every POSTED application all-time (the
    // same population the dashboard caps over) so filtering by date/supplier
    // never changes how much an individual payment is credited.
    const appliedByInvoice = {};
    const addPosted = (apps) => apps.forEach((a) => {
      if (a.invoiceNo && Object.prototype.hasOwnProperty.call(invoiceAmountByNo, a.invoiceNo)) {
        appliedByInvoice[a.invoiceNo] = (appliedByInvoice[a.invoiceNo] || 0) + Number(a.amountApplied || 0);
      }
    });
    supplierPayments.filter((p) => p.status === 'Posted').forEach((p) => addPosted(p.invoiceApplications));
    paymentVouchers.filter((p) => p.status === 'Posted' && !p.paymentOnAccount).forEach((p) => addPosted(p.applications));
    capFactor = (invoiceNo) => {
      const applied = appliedByInvoice[invoiceNo] || 0;
      const cap = invoiceAmountByNo[invoiceNo];
      return applied > cap && applied > 0 ? cap / applied : 1;
    };

    const settle = (apps) => {
      let paidAmount = 0;
      const invoiceNos = [];
      (apps || []).forEach((a) => {
        if (!a.invoiceNo || !Object.prototype.hasOwnProperty.call(invoiceAmountByNo, a.invoiceNo)) return; // not an active purchase invoice
        paidAmount += Number(a.amountApplied || 0) * capFactor(a.invoiceNo);
        if (!invoiceNos.includes(a.invoiceNo)) invoiceNos.push(a.invoiceNo);
      });
      return { paidAmount, invoiceNos };
    };

    candidates = [
      ...supplierPayments.map((p) => ({
        key: `SP-${p.id}`,
        paymentNo: p.paymentNo,
        date: p.paymentDate,
        partyCode: null,
        partyName: p.supplierName,
        paymentMode: p.paymentMode,
        referenceNo: p.instrumentNo,
        bankName: p.payFromAccount,
        paidBy: p.paidBy,
        dueDate: p.paymentDate,
        remarks: p.remarks || p.notes,
        transNo: p.id,
        status: p.status,
        branch: p.branch,
        currency: normCurrency(p.paymentCurrency),
        docAmount: Number(p.paymentAmount || 0),
        onAccount: false,
        ...settle(p.invoiceApplications),
      })),
      ...paymentVouchers.map((p) => ({
        key: `PV-${p.id}`,
        paymentNo: p.paymentVoucherNo,
        date: p.documentDate || p.postingDate,
        partyCode: p.partyCode,
        partyName: p.partyName,
        paymentMode: p.paymentMode,
        referenceNo: p.transactionNo || p.reference,
        bankName: p.paymentGlAccount,
        paidBy: null,
        dueDate: p.dueDate || p.documentDate || p.postingDate,
        remarks: p.remarks || p.journalRemarks,
        transNo: p.id,
        status: p.status,
        branch: p.branch,
        currency: normCurrency(p.currency),
        docAmount: Number(p.totalDue || 0),
        onAccount: Boolean(p.paymentOnAccount),
        ...settle(p.applications),
      })),
    ]
      .map((c) => {
        // Counted = exactly what the dashboard's "Total Payables" counts: a
        // Posted, not-on-account document that settled an active purchase
        // invoice. Anything else is still listed (full document amount) so
        // no payment is hidden, but stays out of the totals.
        const counted = c.status === 'Posted' && !c.onAccount && c.invoiceNos.length > 0;
        return { ...c, counted, paidAmount: counted ? c.paidAmount : c.docAmount, invoiceNos: counted ? c.invoiceNos : [] };
      })
      ;

    // Purchase invoices that no counted payment settles are still listed — as
    // an invoice-only row (no payment no., Payment Amount 0, Status = the
    // invoice's own Paid/Unpaid/Partial state) — so every invoice the
    // Purchase Invoice Register shows also appears here and the Invoice
    // Amount column total equals that register's Net Amount total.
    const coveredInvoices = new Set();
    candidates.filter((c) => c.counted).forEach((c) => c.invoiceNos.forEach((no) => coveredInvoices.add(no)));
    allInvoices
      .filter((i) => i.invoiceNo && !coveredInvoices.has(i.invoiceNo))
      .forEach((i) => {
        candidates.push({
          key: `PI-${i.invoiceNo}`,
          paymentNo: '—',
          date: i.invoiceDate,
          partyCode: null,
          partyName: i.supplier,
          paymentMode: null,
          referenceNo: null,
          bankName: null,
          paidBy: null,
          status: i.paymentStatus || 'Unpaid',
          branch: i.branch,
          currency: 'INR',
          docAmount: 0,
          onAccount: false,
          paidAmount: 0,
          invoiceNos: [],
          counted: true,
          invoiceOnly: true,
          fixedInvoiceAmount: Number(i.amount || 0),
        });
      });
    candidates = candidates.filter((c) => !supplier || c.partyName === supplier);
  } else {
    const accountVouchers = await prisma.paymentVoucher.findMany({
      where: { partyType: 'Account', ...(statusFilter ? { status: statusFilter } : {}) },
    });
    candidates = accountVouchers.map((p) => ({
      key: `PV-${p.id}`,
      paymentNo: p.paymentVoucherNo,
      date: p.documentDate || p.postingDate,
      partyCode: p.partyCode,
      partyName: p.partyName,
      paymentMode: p.paymentMode,
      referenceNo: p.transactionNo || p.reference,
      bankName: p.paymentGlAccount,
      paidBy: null,
      dueDate: p.dueDate || p.documentDate || p.postingDate,
      remarks: p.remarks || p.journalRemarks,
      transNo: p.id,
      status: p.status,
      branch: p.branch,
      currency: normCurrency(p.currency),
      paidAmount: Number(p.totalDue || 0),
      invoiceNos: [],
      counted: p.status === 'Posted',
    }))
      .filter((c) => !account || c.partyCode === account);
    accountVouchers.forEach((p) => { if (p.partyCode) codeByPartyName[p.partyName] = p.partyCode; });
  }

  candidates = candidates
    .filter((c) => !paymentMode || c.paymentMode === paymentMode)
    .filter((c) => !paymentMethod || METHOD_OF_MODE[c.paymentMode] === paymentMethod)
    .filter((c) => !referenceType || REFERENCE_TYPE_OF_MODE[c.paymentMode] === referenceType)
    .filter((c) => !branch || c.branch === branch)
    .filter((c) => !currency || c.currency === String(currency).toUpperCase());

  if (showUnreconciledPayments === 'Yes' && candidates.length) {
    const unreconciledLines = await prisma.bankReconciliationTransaction.findMany({
      where: { source: 'System', status: { not: 'Reconciled' }, voucherNo: { in: candidates.map((c) => c.paymentNo) } },
      select: { voucherNo: true },
    });
    const unreconciledNos = new Set(unreconciledLines.map((l) => l.voucherNo));
    candidates = candidates.filter((c) => unreconciledNos.has(c.paymentNo));
  }

  const toRow = (c, idx) => ({
    id: c.key,
    paymentNo: c.paymentNo,
    paymentDate: c.date,
    supplierCode: codeByPartyName[c.partyName] || c.partyCode || '—',
    supplierName: c.partyName || 'Unknown',
    accountCode: c.partyCode || codeByPartyName[c.partyName] || '—',
    accountName: c.partyName || 'Unknown',
    paymentMode: c.paymentMode || '—',
    referenceNo: c.referenceNo || '—',
    bankName: c.bankName || '—',
    invoiceNos: c.invoiceNos,
    invoiceAmount: c.fixedInvoiceAmount != null ? c.fixedInvoiceAmount : 0,
    invoiceOnly: Boolean(c.invoiceOnly),
    paymentAmount: c.paidAmount,
    discount: 0,
    netPaid: c.paidAmount,
    paidBy: c.paidBy || '—',
    branch: c.branch || '',
    dueDate: c.dueDate || c.date || null,
    remarks: c.remarks || '',
    transNo: c.transNo != null ? c.transNo : '',
    status: c.status,
    counted: c.counted,
    _t: c.date ? new Date(c.date).getTime() : 0,
    _i: idx,
  });

  const allRows = candidates.map(toRow).sort((a, b) => (b._t - a._t) || (a._i - b._i));
  const inPeriod = (r) => {
    if (!r._t) return !from && !to;
    if (from && r._t < from.getTime()) return false;
    if (to && r._t > to.getTime()) return false;
    return true;
  };
  const periodRows = allRows.filter(inPeriod);

  // Invoice Amount: the invoice's Net Amount (PurchaseInvoice.amount), once
  // per invoice, on the earliest payment that settles it.
  const seenInvoices = new Set();
  [...periodRows].reverse().forEach((r) => {
    if (r.invoiceOnly) return;
    let amt = 0;
    r.invoiceNos.forEach((no) => {
      if (seenInvoices.has(no)) return;
      seenInvoices.add(no);
      amt += invoiceAmountByNo[no] || 0;
    });
    r.invoiceAmount = amt;
  });
  const rows = periodRows.map(({ _t, _i, invoiceNos, ...r }) => ({ ...r, paymentDate: r.invoiceOnly ? null : r.paymentDate }));

  const countedRows = rows.filter((r) => r.counted);
  const paidRows = countedRows.filter((r) => r.paymentAmount > 0);
  const totals = countedRows.reduce((acc, r) => ({
    invoiceAmount: acc.invoiceAmount + r.invoiceAmount,
    paymentAmount: acc.paymentAmount + r.paymentAmount,
    discount: acc.discount + r.discount,
    netPaid: acc.netPaid + r.netPaid,
  }), { invoiceAmount: 0, paymentAmount: 0, discount: 0, netPaid: 0 });

  const totalPayments = totals.paymentAmount;
  const cashAmount = countedRows.filter((r) => r.paymentMode === 'Cash').reduce((sum, r) => sum + r.paymentAmount, 0);
  const upiAmount = countedRows.filter((r) => r.paymentMode === 'UPI').reduce((sum, r) => sum + r.paymentAmount, 0);
  const bankAmount = Math.max(totalPayments - cashAmount - upiAmount, 0);

  // Payment by Payment Mode — donut over the exact payment mode values in
  // use (Top 5 + Others), across the full filtered set.
  const byModeValue = {};
  paidRows.forEach((r) => { byModeValue[r.paymentMode] = (byModeValue[r.paymentMode] || 0) + r.paymentAmount; });
  const modeEntries = Object.entries(byModeValue).sort((a, b) => b[1] - a[1]);
  const modeGrandTotal = totalPayments || 1;
  const top5Modes = modeEntries.slice(0, 5);
  const othersModeValue = modeEntries.slice(5).reduce((sum, [, v]) => sum + v, 0);
  const paymentByPaymentMode = [
    ...top5Modes.map(([name, value]) => ({ name, value: Math.round(value), percent: Math.round((value / modeGrandTotal) * 1000) / 10 })),
    ...(othersModeValue > 0 ? [{ name: 'Others', value: Math.round(othersModeValue), percent: Math.round((othersModeValue / modeGrandTotal) * 1000) / 10 }] : []),
  ];

  // Payment Trend (Last 7 Days) — always the 7 calendar days ending at `to`
  // (or today), independent of the From date, built from the same reconciled
  // rows (every other filter applies) so it can never disagree with the table.
  const trendEnd = to ? new Date(to) : new Date();
  const trendDays = [];
  for (let i = 6; i >= 0; i -= 1) {
    const d = new Date(trendEnd);
    d.setDate(d.getDate() - i);
    d.setHours(0, 0, 0, 0);
    trendDays.push(d);
  }
  const pad2 = (n) => String(n).padStart(2, '0');
  const paymentTrend = trendDays.map((d) => {
    const dayTotal = allRows
      .filter((r) => r.counted && r._t && new Date(r._t).toDateString() === d.toDateString())
      .reduce((sum, r) => sum + r.paymentAmount, 0);
    return { name: `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}`, value: Math.round(dayTotal) };
  });

  // Top 5 Suppliers (or Accounts) by Payment.
  const byPartyValue = {};
  paidRows.forEach((r) => { byPartyValue[r.supplierName] = (byPartyValue[r.supplierName] || 0) + r.paymentAmount; });
  const top5SuppliersByPayment = Object.entries(byPartyValue).sort((a, b) => b[1] - a[1]).slice(0, 5)
    .map(([name, value]) => ({ name, value: Math.round(value) }));

  res.json({
    success: true,
    data: {
      partyType,
      rows,
      totals,
      stats: {
        totalPayments,
        totalPaymentTransactions: rows.filter((r) => !r.invoiceOnly).length,
        suppliersPaid: new Set(paidRows.map((r) => r.supplierName)).size,
        bankAmount,
        cashAmount,
        upiAmount,
      },
      paymentByPaymentMode,
      paymentTrend,
      top5SuppliersByPayment,
    },
  });
}));

// Payment Receipt ("Incoming Payment") -- a master/detail resource
// (PaymentReceipt has many PaymentReceiptApplication rows), same
// bespoke-route pattern as Collection/SupplierPayment above. Unlike those
// two (each locked to one party type), a Payment Receipt posts against a
// Customer, a Vendor, or a raw Chart-Of-Accounts Account, chosen via
// partyType -- so which open-item ledger (if any) it settles through is
// resolved per-record rather than fixed at mount time. Customer/Vendor
// receipts reuse the exact same customerLedger/supplierLedger instances
// Collection/SupplierPayment already use, so apply/reverse stays a single
// shared implementation. An Account party type, and any receipt with
// paymentOnAccount checked, never touch CustomerOutstanding/
// SupplierOutstanding at all -- there is no advance/GL-journal table in this
// schema for either case to post against, so those receipts are simply
// recorded with no ledger side effects.
// paymentMode / paymentGlAccount / bankChargesAccount / bankChargesAmount
// (the Payment Modes dialog's breakdown -- see
// components/banking/PaymentModesDialog.jsx and utils/glPosting.js's
// resolvePaymentModeCashAccount) are plain scalar columns on the model, not
// in PROTECTED_HEADER_FIELDS, so sanitizeHeader's blocklist lets them
// through unchanged on both create and update below -- no extra whitelist
// entry needed, same as every other free-typed header field.
const paymentReceiptInclude = { applications: { orderBy: { id: 'asc' } } };

function toPaymentReceiptApplicationData(app) {
  return {
    invoiceNo: app.invoiceNo || null,
    invoiceDate: app.invoiceDate || null,
    dueDate: app.dueDate || null,
    totalAmount: app.totalAmount != null ? Number(app.totalAmount) : 0,
    outstandingAtTimeOfApplication: app.outstandingAtTimeOfApplication != null ? Number(app.outstandingAtTimeOfApplication) : 0,
    amountApplied: app.amountApplied != null ? Number(app.amountApplied) : 0,
  };
}

/** Which open-item ledger (if any) a Payment Receipt settles through. */
function ledgerForPaymentReceipt(row) {
  if (row.paymentOnAccount) return null;
  if (row.partyType === 'Customer') return customerLedger;
  if (row.partyType === 'Vendor') return supplierLedger;
  return null; // 'Account' has no open-item ledger to settle against.
}

/** Which invoice/paymentStatus cascade (if any) a Payment Receipt feeds. */
function paymentStatusSyncFor(row) {
  if (row.partyType === 'Customer') return syncSalesInvoicePaymentStatus;
  if (row.partyType === 'Vendor') return syncPurchaseInvoicePaymentStatus;
  return null;
}

router.get('/banking/payment-receipts', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { paymentReceiptNo: { contains: q } },
        { partyName: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.paymentReceipt.findMany({ where: withBranchScope(where, req), include: paymentReceiptInclude, orderBy: { id: 'desc' } });
  await attachJournalEntryRefs(rows, JOURNAL_SOURCE_TYPES.PAYMENT_RECEIPT, 'paymentReceiptNo');
  res.json({ success: true, data: rows });
}));

router.get('/banking/payment-receipts/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.paymentReceipt.findUnique({ where: { id: Number(req.params.id) }, include: paymentReceiptInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  await attachJournalEntryRefs(row, JOURNAL_SOURCE_TYPES.PAYMENT_RECEIPT, 'paymentReceiptNo');
  res.json({ success: true, data: row });
}));

router.post('/banking/payment-receipts', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue paymentReceiptNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { applications = [], seriesId, ...rawHeader } = req.body;
  // `roundOff` is a plain user-typed figure here (there's nothing to compute
  // it from, unlike the tax-rounding use of the same column name on
  // Sales/Purchase documents), so it has to be let through explicitly —
  // same reason Cheque's `amount` is allowed through below.
  const header = sanitizeHeader(rawHeader, { allow: ['roundOff'], alsoBlock: ['appliedAmount', 'openBalance'] });
  // An Account party has no outstanding invoices to apply against, and
  // Payment on Account is explicitly "don't settle anything" — either way
  // the applications the client sent are ignored rather than saved.
  const appData = (header.partyType === 'Account' || header.paymentOnAccount)
    ? []
    : applications.map(toPaymentReceiptApplicationData);
  const appliedAmount = round2(appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0));
  const openBalance = round2(Number(header.totalAmountDue || 0) - appliedAmount - Number(header.roundOff || 0));

  const row = await prisma.$transaction(async (tx) => {
    // paymentReceiptNo comes from the configured IP (Payment Receipt)
    // numbering series rather than free text — see resolveDocumentNumber
    // above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('IP', header.paymentReceiptNo, tx, seriesId || null);
    const created = await tx.paymentReceipt.create({
      data: { ...header, paymentReceiptNo: documentNumber, appliedAmount, openBalance, applications: { create: appData } },
      include: paymentReceiptInclude,
    });
    if (syncManual) await syncManual();

    const ledger = ledgerForPaymentReceipt(created);
    if (created.status === 'Posted' && ledger) {
      // Validate before applying — a receipt that over-settles is rejected
      // outright rather than partially posted, same rule as Collection/
      // SupplierPayment.
      await ledger.assertApplicationsValid(tx, appData, {
        paymentAmount: created.totalAmountDue,
        partyName: created.partyName,
      });
      await ledger.apply(tx, appData);
      const syncStatus = paymentStatusSyncFor(created);
      if (syncStatus) {
        for (const app of appData) {
          if (app.invoiceNo) await syncStatus(tx, app.invoiceNo);
        }
      }
    }
    // Dr Cash/Bank / Cr the party's control account. Valued at appliedAmount
    // -- what actually settled against the ledger. See utils/glPosting.js.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.PAYMENT_RECEIPT,
      sourceDocNo: created.paymentReceiptNo,
      status: created.status,
      doc: created,
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/banking/payment-receipts/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { applications = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader, { allow: ['roundOff'], alsoBlock: ['appliedAmount', 'openBalance'] });
  const appData = (header.partyType === 'Account' || header.paymentOnAccount)
    ? []
    : applications.map(toPaymentReceiptApplicationData);
  const appliedAmount = round2(appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0));
  const openBalance = round2(Number(header.totalAmountDue || 0) - appliedAmount - Number(header.roundOff || 0));

  // Replace the applied-invoice set wholesale on every save -- simpler and
  // safer than diffing which rows were added/removed/edited client-side.
  const row = await prisma.$transaction(async (tx) => {
    // If this receipt was already Posted before this save (against whatever
    // party type it had *then*), reverse that first — using the OLD row's
    // ledger, not the new one, since partyType/paymentOnAccount may have
    // changed on this very save.
    const existing = await tx.paymentReceipt.findUnique({ where: { id }, include: paymentReceiptInclude });
    if (existing?.status === 'Posted') {
      const existingLedger = ledgerForPaymentReceipt(existing);
      if (existingLedger) await existingLedger.reverse(tx, existing.applications);
    }
    await tx.paymentReceiptApplication.deleteMany({ where: { paymentReceiptId: id } });
    const updated = await tx.paymentReceipt.update({
      where: { id },
      data: { ...header, appliedAmount, openBalance, applications: { create: appData } },
      include: paymentReceiptInclude,
    });

    const ledger = ledgerForPaymentReceipt(updated);
    if (updated.status === 'Posted' && ledger) {
      await ledger.assertApplicationsValid(tx, appData, {
        paymentAmount: updated.totalAmountDue,
        partyName: updated.partyName,
      });
      await ledger.apply(tx, appData);
    }
    // Sync every invoice touched by either the old or the new application
    // set — one dropped from this receipt needs its paymentStatus pulled
    // back down just as much as one newly added needs pushing up. Uses the
    // NEW row's party type, since an invoice can only belong to one side.
    const syncStatus = paymentStatusSyncFor(updated);
    if (syncStatus) {
      const touchedInvoiceNos = new Set([
        ...(existing?.applications || []).map((a) => a.invoiceNo).filter(Boolean),
        ...appData.map((a) => a.invoiceNo).filter(Boolean),
      ]);
      for (const invoiceNo of touchedInvoiceNos) {
        await syncStatus(tx, invoiceNo);
      }
    }
    // Rebuild the accounting document from what this receipt now says -- a
    // receipt pulled back to Draft loses its ledger entry entirely.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.PAYMENT_RECEIPT,
      sourceDocNo: updated.paymentReceiptNo,
      status: updated.status,
      doc: updated,
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/banking/payment-receipts/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // Deleting the document deletes its accounting document too -- a
  // ledger entry for a document that no longer exists is worse than no
  // entry at all. See reverseJournalEntry in utils/glPosting.js.
  await removeJournalEntryForDocument(
    prisma, JOURNAL_SOURCE_TYPES.PAYMENT_RECEIPT, 'paymentReceipt', 'paymentReceiptNo', Number(req.params.id)
  );
  // PaymentReceiptApplication.paymentReceipt has onDelete: Cascade, so
  // applications go with it. If this receipt was Posted, its effect on the
  // relevant ledger needs reversing first, or the deleted receipt's amount
  // stays "applied" forever with no record of why the balance is low.
  await prisma.$transaction(async (tx) => {
    const existing = await tx.paymentReceipt.findUnique({ where: { id: Number(req.params.id) }, include: paymentReceiptInclude });
    if (existing?.status === 'Posted') {
      const ledger = ledgerForPaymentReceipt(existing);
      if (ledger) await ledger.reverse(tx, existing.applications);
    }
    await tx.paymentReceipt.delete({ where: { id: Number(req.params.id) } });
    if (existing?.status === 'Posted') {
      const syncStatus = paymentStatusSyncFor(existing);
      if (syncStatus) {
        for (const app of existing.applications) {
          if (app.invoiceNo) await syncStatus(tx, app.invoiceNo);
        }
      }
    }
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Payment Voucher ("Outgoing Payment") -- a master/detail resource
// (PaymentVoucher has many PaymentVoucherApplication rows), the outgoing
// counterpart to Payment Receipt above. Only Vendor and Account party types
// exist here — there is no "pay a customer" concept — so Vendor settles
// through the very same supplierLedger Payment Entry/Payment Receipt already
// use, and Account (or any voucher with paymentOnAccount checked) never
// touches SupplierOutstanding at all, for the same reason Payment Receipt's
// Account/paymentOnAccount path doesn't.
// Same Payment Modes breakdown as Payment Receipt above -- passes through
// sanitizeHeader's blocklist unchanged.
const paymentVoucherInclude = { applications: { orderBy: { id: 'asc' } } };

function toPaymentVoucherApplicationData(app) {
  return {
    invoiceNo: app.invoiceNo || null,
    invoiceDate: app.invoiceDate || null,
    dueDate: app.dueDate || null,
    totalAmount: app.totalAmount != null ? Number(app.totalAmount) : 0,
    outstandingAtTimeOfApplication: app.outstandingAtTimeOfApplication != null ? Number(app.outstandingAtTimeOfApplication) : 0,
    amountApplied: app.amountApplied != null ? Number(app.amountApplied) : 0,
  };
}

/** Which open-item ledger (if any) a Payment Voucher settles through. */
function ledgerForPaymentVoucher(row) {
  if (row.paymentOnAccount) return null;
  if (row.partyType === 'Vendor') return supplierLedger;
  return null; // 'Account' has no open-item ledger to settle against.
}

router.get('/banking/payment-vouchers', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { paymentVoucherNo: { contains: q } },
        { partyName: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.paymentVoucher.findMany({ where: withBranchScope(where, req), include: paymentVoucherInclude, orderBy: { id: 'desc' } });
  await attachJournalEntryRefs(rows, JOURNAL_SOURCE_TYPES.PAYMENT_VOUCHER, 'paymentVoucherNo');
  res.json({ success: true, data: rows });
}));

router.get('/banking/payment-vouchers/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.paymentVoucher.findUnique({ where: { id: Number(req.params.id) }, include: paymentVoucherInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  await attachJournalEntryRefs(row, JOURNAL_SOURCE_TYPES.PAYMENT_VOUCHER, 'paymentVoucherNo');
  res.json({ success: true, data: row });
}));

router.post('/banking/payment-vouchers', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue paymentVoucherNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { applications = [], seriesId, ...rawHeader } = req.body;
  // `roundOff` is a plain user-typed figure here, same reasoning as Payment
  // Receipt's POST above.
  const header = sanitizeHeader(rawHeader, { allow: ['roundOff'], alsoBlock: ['appliedAmount', 'openBalance'] });
  // An Account party has no outstanding invoices to apply against, and
  // Payment on Account is explicitly "don't settle anything".
  const appData = (header.partyType === 'Account' || header.paymentOnAccount)
    ? []
    : applications.map(toPaymentVoucherApplicationData);
  const appliedAmount = round2(appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0));
  const openBalance = round2(Number(header.totalDue || 0) - appliedAmount - Number(header.roundOff || 0));

  const row = await prisma.$transaction(async (tx) => {
    // paymentVoucherNo comes from the configured OP (Payment Voucher)
    // numbering series rather than free text — see resolveDocumentNumber
    // above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('OP', header.paymentVoucherNo, tx, seriesId || null);
    const created = await tx.paymentVoucher.create({
      data: { ...header, paymentVoucherNo: documentNumber, appliedAmount, openBalance, applications: { create: appData } },
      include: paymentVoucherInclude,
    });
    if (syncManual) await syncManual();

    const ledger = ledgerForPaymentVoucher(created);
    if (created.status === 'Posted' && ledger) {
      // Validate before applying — a voucher that over-settles is rejected
      // outright rather than partially posted, same rule as Payment Entry/
      // Payment Receipt.
      await ledger.assertApplicationsValid(tx, appData, {
        paymentAmount: created.totalDue,
        partyName: created.partyName,
      });
      await ledger.apply(tx, appData);
      for (const app of appData) {
        if (app.invoiceNo) await syncPurchaseInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
    // Dr the party's control account / Cr Cash/Bank. See utils/glPosting.js.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.PAYMENT_VOUCHER,
      sourceDocNo: created.paymentVoucherNo,
      status: created.status,
      doc: created,
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/banking/payment-vouchers/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { applications = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader, { allow: ['roundOff'], alsoBlock: ['appliedAmount', 'openBalance'] });
  const appData = (header.partyType === 'Account' || header.paymentOnAccount)
    ? []
    : applications.map(toPaymentVoucherApplicationData);
  const appliedAmount = round2(appData.reduce((sum, a) => sum + Number(a.amountApplied || 0), 0));
  const openBalance = round2(Number(header.totalDue || 0) - appliedAmount - Number(header.roundOff || 0));

  // Replace the applied-invoice set wholesale on every save -- simpler and
  // safer than diffing which rows were added/removed/edited client-side.
  const row = await prisma.$transaction(async (tx) => {
    // If this voucher was already Posted before this save (against whatever
    // party type it had *then*), reverse that first — using the OLD row's
    // ledger, not the new one, since partyType/paymentOnAccount may have
    // changed on this very save.
    const existing = await tx.paymentVoucher.findUnique({ where: { id }, include: paymentVoucherInclude });
    if (existing?.status === 'Posted') {
      const existingLedger = ledgerForPaymentVoucher(existing);
      if (existingLedger) await existingLedger.reverse(tx, existing.applications);
    }
    await tx.paymentVoucherApplication.deleteMany({ where: { paymentVoucherId: id } });
    const updated = await tx.paymentVoucher.update({
      where: { id },
      data: { ...header, appliedAmount, openBalance, applications: { create: appData } },
      include: paymentVoucherInclude,
    });

    const ledger = ledgerForPaymentVoucher(updated);
    if (updated.status === 'Posted' && ledger) {
      await ledger.assertApplicationsValid(tx, appData, {
        paymentAmount: updated.totalDue,
        partyName: updated.partyName,
      });
      await ledger.apply(tx, appData);
    }
    // Sync every invoice touched by either the old or the new application
    // set — one dropped from this voucher needs its paymentStatus pulled
    // back down just as much as one newly added needs pushing up.
    const touchedInvoiceNos = new Set([
      ...(existing?.applications || []).map((a) => a.invoiceNo).filter(Boolean),
      ...appData.map((a) => a.invoiceNo).filter(Boolean),
    ]);
    for (const invoiceNo of touchedInvoiceNos) {
      await syncPurchaseInvoicePaymentStatus(tx, invoiceNo);
    }
    // Rebuild the accounting document from what this voucher now says.
    await syncJournalEntry(tx, {
      sourceType: JOURNAL_SOURCE_TYPES.PAYMENT_VOUCHER,
      sourceDocNo: updated.paymentVoucherNo,
      status: updated.status,
      doc: updated,
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/banking/payment-vouchers/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // Deleting the document deletes its accounting document too -- a
  // ledger entry for a document that no longer exists is worse than no
  // entry at all. See reverseJournalEntry in utils/glPosting.js.
  await removeJournalEntryForDocument(
    prisma, JOURNAL_SOURCE_TYPES.PAYMENT_VOUCHER, 'paymentVoucher', 'paymentVoucherNo', Number(req.params.id)
  );
  // PaymentVoucherApplication.paymentVoucher has onDelete: Cascade, so
  // applications go with it. If this voucher was Posted, its effect on
  // SupplierOutstanding needs reversing first, or the deleted voucher's
  // amount stays "applied" forever with no record of why the balance is low.
  await prisma.$transaction(async (tx) => {
    const existing = await tx.paymentVoucher.findUnique({ where: { id: Number(req.params.id) }, include: paymentVoucherInclude });
    if (existing?.status === 'Posted') {
      const ledger = ledgerForPaymentVoucher(existing);
      if (ledger) await ledger.reverse(tx, existing.applications);
    }
    await tx.paymentVoucher.delete({ where: { id: Number(req.params.id) } });
    if (existing?.status === 'Posted') {
      for (const app of existing.applications) {
        if (app.invoiceNo) await syncPurchaseInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// "Send via WhatsApp" -- Payment Receipt (Incoming Payment) / Payment
// Voucher (Outgoing Payment). Same shape as the Sales Quotation/Invoice
// routes above: the PDF is rendered entirely in the browser (see
// capturePaymentReceiptPdf/capturePaymentVoucherPdf on the frontend, which
// screenshot the exact same printable the Print button now produces for
// these two documents) and arrives here as a regular file upload. This
// route's only jobs are: stash the PDF in OCI behind a short-lived
// pre-signed URL, resolve the party's current WhatsApp number LIVE from
// the Business Partner master (same fix as the sales routes' own
// findPartnerWhatsAppNumber lookup -- a number entered on the document
// itself would go stale the moment someone corrects it on the Business
// Partner record), and hand it all to whatsappBusiness.service.js.
router.post('/banking/payment-receipts/:id/whatsapp/send', auth(), handleWhatsappPdfUpload, asyncHandler(async (req, res) => {
  if (!req.file) {
    return res.status(400).json({ success: false, message: 'No PDF uploaded.' });
  }
  const id = Number(req.params.id);
  const receipt = await prisma.paymentReceipt.findUnique({ where: { id } });
  if (!receipt) return res.status(404).json({ success: false, message: 'Record not found' });
  if (!receipt.paymentReceiptNo) {
    return res.status(400).json({ success: false, message: 'Save the payment receipt before sending it.' });
  }

  // A "Account" party (a GL account, not a customer/vendor) has no
  // Business Partner record and no WhatsApp number of its own -- this
  // simply falls through to req.body?.phone (if the frontend has one) and
  // otherwise reports "no number on file", same as any other party with
  // none.
  const phone = (await findPartnerWhatsAppNumber(receipt.partyName)) || req.body?.phone;
  if (!phone) {
    return res.status(400).json({ success: false, message: 'No WhatsApp/mobile number on file for this party.' });
  }

  const key = `whatsapp/payment-receipt/${id}/${crypto.randomUUID()}.pdf`;
  await uploadObject(key, req.file.buffer, 'application/pdf');
  try {
    const documentUrl = await getPresignedUrl(key, WHATSAPP_PDF_PRESIGN_TTL_SECONDS);
    const paymentDateStr = receipt.documentDate ? new Date(receipt.documentDate).toLocaleDateString('en-GB').replace(/\//g, '-') : '';
    // Matches the approved "kemach_incoming_payments" template's body
    // exactly: {{1}} name, {{2}} Payment No., {{3}} Payment Date,
    // {{4}} Amount Received, {{5}} Reference No.
    const bodyParams = parseWhatsappBodyParams(req.body?.bodyParams).length
      ? parseWhatsappBodyParams(req.body?.bodyParams)
      : [
        receipt.partyName || 'Customer',
        receipt.paymentReceiptNo || '',
        paymentDateStr,
        receipt.totalAmountDue != null ? Number(receipt.totalAmountDue).toFixed(2) : '0.00',
        receipt.reference || '',
      ];
    const safeFilename = `${String(receipt.paymentReceiptNo || 'payment-receipt').replace(/[\/\\?%*:|"<>]/g, '_')}.pdf`;
    const providerResponse = await whatsappBusiness.sendDocumentTemplate({
      to: phone,
      templateName: whatsappBusiness.cfg().TEMPLATE_NAME_PAYMENT_RECEIPT,
      documentUrl,
      documentFilename: safeFilename,
      bodyParams,
    });
    setTimeout(() => {
      deleteObject(key).catch(() => { });
    }, 30 * 60 * 1000).unref?.();

    res.json({ success: true, data: providerResponse });
  } catch (err) {
    await deleteObject(key).catch(() => { });
    throw err;
  }
}));

