// Banking
// Deposit Entry -- a master/detail resource (BankDeposit has many
// DepositItem rows), same bespoke-route pattern as Payment Entry above
// (mirrors crudRouter's URL/method/response shape so the frontend keeps
// using the generic bankDepositApi from createCrudApi). Replaces the old
// flat crudRouter(prisma.bankDeposit, ...) mount now that the model has a
// nested line-items collection.
const bankDepositInclude = { items: { orderBy: { id: 'asc' } } };

function toDepositItemData(item) {
  return {
    paymentMode: item.paymentMode || null,
    instrumentNo: item.instrumentNo || null,
    instrumentDate: item.instrumentDate || null,
    accountDescription: item.accountDescription || null,
    amount: round2(item.amount != null ? Number(item.amount) : 0),
  };
}

/**
 * Reject a deposit line for a negative amount.
 *
 * A deposit slip records money going *into* the bank; a negative line is not a
 * withdrawal, it is a data-entry error. The form already blocks the minus key
 * and the Zod schema rejects it, but neither of those protects the API — and
 * the deposit total now feeds the Cash Book, Bank Book and Day Book balances,
 * so a negative line posted directly would quietly understate the bank
 * position rather than failing visibly.
 *
 * A zero line is allowed: a slip can legitimately carry a placeholder row that
 * has not been filled in yet.
 */
function assertNonNegativeDepositItems(items) {
  const offending = items
    .map((item, index) => ({ index, amount: Number(item.amount) || 0 }))
    .filter((row) => row.amount < 0)
    .map((row) => `line ${row.index + 1} (${row.amount.toFixed(2)})`);

  if (offending.length) {
    const err = new Error(
      `A deposit amount cannot be negative — ${offending.join(', ')}.`
    );
    err.status = 400;
    throw err;
  }
}

// The term-deposit fields arrive as strings from the form (or as '' when
// left blank on a non-term deposit), and Prisma's Decimal columns reject
// both — normalise them to a number or null before they reach the header
// spread.
function toBankDepositHeaderData(header) {
  const blankToNull = (v) => (v === '' || v == null ? null : v);
  const numberOrNull = (v) => {
    const n = blankToNull(v);
    return n == null || Number.isNaN(Number(n)) ? null : Number(n);
  };
  return {
    ...header,
    interestRate: numberOrNull(header.interestRate),
    maturityDate: blankToNull(header.maturityDate),
    maturityAmount: numberOrNull(header.maturityAmount),
  };
}

