router.post('/banking/reconciliations', auth(), asyncHandler(async (req, res) => {
  const { transactions = [], ...header } = req.body;
  const row = await prisma.bankReconciliation.create({
    data: { ...header, transactions: { create: transactions.map(toReconciliationTxnData) } },
    include: bankReconciliationInclude,
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/banking/reconciliations/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  const { transactions = [], ...header } = req.body;
  // Replace the transaction set wholesale on every save -- simpler and
  // safer than diffing which rows were matched/unmatched client-side.
  const row = await prisma.$transaction(async (tx) => {
    await tx.bankReconciliationTransaction.deleteMany({ where: { reconciliationId: id } });
    return tx.bankReconciliation.update({
      where: { id },
      data: { ...header, transactions: { create: transactions.map(toReconciliationTxnData) } },
      include: bankReconciliationInclude,
    });
  });
  res.json({ success: true, data: row });
}));

router.delete('/banking/reconciliations/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // BankReconciliationTransaction.reconciliation has onDelete: Cascade.
  await prisma.bankReconciliation.delete({ where: { id: Number(req.params.id) } });
  res.json({ success: true, message: 'Deleted successfully' });
}));
// Cheque Print -- a master/detail resource (Cheque has many
// ChequeInvoiceApplication rows), same bespoke-route pattern as the other
// banking resources above.
const chequeInclude = { invoiceApplications: { orderBy: { id: 'asc' } } };

// A cheque settles the invoices listed on it. Previously it recorded an
// amountToPay per invoice and then did nothing with it — paying a supplier by
// cheque left the debt standing in full.
//
// Settlement follows the instrument, not the keystroke: a cheque only clears
// the debt once it has actually been issued. While it is Pending it is a
// draft, and if it is Cancelled or Bounced the settlement is reversed and the
// supplier is owed the money again.
/**
 * The party a cheque pays, for settlement purposes.
 *
 * The Cheque Print form captures the payee as `payTo` and has no separate
 * supplier field, so `supplierName` arrived null on every cheque and the
 * ledger's "does this invoice belong to the party paying" check silently did
 * nothing — the same defect that was fixed for collections and payments, and
 * which would have been reintroduced here. Falling back to `payTo` restores
 * the guard without asking the user to key the party twice.
 *
 * `payTo` can name a customer as well as a supplier (a refund cheque). That is
 * fine: the settlement lookup simply finds no supplier invoice under that
 * name, and a cheque with no applications settles nothing either way.
 */
const chequeParty = (header) => header.supplierName || header.payTo || null;

const CHEQUE_SETTLING_STATUSES = ['Printed', 'Issued', 'Presented', 'Cleared'];
const chequeSettles = (status) => CHEQUE_SETTLING_STATUSES.includes(status);

// The ledger keys applications by amountApplied; the cheque model calls the
// same figure amountToPay.
const chequeApplicationsForLedger = (apps) =>
  (apps || []).map((a) => ({ invoiceNo: a.invoiceNo, amountApplied: Number(a.amountToPay) || 0 }));

function toChequeApplicationData(app) {
  return {
    invoiceNo: app.invoiceNo || null,
    invoiceDate: app.invoiceDate || null,
    dueDate: app.dueDate || null,
    totalAmount: app.totalAmount != null ? Number(app.totalAmount) : 0,
    outstanding: app.outstanding != null ? Number(app.outstanding) : 0,
    amountToPay: app.amountToPay != null ? Number(app.amountToPay) : 0,
  };
}

router.get('/banking/cheques', auth(), asyncHandler(async (req, res) => {
  const { q } = req.query;
  const where = q
    ? {
      OR: [
        { chequeNo: { contains: q } },
        { payTo: { contains: q } },
        { bankAccount: { contains: q } },
      ],
    }
    : undefined;
  const rows = await prisma.cheque.findMany({ where: withBranchScope(where, req), include: chequeInclude, orderBy: { id: 'desc' } });
  res.json({ success: true, data: rows });
}));

router.get('/banking/cheques/:id', auth(), asyncHandler(async (req, res) => {
  const row = await prisma.cheque.findUnique({ where: { id: Number(req.params.id) }, include: chequeInclude });
  if (!row) return res.status(404).json({ success: false, message: 'Record not found' });
  res.json({ success: true, data: row });
}));

router.post('/banking/cheques', auth(), asyncHandler(async (req, res) => {
  // seriesId (which numbering series to issue chequeNo from) is chosen
  // on the create form and is not a column on this document — pulled out
  // before sanitizeHeader so it never reaches the Prisma create payload.
  const { invoiceApplications = [], seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader, { allow: ['amount'] });  // `amount` is the face value typed on the cheque, not a computed
  // total — it is the one document where that field is user input.
  const row = await prisma.$transaction(async (tx) => {
    // chequeNo now comes from the configured CHQ numbering series rather
    // than free text — see resolveDocumentNumber above.
    const { documentNumber, syncManual } = await resolveDocumentNumber('CHQ', header.chequeNo, tx, seriesId || null);
    const appData = invoiceApplications.map(toChequeApplicationData);
    const totalAppliedAmount = round2(appData.reduce((sum, a) => sum + (Number(a.amountToPay) || 0), 0));
    const created = await tx.cheque.create({
      data: {
        ...header, chequeNo: documentNumber, supplierName: chequeParty(header),
        totalAppliedAmount, invoiceApplications: { create: appData },
      },
      include: chequeInclude,
    });
    if (syncManual) await syncManual();
    if (chequeSettles(created.status)) {
      const ledgerApps = chequeApplicationsForLedger(appData);
      await supplierLedger.assertApplicationsValid(tx, ledgerApps, {
        paymentAmount: created.amount, partyName: created.supplierName,
      });
      await applyToSupplierOutstanding(tx, ledgerApps);
      for (const app of ledgerApps) {
        if (app.invoiceNo) await syncPurchaseInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
    // A cheque only actually leaves the bank account once it's been printed
    // and handed over — 'Pending' isn't a real bank-account movement yet.
    await syncBankReconciliationTxn(tx, {
      bankAccount: created.bankAccount, voucherType: 'Cheque', voucherNo: created.chequeNo,
      txnDate: created.chequeDate, type: 'Debit', amount: created.amount,
      description: `Cheque to ${created.payTo || 'payee'}`, remarks: created.narration,
      isActive: created.status === 'Printed',
    });
    return created;
  });
  res.status(201).json({ success: true, data: row });
}));

router.put('/banking/cheques/:id', auth(), asyncHandler(async (req, res) => {
  const id = Number(req.params.id);
  // Series selection is create-only: an edit keeps the number it already
  // has, so seriesId (if the client sends it at all) is discarded here
  // rather than reaching sanitizeHeader — the saved number is never
  // re-resolved.
  const { invoiceApplications = [], seriesId: _seriesId, ...rawHeader } = req.body;
  const header = sanitizeHeader(rawHeader, { allow: ['amount'] });  // `amount` is the face value typed on the cheque, not a computed
  // total — it is the one document where that field is user input.
  // Replace the applied-invoice set wholesale on every save.
  const row = await prisma.$transaction(async (tx) => {
    // Reverse whatever the previous version of this cheque had settled,
    // before re-applying — otherwise re-saving double-settles the invoice.
    const previousCheque = await tx.cheque.findUnique({ where: { id }, include: chequeInclude });
    if (previousCheque && chequeSettles(previousCheque.status)) {
      await reverseSupplierOutstanding(tx, chequeApplicationsForLedger(previousCheque.invoiceApplications));
    }
    await tx.chequeInvoiceApplication.deleteMany({ where: { chequeId: id } });
    const appData = invoiceApplications.map(toChequeApplicationData);
    const totalAppliedAmount = round2(appData.reduce((sum, a) => sum + (Number(a.amountToPay) || 0), 0));
    const updated = await tx.cheque.update({
      where: { id },
      data: {
        ...header, supplierName: chequeParty(header),
        totalAppliedAmount, invoiceApplications: { create: appData },
      },
      include: chequeInclude,
    });
    if (chequeSettles(updated.status)) {
      const ledgerApps = chequeApplicationsForLedger(appData);
      await supplierLedger.assertApplicationsValid(tx, ledgerApps, {
        paymentAmount: updated.amount, partyName: updated.supplierName,
      });
      await applyToSupplierOutstanding(tx, ledgerApps);
    }
    // Sync every invoice touched by either the old or the new application
    // set — one dropped from this cheque needs its paymentStatus pulled back
    // down just as much as one newly added to it needs pushing up.
    const touchedInvoiceNos = new Set([
      ...chequeApplicationsForLedger(previousCheque?.invoiceApplications).map((a) => a.invoiceNo).filter(Boolean),
      ...appData.map((a) => a.invoiceNo).filter(Boolean),
    ]);
    for (const invoiceNo of touchedInvoiceNos) {
      await syncPurchaseInvoicePaymentStatus(tx, invoiceNo);
    }
    await syncBankReconciliationTxn(tx, {
      bankAccount: updated.bankAccount, voucherType: 'Cheque', voucherNo: updated.chequeNo,
      txnDate: updated.chequeDate, type: 'Debit', amount: updated.amount,
      description: `Cheque to ${updated.payTo || 'payee'}`, remarks: updated.narration,
      isActive: updated.status === 'Printed',
    });
    return updated;
  });
  res.json({ success: true, data: row });
}));

router.delete('/banking/cheques/:id', auth(['admin']), asyncHandler(async (req, res) => {
  // ChequeInvoiceApplication.cheque has onDelete: Cascade.
  await prisma.$transaction(async (tx) => {
    const existing = await tx.cheque.findUnique({ where: { id: Number(req.params.id) }, include: chequeInclude });
    if (existing && chequeSettles(existing.status)) {
      // Deleting a settling cheque puts the debt back on the supplier.
      await reverseSupplierOutstanding(tx, chequeApplicationsForLedger(existing.invoiceApplications));
    }
    if (existing) {
      await syncBankReconciliationTxn(tx, {
        bankAccount: existing.bankAccount, voucherNo: existing.chequeNo, isActive: false,
      });
    }
    await tx.cheque.delete({ where: { id: Number(req.params.id) } });
    if (existing && chequeSettles(existing.status)) {
      for (const app of chequeApplicationsForLedger(existing.invoiceApplications)) {
        if (app.invoiceNo) await syncPurchaseInvoicePaymentStatus(tx, app.invoiceNo);
      }
    }
  });
  res.json({ success: true, message: 'Deleted successfully' });
}));

// Cash Book report — bespoke aggregation endpoint for the
// Reports > Cash/Bank Position > Cash Book page. There is no generic
// Voucher/Journal/Expense ledger model anywhere in this schema, so this
// report is honestly scoped to the real cash movement that does exist:
// Collection (customer receipts) and SupplierPayment (supplier payments),
// each optionally matched to a specific HouseBank "Cash Account" via its
// free-text depositTo/payFromAccount field (HouseBank.accountType is also
// free text with no enum distinguishing "Cash" from "Bank" accounts, so
// every HouseBank record is offered as a candidate Cash Account rather
// than guessing at a convention). Line items like "Office Expenses",
// "Salaries Paid", "Miscellaneous Receipt", or "Interest Received" have no
// backing document type in this schema (no Expense/JournalVoucher/
// PettyCash model exists) and are never fabricated — every row here is a
// real, posted Collection or SupplierPayment. "Particulars" falls back to
// "Collection from {customer}" / "Payment to {supplier}" when the
// document's own notes/remarks are blank. "Currency" and "Show Cancelled
// Transactions" are no-ops — every amount is implicitly INR, and neither
// Collection nor SupplierPayment ever carries a "Cancelled" status (only
// Draft/Posted). "Branch" DOES filter for real now: Collection, SupplierPayment,
// Cheque and BankDeposit all carry their own real `branch` string column
// (Branch.branchName convention, same as every other branch-scoped table in
// this schema — see ix_collection_branch/ix_supplier_payment_branch/
// ix_cheque_branch/ix_bank_deposit_branch), and HouseBank carries the
// equivalent `branchName` column. `req` is also threaded through so every
// query here goes through the same withBranchScope() row-level restriction
// (to the signed-in user's own granted branches) as every other bespoke
// report and CRUD list route in this file — a non-admin previously saw every
// branch's cash movement on this report regardless of their own grants.
async function computeCashBalanceAsOf(prismaClient, asOfDate, accountFilter, branchFilter, req) {
  const houseBankWhere = {};
  if (accountFilter) {
    houseBankWhere.OR = [{ accountName: accountFilter }, { bankName: accountFilter }];
  }
  if (branchFilter) houseBankWhere.branchName = branchFilter;
  const [houseBanks, collections, payments] = await Promise.all([
    prismaClient.houseBank.findMany({ where: withBranchScope(houseBankWhere, req, 'branchName'), select: { openingBalance: true } }),
    prismaClient.collection.findMany({
      where: withBranchScope({
        status: 'Posted',
        receiptDate: { lte: asOfDate },
        ...(accountFilter ? { depositTo: accountFilter } : {}),
        ...(branchFilter ? { branch: branchFilter } : {}),
      }, req),
      select: { paymentAmount: true, collectionNo: true },
    }),
    prismaClient.supplierPayment.findMany({
      where: withBranchScope({
        status: 'Posted',
        paymentDate: { lte: asOfDate },
        ...(accountFilter ? { payFromAccount: accountFilter } : {}),
        ...(branchFilter ? { branch: branchFilter } : {}),
      }, req),
      select: { paymentAmount: true, instrumentNo: true },
    }),
  ]);
  // Cheques and bank deposits move money too, and were both missing — the
  // balance was house-bank opening plus collections minus supplier payments
  // and nothing else, so every cheque written and every deposit banked was
  // invisible to the Cash Book, Bank Book and Day Book.
  //
  // Both have to be de-duplicated against what is already counted:
  //
  //   - a cheque tied to a Payment Entry (its supplier and amount already
  //     recorded as a SupplierPayment) would otherwise debit the account
  //     twice, so only cheques with no matching payment voucher count;
  //   - a Bank Deposit that banks a receipt already credited to this account
  //     via the Collection's "Deposit To" would likewise double up, so only
  //     deposits received from something other than a posted collection count.
  const [cheques, deposits] = await Promise.all([
    prismaClient.cheque.findMany({
      where: withBranchScope({
        status: { in: ['Printed', 'Issued', 'Presented', 'Cleared'] },
        chequeDate: { lte: asOfDate },
        ...(accountFilter ? { bankAccount: accountFilter } : {}),
        ...(branchFilter ? { branch: branchFilter } : {}),
      }, req),
      select: { amount: true, chequeNo: true, supplierName: true },
    }),
    prismaClient.bankDeposit.findMany({
      where: withBranchScope({
        status: 'Posted',
        depositDate: { lte: asOfDate },
        ...(accountFilter ? { depositTo: accountFilter } : {}),
        ...(branchFilter ? { branch: branchFilter } : {}),
      }, req),
      select: { totalDepositAmount: true },
    }),
  ]);

  // Payment vouchers already counted, keyed by the instrument number they
  // were issued against.
  const paidInstruments = new Set(
    payments.map((p) => (p.instrumentNo || '').trim()).filter(Boolean)
  );
  const baseline = round2(houseBanks.reduce((sum, b) => sum + Number(b.openingBalance || 0), 0));
  const receiptsTotal = round2(collections.reduce((sum, c) => sum + Number(c.paymentAmount || 0), 0));
  const paymentsTotal = round2(payments.reduce((sum, p) => sum + Number(p.paymentAmount || 0), 0));

  const chequesTotal = round2(
    cheques
      .filter((c) => !paidInstruments.has((c.chequeNo || '').trim()))
      .reduce((sum, c) => sum + Number(c.amount || 0), 0)
  );
  const depositsTotal = round2(
    deposits.reduce((sum, d) => sum + Number(d.totalDepositAmount || 0), 0)
  );

  return round2(baseline + receiptsTotal + depositsTotal - paymentsTotal - chequesTotal);
}

router.get('/banking/cash-book/report', auth(), asyncHandler(async (req, res) => {
  const {
    branch, cashAccount, fromDate, toDate, include, voucherType, openingBalanceAsOn,
  } = req.query;

  const from = fromDate ? new Date(fromDate) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : new Date();
  to.setHours(23, 59, 59, 999);
  const obAsOn = openingBalanceAsOn ? new Date(openingBalanceAsOn) : new Date(from.getTime() - 1);
  obAsOn.setHours(23, 59, 59, 999);

  const accountFilter = cashAccount || '';
  const branchFilter = branch || '';
  // Opening Balance is always the true historical cash position as of that
  // date (both receipts and payments), regardless of the "Include" filter
  // below — Include only scopes which transaction types populate the
  // ledger body/totals for this report run, it doesn't rewrite history.
  const openingBalance = await computeCashBalanceAsOf(prisma, obAsOn, accountFilter, branchFilter, req);

  const includeReceipts = include !== 'Payments Only';
  const includePayments = include !== 'Receipts Only';

  const [collections, supplierPayments] = await Promise.all([
    includeReceipts
      ? prisma.collection.findMany({
        where: withBranchScope({
          status: 'Posted',
          receiptDate: { gte: from, lte: to },
          ...(accountFilter ? { depositTo: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        orderBy: { receiptDate: 'asc' },
      })
      : [],
    includePayments
      ? prisma.supplierPayment.findMany({
        where: withBranchScope({
          status: 'Posted',
          paymentDate: { gte: from, lte: to },
          ...(accountFilter ? { payFromAccount: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        orderBy: { paymentDate: 'asc' },
      })
      : [],
  ]);

  const ledgerEntries = [
    ...collections.map((c) => ({
      date: c.receiptDate,
      voucherType: 'Receipt',
      voucherNo: c.collectionNo,
      particulars: c.notes || c.remarks || `Collection from ${c.customerName || 'Customer'}`,
      receipt: Number(c.paymentAmount || 0),
      payment: 0,
      referenceNo: c.instrumentNo || '—',
      remarks: c.remarks || '—',
    })),
    ...supplierPayments.map((p) => ({
      date: p.paymentDate,
      voucherType: 'Payment',
      voucherNo: p.paymentNo,
      particulars: p.notes || p.remarks || `Payment to ${p.supplierName || 'Supplier'}`,
      receipt: 0,
      payment: Number(p.paymentAmount || 0),
      referenceNo: p.instrumentNo || '—',
      remarks: p.remarks || '—',
    })),
  ].sort((a, b) => new Date(a.date) - new Date(b.date));

  // Running balance is computed over the FULL chronological ledger for the
  // period (never affected by the Voucher Type display filter below), so
  // the Balance column stays a true running total even if some voucher
  // types are hidden from view.
  let runningBalance = openingBalance;
  const fullRows = ledgerEntries.map((e) => {
    runningBalance += e.receipt - e.payment;
    return { ...e, balance: runningBalance };
  });

  const totalReceiptsFull = collections.reduce((sum, c) => sum + Number(c.paymentAmount || 0), 0);
  const totalPaymentsFull = supplierPayments.reduce((sum, p) => sum + Number(p.paymentAmount || 0), 0);
  const closingBalance = openingBalance + totalReceiptsFull - totalPaymentsFull;

  const openingRow = {
    date: from,
    voucherType: 'Opening Balance',
    voucherNo: `OB/${String(from.getDate()).padStart(2, '0')}/${String(from.getMonth() + 1).padStart(2, '0')}/${from.getFullYear()}`,
    particulars: 'Opening Balance',
    receipt: null,
    payment: null,
    referenceNo: '—',
    remarks: '—',
    balance: openingBalance,
  };

  // Voucher Type is a pure display filter over the fully-computed ledger —
  // it narrows which rows are shown, it does not recompute totals/balance.
  let rows = [openingRow, ...fullRows];
  if (voucherType && voucherType !== 'All') {
    rows = rows.filter((r) => r.voucherType === voucherType);
  }

  const totals = rows.reduce((acc, r) => ({
    receipt: acc.receipt + (r.receipt || 0),
    payment: acc.payment + (r.payment || 0),
  }), { receipt: 0, payment: 0 });

  // Receipt vs Payment donut, and Net Cash Inflow — always the true
  // period totals (independent of Voucher Type).
  const receiptVsPayment = [
    { name: 'Total Receipts', value: Math.round(totalReceiptsFull), percent: (totalReceiptsFull + totalPaymentsFull) > 0 ? Math.round((totalReceiptsFull / (totalReceiptsFull + totalPaymentsFull)) * 1000) / 10 : 0 },
    { name: 'Total Payments', value: Math.round(totalPaymentsFull), percent: (totalReceiptsFull + totalPaymentsFull) > 0 ? Math.round((totalPaymentsFull / (totalReceiptsFull + totalPaymentsFull)) * 1000) / 10 : 0 },
  ];

  // Cash Balance Trend (Last 7 Days) — a true balance snapshot for each of
  // the 7 calendar days ending at `to`, independent of Voucher Type/
  // Include, same "always the real underlying number" approach used for
  // Supplier Outstanding's 6-month trend.
  const trendDays = [];
  for (let i = 6; i >= 0; i -= 1) {
    const d = new Date(to);
    d.setDate(d.getDate() - i);
    d.setHours(23, 59, 59, 999);
    trendDays.push(d);
  }
  const pad2 = (n) => String(n).padStart(2, '0');
  const cashBalanceTrend = [];
  for (let i = 0; i < trendDays.length; i += 1) {
    const d = trendDays[i];
    // eslint-disable-next-line no-await-in-loop
    const balance = await computeCashBalanceAsOf(prisma, d, accountFilter, branchFilter, req);
    cashBalanceTrend.push({ name: `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}`, value: Math.round(balance) });
  }

  // Top Receipt Sources (customer-wise) — Collection has no ledger
  // "head"/category field (no Sales/Advance/Interest classification
  // exists), so the closest honest substitute is grouping by the paying
  // customer, same idea as Top 5 Customers by Collection on the
  // Collection Register report.
  const bySourceValue = {};
  collections.forEach((c) => {
    const name = c.customerName || 'Unknown';
    bySourceValue[name] = (bySourceValue[name] || 0) + Number(c.paymentAmount || 0);
  });
  const topReceiptSources = Object.entries(bySourceValue).sort((a, b) => b[1] - a[1]).slice(0, 5)
    .map(([name, value]) => ({ name, value: Math.round(value) }));

  res.json({
    success: true,
    data: {
      rows,
      totals,
      stats: {
        openingBalance,
        totalReceipts: totalReceiptsFull,
        totalPayments: totalPaymentsFull,
        closingBalance,
        noOfReceipts: collections.length,
        noOfPayments: supplierPayments.length,
      },
      receiptVsPayment,
      cashBalanceTrend,
      topReceiptSources,
    },
  });
}));

// Day Book report — bespoke aggregation endpoint for the
// Reports > Cash/Bank Position > Day Book page. Same real-data-only
// approach as Cash Book above (Collection + SupplierPayment, no fabricated
// Expense/Journal entries), but NOT restricted to a single Cash Account —
// it spans every account, real or generic, that ever appears in
// Collection.depositTo / SupplierPayment.payFromAccount (including
// placeholder labels like "Customer A/c"/"Vendor A/c" that aren't backed
// by a HouseBank record at all), and adds that raw account name as its own
// column. The optional "Account" filter matches literal depositTo/
// payFromAccount text rather than requiring a HouseBank match, since not
// every account name in use is a real HouseBank record.
router.get('/banking/day-book/report', auth(), asyncHandler(async (req, res) => {
  const {
    branch, account, fromDate, toDate, include, voucherType, openingBalanceAsOn,
  } = req.query;

  const from = fromDate ? new Date(fromDate) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : new Date();
  to.setHours(23, 59, 59, 999);
  const obAsOn = openingBalanceAsOn ? new Date(openingBalanceAsOn) : new Date(from.getTime() - 1);
  obAsOn.setHours(23, 59, 59, 999);

  const accountFilter = account || '';
  const branchFilter = branch || '';

  async function balanceAsOf(asOfDate) {
    // Baseline only applies when looking at the whole book — a specific
    // non-HouseBank account filter (e.g. "Customer A/c") has no opening
    // balance of its own to anchor to.
    // The two document totals are SUMmed in the database rather than fetched
    // and reduced: this is "since inception", so the old findMany pulled every
    // posted receipt and payment that has ever existed across the wire just to
    // add them up, and it is called again for each of the 7 trend days below.
    // `_sum` yields NULL, not 0, when nothing matches — Number(x || 0) is the
    // same coercion this file already applies to every other _sum read, and
    // reproduces the empty-reduce's 0 exactly. SQL SUM likewise ignores NULL
    // amounts, matching the per-row `Number(... || 0)` the reduce did.
    // Branch filters (and row-level branch-scopes) all three the same way
    // Cash Book's computeCashBalanceAsOf does — see that function's comment.
    const [houseBanks, collectionsAgg, paymentsAgg] = await Promise.all([
      accountFilter
        ? []
        : prisma.houseBank.findMany({
          where: withBranchScope(branchFilter ? { branchName: branchFilter } : undefined, req, 'branchName'),
          select: { openingBalance: true },
        }),
      prisma.collection.aggregate({
        where: withBranchScope({
          status: 'Posted',
          receiptDate: { lte: asOfDate },
          ...(accountFilter ? { depositTo: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        _sum: { paymentAmount: true },
      }),
      prisma.supplierPayment.aggregate({
        where: withBranchScope({
          status: 'Posted',
          paymentDate: { lte: asOfDate },
          ...(accountFilter ? { payFromAccount: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        _sum: { paymentAmount: true },
      }),
    ]);
    const baseline = houseBanks.reduce((sum, b) => sum + Number(b.openingBalance || 0), 0);
    const receiptsTotal = Number(collectionsAgg._sum.paymentAmount || 0);
    const paymentsTotal = Number(paymentsAgg._sum.paymentAmount || 0);
    return baseline + receiptsTotal - paymentsTotal;
  }

  // Opening Balance is always the true historical position as of that
  // date, regardless of the "Include" filter (same reasoning as Cash Book).
  const openingBalance = await balanceAsOf(obAsOn);

  const includeReceipts = include !== 'Payments Only';
  const includePayments = include !== 'Receipts Only';

  const [collections, supplierPayments] = await Promise.all([
    includeReceipts
      ? prisma.collection.findMany({
        where: withBranchScope({
          status: 'Posted',
          receiptDate: { gte: from, lte: to },
          ...(accountFilter ? { depositTo: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        orderBy: { receiptDate: 'asc' },
      })
      : [],
    includePayments
      ? prisma.supplierPayment.findMany({
        where: withBranchScope({
          status: 'Posted',
          paymentDate: { gte: from, lte: to },
          ...(accountFilter ? { payFromAccount: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        orderBy: { paymentDate: 'asc' },
      })
      : [],
  ]);

  const ledgerEntries = [
    ...collections.map((c) => ({
      date: c.receiptDate,
      voucherType: 'Receipt',
      voucherNo: c.collectionNo,
      accountName: c.depositTo || '—',
      particulars: c.notes || c.remarks || `Collection from ${c.customerName || 'Customer'}`,
      receipt: Number(c.paymentAmount || 0),
      payment: 0,
      referenceNo: c.instrumentNo || '—',
      remarks: c.remarks || '—',
    })),
    ...supplierPayments.map((p) => ({
      date: p.paymentDate,
      voucherType: 'Payment',
      voucherNo: p.paymentNo,
      accountName: p.payFromAccount || '—',
      particulars: p.notes || p.remarks || `Payment to ${p.supplierName || 'Supplier'}`,
      receipt: 0,
      payment: Number(p.paymentAmount || 0),
      referenceNo: p.instrumentNo || '—',
      remarks: p.remarks || '—',
    })),
  ].sort((a, b) => new Date(a.date) - new Date(b.date));

  let runningBalance = openingBalance;
  const fullRows = ledgerEntries.map((e) => {
    runningBalance += e.receipt - e.payment;
    return { ...e, balance: runningBalance };
  });

  const totalReceiptsFull = collections.reduce((sum, c) => sum + Number(c.paymentAmount || 0), 0);
  const totalPaymentsFull = supplierPayments.reduce((sum, p) => sum + Number(p.paymentAmount || 0), 0);
  const closingBalance = openingBalance + totalReceiptsFull - totalPaymentsFull;

  const openingRow = {
    date: from,
    voucherType: 'Opening Balance',
    voucherNo: `OB/${String(from.getDate()).padStart(2, '0')}/${String(from.getMonth() + 1).padStart(2, '0')}/${from.getFullYear()}`,
    accountName: accountFilter || 'All Accounts',
    particulars: 'Opening Balance',
    receipt: null,
    payment: null,
    referenceNo: '—',
    remarks: '—',
    balance: openingBalance,
  };

  let rows = [openingRow, ...fullRows];
  if (voucherType && voucherType !== 'All') {
    rows = rows.filter((r) => r.voucherType === voucherType);
  }

  const totals = rows.reduce((acc, r) => ({
    receipt: acc.receipt + (r.receipt || 0),
    payment: acc.payment + (r.payment || 0),
  }), { receipt: 0, payment: 0 });

  const receiptVsPayment = [
    { name: 'Total Receipts', value: Math.round(totalReceiptsFull), percent: (totalReceiptsFull + totalPaymentsFull) > 0 ? Math.round((totalReceiptsFull / (totalReceiptsFull + totalPaymentsFull)) * 1000) / 10 : 0 },
    { name: 'Total Payments', value: Math.round(totalPaymentsFull), percent: (totalReceiptsFull + totalPaymentsFull) > 0 ? Math.round((totalPaymentsFull / (totalReceiptsFull + totalPaymentsFull)) * 1000) / 10 : 0 },
  ];

  const trendDays = [];
  for (let i = 6; i >= 0; i -= 1) {
    const d = new Date(to);
    d.setDate(d.getDate() - i);
    d.setHours(23, 59, 59, 999);
    trendDays.push(d);
  }
  const pad2 = (n) => String(n).padStart(2, '0');
  const dayBookTrend = [];
  for (let i = 0; i < trendDays.length; i += 1) {
    const d = trendDays[i];
    // eslint-disable-next-line no-await-in-loop
    const balance = await balanceAsOf(d);
    dayBookTrend.push({ name: `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}`, value: Math.round(balance) });
  }

  // Top 5 Accounts by Transactions — counts (not amounts) per account
  // name, across the full chronological ledger for the period.
  const byAccountCount = {};
  fullRows.forEach((r) => { byAccountCount[r.accountName] = (byAccountCount[r.accountName] || 0) + 1; });
  const top5AccountsByTransactions = Object.entries(byAccountCount).sort((a, b) => b[1] - a[1]).slice(0, 5)
    .map(([name, value]) => ({ name, value }));

  // Distinct account names in use, for the "Account" filter dropdown —
  // there's no single resource listing every depositTo/payFromAccount
  // value ever used (some are HouseBank records, some are free-text
  // placeholders), so it's derived here from the actual ledger data.
  const [allDepositAccounts, allPayFromAccounts] = await Promise.all([
    prisma.collection.findMany({ where: { depositTo: { not: null } }, select: { depositTo: true }, distinct: ['depositTo'] }),
    prisma.supplierPayment.findMany({ where: { payFromAccount: { not: null } }, select: { payFromAccount: true }, distinct: ['payFromAccount'] }),
  ]);
  const accountOptions = Array.from(new Set([
    ...allDepositAccounts.map((r) => r.depositTo).filter(Boolean),
    ...allPayFromAccounts.map((r) => r.payFromAccount).filter(Boolean),
  ])).sort();

  res.json({
    success: true,
    data: {
      rows,
      totals,
      accountOptions,
      stats: {
        totalVouchers: collections.length + supplierPayments.length,
        totalReceipts: totalReceiptsFull,
        totalPayments: totalPaymentsFull,
        closingBalance,
        openingBalance,
      },
      receiptVsPayment,
      dayBookTrend,
      top5AccountsByTransactions,
    },
  });
}));

// Bank Book report — bespoke aggregation endpoint for the
// Reports > Cash/Bank Position > Bank Book page. Same real-data-only
// ledger builder as Cash Book/Day Book (Collection + SupplierPayment, no
// fabricated Expense/Journal entries), scoped to a single HouseBank "Bank
// Account" the same way Cash Book scopes to a Cash Account — every
// HouseBank record is offered as a candidate, since accountType is free
// text with no enum distinguishing "Cash" from "Bank". "Cleared Status"
// is a real lookup against BankReconciliationTransaction (the one place
// in this schema that actually tracks reconciliation), matched by
// voucherNo for source='System' rows; a voucher with no matching
// reconciliation-transaction record, or one whose status isn't
// 'Reconciled', is treated as "Uncleared" — nothing here is fabricated,
// it just reflects whether that voucher has ever been reconciled.
router.get('/banking/bank-book/report', auth(), asyncHandler(async (req, res) => {
  const {
    branch, bankAccount, fromDate, toDate, include, voucherType, openingBalanceAsOn, showClearedTransactions,
  } = req.query;

  const from = fromDate ? new Date(fromDate) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : new Date();
  to.setHours(23, 59, 59, 999);
  const obAsOn = openingBalanceAsOn ? new Date(openingBalanceAsOn) : new Date(from.getTime() - 1);
  obAsOn.setHours(23, 59, 59, 999);

  const accountFilter = bankAccount || '';
  const branchFilter = branch || '';

  async function balanceAsOf(asOfDate) {
    const houseBankWhere = {};
    if (accountFilter) houseBankWhere.OR = [{ accountName: accountFilter }, { bankName: accountFilter }];
    if (branchFilter) houseBankWhere.branchName = branchFilter;
    // SUMmed in the database rather than fetched and reduced — see the
    // identical note on Day Book's balanceAsOf above for why, and for why
    // Number(x._sum.field || 0) reproduces the old reduce exactly (`_sum` is
    // NULL, not 0, when no row matches). Branch filters (and row-level
    // branch-scopes) all three the same way Cash Book's
    // computeCashBalanceAsOf does — see that function's comment.
    const [houseBanks, collectionsAgg, paymentsAgg] = await Promise.all([
      prisma.houseBank.findMany({ where: withBranchScope(houseBankWhere, req, 'branchName'), select: { openingBalance: true } }),
      prisma.collection.aggregate({
        where: withBranchScope({
          status: 'Posted',
          receiptDate: { lte: asOfDate },
          ...(accountFilter ? { depositTo: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        _sum: { paymentAmount: true },
      }),
      prisma.supplierPayment.aggregate({
        where: withBranchScope({
          status: 'Posted',
          paymentDate: { lte: asOfDate },
          ...(accountFilter ? { payFromAccount: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        _sum: { paymentAmount: true },
      }),
    ]);
    const baseline = houseBanks.reduce((sum, b) => sum + Number(b.openingBalance || 0), 0);
    const receiptsTotal = Number(collectionsAgg._sum.paymentAmount || 0);
    const paymentsTotal = Number(paymentsAgg._sum.paymentAmount || 0);
    return baseline + receiptsTotal - paymentsTotal;
  }

  const openingBalance = await balanceAsOf(obAsOn);

  const includeReceipts = include !== 'Payments Only';
  const includePayments = include !== 'Receipts Only';

  const [collections, supplierPayments] = await Promise.all([
    includeReceipts
      ? prisma.collection.findMany({
        where: withBranchScope({
          status: 'Posted',
          receiptDate: { gte: from, lte: to },
          ...(accountFilter ? { depositTo: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        orderBy: { receiptDate: 'asc' },
      })
      : [],
    includePayments
      ? prisma.supplierPayment.findMany({
        where: withBranchScope({
          status: 'Posted',
          paymentDate: { gte: from, lte: to },
          ...(accountFilter ? { payFromAccount: accountFilter } : {}),
          ...(branchFilter ? { branch: branchFilter } : {}),
        }, req),
        orderBy: { paymentDate: 'asc' },
      })
      : [],
  ]);

  // Bulk cleared-status lookup: one query for every voucherNo this ledger
  // touches, rather than one query per row.
  const voucherNos = [...collections.map((c) => c.collectionNo), ...supplierPayments.map((p) => p.paymentNo)].filter(Boolean);
  const reconTxns = voucherNos.length
    ? await prisma.bankReconciliationTransaction.findMany({
      where: { source: 'System', voucherNo: { in: voucherNos } },
      select: { voucherNo: true, status: true },
    })
    : [];
  const clearedByVoucherNo = {};
  reconTxns.forEach((t) => {
    if (t.status === 'Reconciled') clearedByVoucherNo[t.voucherNo] = true;
  });

  const ledgerEntries = [
    ...collections.map((c) => ({
      date: c.receiptDate,
      voucherType: 'Receipt',
      voucherNo: c.collectionNo,
      particulars: c.notes || c.remarks || `Collection from ${c.customerName || 'Customer'}`,
      receipt: Number(c.paymentAmount || 0),
      payment: 0,
      chequeRefNo: c.instrumentNo || '—',
      clearedStatus: clearedByVoucherNo[c.collectionNo] ? 'Cleared' : 'Uncleared',
      remarks: c.remarks || '—',
    })),
    ...supplierPayments.map((p) => ({
      date: p.paymentDate,
      voucherType: 'Payment',
      voucherNo: p.paymentNo,
      particulars: p.notes || p.remarks || `Payment to ${p.supplierName || 'Supplier'}`,
      receipt: 0,
      payment: Number(p.paymentAmount || 0),
      chequeRefNo: p.instrumentNo || '—',
      clearedStatus: clearedByVoucherNo[p.paymentNo] ? 'Cleared' : 'Uncleared',
      remarks: p.remarks || '—',
    })),
  ].sort((a, b) => new Date(a.date) - new Date(b.date));

  let runningBalance = openingBalance;
  let unclearedNet = 0;
  const fullRows = ledgerEntries.map((e) => {
    runningBalance += e.receipt - e.payment;
    if (e.clearedStatus === 'Uncleared') unclearedNet += e.receipt - e.payment;
    return { ...e, balance: runningBalance };
  });

  const totalReceiptsFull = collections.reduce((sum, c) => sum + Number(c.paymentAmount || 0), 0);
  const totalPaymentsFull = supplierPayments.reduce((sum, p) => sum + Number(p.paymentAmount || 0), 0);
  const closingBalance = openingBalance + totalReceiptsFull - totalPaymentsFull;
  const unclearedBalance = unclearedNet;
  const clearedBalance = closingBalance - unclearedBalance;

  const openingRow = {
    date: from,
    voucherType: 'Opening Balance',
    voucherNo: `OB/${String(from.getDate()).padStart(2, '0')}/${String(from.getMonth() + 1).padStart(2, '0')}/${from.getFullYear()}`,
    particulars: 'Opening Balance',
    receipt: null,
    payment: null,
    chequeRefNo: '—',
    clearedStatus: 'Cleared',
    remarks: '—',
    balance: openingBalance,
  };

  // "Show Cleared Transactions": No narrows the ledger body down to only
  // still-pending (Uncleared) vouchers — a "what hasn't cleared yet" view
  // — Yes (the default) shows everything. This is independent of the
  // Voucher Type display filter below.
  let rows = [openingRow, ...fullRows];
  if (showClearedTransactions === 'No') {
    rows = rows.filter((r) => r.voucherType === 'Opening Balance' || r.clearedStatus === 'Uncleared');
  }
  if (voucherType && voucherType !== 'All') {
    rows = rows.filter((r) => r.voucherType === voucherType);
  }

  const totals = rows.reduce((acc, r) => ({
    receipt: acc.receipt + (r.receipt || 0),
    payment: acc.payment + (r.payment || 0),
  }), { receipt: 0, payment: 0 });

  const receiptVsPayment = [
    { name: 'Total Receipts', value: Math.round(totalReceiptsFull), percent: (totalReceiptsFull + totalPaymentsFull) > 0 ? Math.round((totalReceiptsFull / (totalReceiptsFull + totalPaymentsFull)) * 1000) / 10 : 0 },
    { name: 'Total Payments', value: Math.round(totalPaymentsFull), percent: (totalReceiptsFull + totalPaymentsFull) > 0 ? Math.round((totalPaymentsFull / (totalReceiptsFull + totalPaymentsFull)) * 1000) / 10 : 0 },
  ];

  const trendDays = [];
  for (let i = 6; i >= 0; i -= 1) {
    const d = new Date(to);
    d.setDate(d.getDate() - i);
    d.setHours(23, 59, 59, 999);
    trendDays.push(d);
  }
  const pad2 = (n) => String(n).padStart(2, '0');
  const bankBalanceTrend = [];
  for (let i = 0; i < trendDays.length; i += 1) {
    const d = trendDays[i];
    // eslint-disable-next-line no-await-in-loop
    const balance = await balanceAsOf(d);
    bankBalanceTrend.push({ name: `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}`, value: Math.round(balance) });
  }

  // Top 5 Transactions (by amount), across the full chronological ledger
  // for the period.
  const top5Transactions = [...fullRows].sort((a, b) => (b.receipt + b.payment) - (a.receipt + a.payment)).slice(0, 5)
    .map((r) => ({ name: r.particulars, value: Math.round(r.receipt + r.payment) }));

  res.json({
    success: true,
    data: {
      rows,
      totals,
      stats: {
        openingBalance,
        totalReceipts: totalReceiptsFull,
        totalPayments: totalPaymentsFull,
        closingBalance,
        noOfTransactions: collections.length + supplierPayments.length,
        clearedBalance,
        unclearedBalance,
      },
      receiptVsPayment,
      bankBalanceTrend,
      top5Transactions,
    },
  });
}));

// Deposit Register report — bespoke aggregation endpoint for the
// Reports > Cash/Bank Position > Deposit Register page. The mockup for
// this report was designed around Fixed/Recurring Deposit accounts. There
// is still no separate term-deposit/investment model in this schema — the
// only "Deposit" entity is BankDeposit/DepositItem, a deposit slip
// recording Cash/Cheque/Bank Transfer/Mixed amounts paid into a bank
// account — but interestRate/maturityDate/maturityAmount now exist as
// nullable fields on BankDeposit (captured in Deposit Entry), so the
// report shows them as real stored values. They are null on ordinary
// deposit slips and on everything recorded before those fields were added,
// and the page renders null as "—" rather than 0. Note "Deposit Type" here
// is still the slip's payment composition (Cash/Cheque/Bank
// Transfer/Mixed), not an FD/RD product type. "Currency" and "Show
// Cancelled Deposits" are no-ops — single implicit currency, and
// BankDeposit only ever has Draft/Posted status. "Branch" DOES filter for
// real: BankDeposit/SupplierPayment carry their own real `branch` column
// and HouseBank its own `branchName` (same fix as Cash Book/Day Book/Bank
// Book above — see computeCashBalanceAsOf's comment), and every query below
// also goes through withBranchScope() for the signed-in user's own branch
// grants.
//
// Opening/Closing Balance and Total Withdrawals are computed on this
// report's own cash-movement model so the five headline cards actually
// tie: Opening + Total Deposits - Total Withdrawals = Closing. Money in
// is BankDeposit (the deposit slips this report lists), money out is
// Posted SupplierPayment.payFromAccount — the only outflow against a bank
// account anywhere in this schema. The baseline is HouseBank.openingBalance
// for the account(s) in scope, same as Bank Book. Note this deliberately
// differs from Bank Book's ledger, which treats Collection as the inflow;
// counting both Collections and their BankDeposit slips would double-count
// the same money, and on this page the deposit slips are the subject.
// Withdrawals are always Posted-only — a Draft payment hasn't moved money —
// whereas deposits follow the Include filter, so a "Draft Only" view shows
// draft deposit volume against real withdrawals.
router.get('/banking/deposit-register/report', auth(), asyncHandler(async (req, res) => {
  const {
    branch, account, depositType, fromDate, toDate, include,
  } = req.query;

  const from = fromDate ? new Date(fromDate) : new Date(new Date().getFullYear(), new Date().getMonth(), 1);
  from.setHours(0, 0, 0, 0);
  const to = toDate ? new Date(toDate) : new Date();
  to.setHours(23, 59, 59, 999);

  let statusWhere = { in: ['Posted', 'Draft'] };
  if (include === 'Posted Only') statusWhere = 'Posted';
  else if (include === 'Draft Only') statusWhere = 'Draft';

  const depositWhere = {
    depositDate: { gte: from, lte: to },
    status: statusWhere,
  };
  if (account) depositWhere.depositTo = account;
  if (depositType) depositWhere.depositType = depositType;
  if (branch) depositWhere.branch = branch;

  const deposits = await prisma.bankDeposit.findMany({
    where: withBranchScope(depositWhere, req),
    include: { items: true },
    orderBy: { depositDate: 'asc' },
  });

  const rows = deposits.map((d) => {
    const items = d.items || [];
    const referenceNo = items.map((i) => i.instrumentNo).filter(Boolean).join(', ') || '—';
    return {
      id: d.id,
      date: d.depositDate,
      depositNo: d.depositNo,
      accountName: d.depositTo || '—',
      depositType: d.depositType || '—',
      amount: Number(d.totalDepositAmount || 0),
      // Term-deposit fields — null on any deposit slip that isn't a
      // Fixed/Recurring Deposit, and on every slip recorded before these
      // fields existed. The page renders those as "—" rather than 0, so a
      // missing rate is never mistaken for a 0% one.
      interestRate: d.interestRate == null ? null : Number(d.interestRate),
      maturityDate: d.maturityDate,
      maturityAmount: d.maturityAmount == null ? null : Number(d.maturityAmount),
      referenceNo,
      remarks: d.remarks || '—',
    };
  });

  const totals = rows.reduce((acc, r) => ({
    amount: acc.amount + r.amount,
    maturityAmount: acc.maturityAmount + (r.maturityAmount || 0),
  }), { amount: 0, maturityAmount: 0 });

  // Deposit Type Summary — donut over the exact depositType values in use.
  const byTypeValue = {};
  rows.forEach((r) => { byTypeValue[r.depositType] = (byTypeValue[r.depositType] || 0) + r.amount; });
  const typeGrandTotal = totals.amount || 1;
  const depositTypeSummary = Object.entries(byTypeValue).sort((a, b) => b[1] - a[1])
    .map(([name, value]) => ({ name, value: Math.round(value), percent: Math.round((value / typeGrandTotal) * 1000) / 10 }));

  const cashDeposits = byTypeValue.Cash || 0;
  const chequeDeposits = byTypeValue.Cheque || 0;
  const bankTransferDeposits = (byTypeValue['Bank Transfer'] || 0) + (byTypeValue.Mixed || 0);

  // Deposit Trend (Last 7 Days) — always the 7 calendar days ending at
  // `to`, regardless of the selected Period Range preset, queried
  // independently of `rows` so a short period range doesn't truncate it —
  // same approach as the other Cash/Bank Position reports.
  const trendDays = [];
  for (let i = 6; i >= 0; i -= 1) {
    const d = new Date(to);
    d.setDate(d.getDate() - i);
    d.setHours(0, 0, 0, 0);
    trendDays.push(d);
  }
  const trendFrom = trendDays[0];
  const trendWhere = { depositDate: { gte: trendFrom, lte: to }, status: statusWhere };
  if (account) trendWhere.depositTo = account;
  if (depositType) trendWhere.depositType = depositType;
  if (branch) trendWhere.branch = branch;
  const trendDeposits = await prisma.bankDeposit.findMany({ where: withBranchScope(trendWhere, req), select: { depositDate: true, totalDepositAmount: true } });
  const pad2 = (n) => String(n).padStart(2, '0');
  const depositTrend = trendDays.map((d) => {
    const dayTotal = trendDeposits
      .filter((r) => r.depositDate && new Date(r.depositDate).toDateString() === d.toDateString())
      .reduce((sum, r) => sum + Number(r.totalDepositAmount || 0), 0);
    return { name: `${pad2(d.getDate())}/${pad2(d.getMonth() + 1)}`, value: Math.round(dayTotal) };
  });

  // Top 5 Accounts by Deposit Amount.
  const byAccountValue = {};
  rows.forEach((r) => { byAccountValue[r.accountName] = (byAccountValue[r.accountName] || 0) + r.amount; });
  const top5AccountsByDeposit = Object.entries(byAccountValue).sort((a, b) => b[1] - a[1]).slice(0, 5)
    .map(([name, value]) => ({ name, value: Math.round(value) }));

  // Opening Balance — the account balance the instant before `from`:
  // the HouseBank baseline plus every deposit and minus every Posted
  // withdrawal dated on or before that point.
  const openingAsOf = new Date(from.getTime() - 1);
  const houseBankWhere = account ? { OR: [{ accountName: account }, { bankName: account }] } : {};
  if (branch) houseBankWhere.branchName = branch;
  const [houseBanks, priorDeposits, priorWithdrawals, periodWithdrawals] = await Promise.all([
    prisma.houseBank.findMany({ where: withBranchScope(houseBankWhere, req, 'branchName'), select: { openingBalance: true } }),
    prisma.bankDeposit.findMany({
      where: withBranchScope({
        depositDate: { lte: openingAsOf },
        status: statusWhere,
        ...(account ? { depositTo: account } : {}),
        ...(depositType ? { depositType } : {}),
        ...(branch ? { branch } : {}),
      }, req),
      select: { totalDepositAmount: true },
    }),
    prisma.supplierPayment.findMany({
      where: withBranchScope({
        status: 'Posted',
        paymentDate: { lte: openingAsOf },
        ...(account ? { payFromAccount: account } : {}),
        ...(branch ? { branch } : {}),
      }, req),
      select: { paymentAmount: true },
    }),
    prisma.supplierPayment.findMany({
      where: withBranchScope({
        status: 'Posted',
        paymentDate: { gte: from, lte: to },
        ...(account ? { payFromAccount: account } : {}),
        ...(branch ? { branch } : {}),
      }, req),
      select: { paymentAmount: true },
    }),
  ]);

  const baseline = houseBanks.reduce((sum, b) => sum + Number(b.openingBalance || 0), 0);
  const priorDepositTotal = priorDeposits.reduce((sum, d) => sum + Number(d.totalDepositAmount || 0), 0);
  const priorWithdrawalTotal = priorWithdrawals.reduce((sum, p) => sum + Number(p.paymentAmount || 0), 0);
  const openingBalance = baseline + priorDepositTotal - priorWithdrawalTotal;
  const totalWithdrawals = periodWithdrawals.reduce((sum, p) => sum + Number(p.paymentAmount || 0), 0);
  const closingBalance = openingBalance + totals.amount - totalWithdrawals;

  res.json({
    success: true,
    data: {
      rows,
      totals,
      stats: {
        openingBalance,
        totalDeposits: totals.amount,
        totalWithdrawals,
        closingBalance,
        noOfDeposits: rows.length,
        noOfWithdrawals: periodWithdrawals.length,
        cashDeposits,
        chequeDeposits,
        bankTransferDeposits,
      },
      depositTypeSummary,
      depositTrend,
      top5AccountsByDeposit,
    },
  });
}));

module.exports = router;
// Exposed so other routes can reuse the exact same on-hand valuation this
// report renders -- e.g. Dashboard's "Total Inventory Value" card mirrors
// this function's stats.totalStockValue rather than re-deriving its own
// figure (see routes/dashboard.js).
module.exports.buildAvailableBalanceReportData = buildAvailableBalanceReportData;
// Exposed so routes/notifications.js's Notification-bell approve endpoint can
// post a Request-linked Stock Transfer's stock/G/L the moment its Stock
// Transfer Request is approved — see this function's own doc comment above.
module.exports.syncStockTransferApprovalOnRequestApproved = syncStockTransferApprovalOnRequestApproved;
